    // --- Yleiset UI funktiot ---
    window.updateDynamicTexts = function() {
        if (!window.manuscriptData) return;
        const title = window.manuscriptData.title || "Nimetön";

        syncTopBarContextForView(currentViewId);
        const sidebarCurrentTitle = document.getElementById('sidebar-current-title');
        if (sidebarCurrentTitle) {
            sidebarCurrentTitle.textContent = title;
        }
        const analysis = window.manuscriptData.analysis || {};
        const sidebarStyle = document.getElementById('sidebar-style');
        const sidebarVocab = document.getElementById('sidebar-vocab');
        if (sidebarStyle) {
            sidebarStyle.textContent = hasSavedAnalysis(analysis) ? 'Analyysi valmis' : 'Odottaa analyysiä...';
            sidebarStyle.style.color = hasSavedAnalysis(analysis) ? 'var(--ai-gradient-start)' : '';
        }
        if (sidebarVocab) {
            sidebarVocab.textContent = analysis.glossary ? 'Valmis sanasto' : '-';
            sidebarVocab.style.color = analysis.glossary ? 'var(--ai-gradient-start)' : '';
        }
        
        const th = document.getElementById('toimitus-book-title');
        if (th) th.innerHTML = `${title} <span class="badge">Luonnos</span>`;
        
        document.querySelectorAll('.view-section .header-info p').forEach(p => {
            if (p.id === "toimitus-book-chapter") return; 
            let txt = p.textContent;
            if (txt.startsWith("Käsikirjoitus:") || txt.startsWith("Käsikirjoitukseen:")) {
                let prefix = txt.startsWith("Käsikirjoitus:") ? "Käsikirjoitus: " : "Käsikirjoitukseen: ";
                let suffixMatch = txt.match(/(\(.*)/);
                let suffix = suffixMatch ? suffixMatch[0] : "";
                p.textContent = demoUiText(prefix + title + " " + suffix);
            }
        });
        applyShowcaseTerminology(document.getElementById(currentViewId));
    };

	    // --- 5. Kuvitus Logic ---
    const VISUAL_BATCH_REQUEST_DELAY_MS = 10000;
    const VISUAL_BATCH_RETRY_DELAY_MS = 10000;
    const VISUAL_BATCH_MAX_REQUEST_ATTEMPTS = 2;
    const VISUAL_MAX_IMAGES_PER_RUN = 100;
    const VISUAL_BATCH_POLL_INTERVAL_MS = 15000;
    const VISUAL_ESTIMATE_DEBOUNCE_MS = 350;
    const visualKindDefinitions = [
        { value: 'chapter_opening', label: 'Luvun tai osion avauskuva' },
        { value: 'scene', label: 'Kohtauskuva' },
        { value: 'character', label: 'Henkilökuva' },
        { value: 'location', label: 'Paikkakuva' },
        { value: 'object', label: 'Esine tai symboli' },
        { value: 'atmosphere', label: 'Tunnelmakuva' },
        { value: 'marketing', label: 'Markkinointikuva' },
    ];
    const visualAspectRatioDefinitions = [
        { value: '3:4', label: 'Pysty 3:4' },
        { value: '16:9', label: 'Vaaka 16:9' },
        { value: '1:1', label: 'Neliö 1:1' },
        { value: '4:3', label: 'Vaaka 4:3' },
        { value: '9:16', label: 'Kapea pysty 9:16' },
    ];
    const infographicTypeLabels = {
        timeline: 'Aikajana',
        character_map: 'Henkilökartta',
        story_arc: 'Juonen kaari',
        location_map: 'Paikkakartta',
        fact_sheet: 'Fakta- ja teemakooste',
    };
    const GRAPHIC_ASSET_PAGE_SIZE = 12;

    function activeGraphicProjectId() {
        return String(window.manuscriptData?.id || '');
    }

    function visualBatchUsesActiveProject(batchRun = visualBatchController) {
        return Boolean(batchRun && batchRun.projectId === activeGraphicProjectId());
    }

    function requestVisualBatchStop(message, projectChanged = false) {
        const batchRun = visualBatchController;
        if (!batchRun) return false;
        if (projectChanged) batchRun.projectChanged = true;
        if (!batchRun.stopRequested) batchRun.stopRequested = true;
        if (visualStopBtn) {
            visualStopBtn.disabled = true;
            visualStopBtn.textContent = 'Pysäytetään…';
        }
        if (message) setVisualStatus(message);
        syncGraphicsControls();
        return true;
    }

    function requestVisualBatchStopForProjectChange(nextProjectId) {
        const batchRun = visualBatchController;
        if (!batchRun || batchRun.projectId === String(nextProjectId || '')) return false;
        return requestVisualBatchStop(
            'Projekti vaihtui. Käynnissä oleva kuva valmistuu vanhaan projektiin, eikä uusia pyyntöjä aloiteta.',
            true,
        );
    }

    function resetGraphicAssetPagination() {
        Object.values(graphicAssetPagination).forEach(state => {
            state.nextCursor = null;
            state.loading = false;
        });
        updateGraphicLoadMoreButtons();
    }

    function invalidateGraphicAssetCache(render = true) {
        graphicAssetsLoadSequence += 1;
        graphicAssetsLoadedProjectId = null;
        graphicAssetPreviewObserver?.disconnect();
        graphicAssetDetailRequests.clear();
        resetGraphicAssetPagination();
        currentGraphicAssets = [];
        if (render) renderGraphicAssets([]);
    }

    function setVisualStatus(message, isError = false) {
        if (!visualStatus) return;
        visualStatus.textContent = demoPriceSafeText(
            message || '',
            isError ? 'Kuvatoimintoa ei voitu suorittaa. Yritä uudelleen.' : 'Kuvaerän tila päivittyi.'
        );
        visualStatus.classList.toggle('is-error', Boolean(isError));
    }

    function selectedVisualModel() {
        const value = String(visualModelSelect?.value || '');
        return imageModels.find(model => `${model.provider}:${model.model_name}` === value)
            || imageModels.find(model => String(model.model_name || '') === value)
            || null;
    }

    function visualExecutionMode() {
        return visualExecutionModeInputs.find(input => input.checked)?.value === 'batch' ? 'batch' : 'direct';
    }

    function visualVariantCount() {
        const value = Math.min(10, Math.max(1, Number(visualVariantsPerPrompt?.value) || 1));
        if (visualVariantsPerPrompt && String(value) !== visualVariantsPerPrompt.value) {
            visualVariantsPerPrompt.value = String(value);
        }
        return value;
    }

    function visualSelectedImageSize() {
        return String(visualImageSize?.value || '1K').trim().toUpperCase() || '1K';
    }

    function visualModelSupportsBatch(model = selectedVisualModel()) {
        if (!model || String(model.model_name || '').toLowerCase().startsWith('imagen-')) return false;
        return model.supports_batch === true;
    }

    function visualSupportedImageSizes(model = selectedVisualModel()) {
        const configured = Array.isArray(model?.supported_image_sizes) ? model.supported_image_sizes : [];
        const normalized = configured
            .map(value => {
                const size = String(value || '').trim().toUpperCase();
                return size === '512PX' || size === '512 PX' ? '512' : size;
            })
            .filter((value, index, values) => ['512', '1K', '2K', '4K'].includes(value) && values.indexOf(value) === index);
        return normalized.length ? normalized : ['1K'];
    }

    function syncVisualModelCapabilities() {
        const model = selectedVisualModel();
        const sizes = visualSupportedImageSizes(model);
        if (visualImageSize) {
            const current = visualSelectedImageSize();
            visualImageSize.innerHTML = sizes.map(size => `<option value="${size}">${size === '512' ? '512 px' : size}</option>`).join('');
            visualImageSize.value = sizes.includes(current) ? current : sizes[0];
        }
        const batchInput = visualExecutionModeInputs.find(input => input.value === 'batch');
        const directInput = visualExecutionModeInputs.find(input => input.value === 'direct');
        const batchSupported = visualModelSupportsBatch(model);
        if (batchInput) batchInput.disabled = !batchSupported;
        visualBatchModeOption?.classList.toggle('is-disabled', !batchSupported);
        if (!batchSupported && batchInput?.checked && directInput) directInput.checked = true;
        if (visualRunModeNote) {
            visualRunModeNote.textContent = !model
                ? 'Valitse kuvamalli nähdäksesi käytettävissä olevat ajotavat.'
                : batchSupported
                    ? 'Valittu malli tukee taustalla jatkuvaa Gemini-eräajoa. Eräajon tavoiteaika on enintään 24 tuntia.'
                    : 'Valittu malli tukee vain suoraa ajoa. Imagen-malleja ei voi lähettää Gemini-eräajoon.';
        }
    }

    function visualPlannedImageCount() {
        const rows = collectVisualBatchRows({ expandVariants: false });
        return rows.length * visualVariantCount();
    }

    function visualCurrency(value, currency, maximumFractionDigits = 3) {
        const number = Number(value);
        if (!Number.isFinite(number)) return '–';
        try {
            return new Intl.NumberFormat('fi-FI', {
                style: 'currency',
                currency,
                minimumFractionDigits: 2,
                maximumFractionDigits,
            }).format(number);
        } catch (error) {
            return `${number.toFixed(2)} ${currency}`;
        }
    }

    function visualEstimatePayload() {
        const model = selectedVisualModel();
        return {
            model_name: String(model?.model_name || visualModelSelect?.value || ''),
            execution_mode: visualExecutionMode(),
            image_size: visualSelectedImageSize(),
            image_count: visualPlannedImageCount(),
        };
    }

    function visualEstimateKey(projectId = activeGraphicProjectId(), payload = visualEstimatePayload()) {
        return JSON.stringify({ project_id: String(projectId || ''), ...payload });
    }

    function renderVisualEstimate(data = null, message = '', isError = false) {
        const count = Number(data?.image_count ?? visualPlannedImageCount());
        if (visualEstimateCount) visualEstimateCount.textContent = count ? formatNumber(count) : '–';
        if (visualEstimateUnit) visualEstimateUnit.textContent = showcaseDemoMode ? '–' : data ? visualCurrency(data.unit_cost_eur, 'EUR', 4) : '–';
        if (visualEstimateTotal) visualEstimateTotal.textContent = showcaseDemoMode ? '–' : data ? visualCurrency(data.estimated_cost_eur, 'EUR', 3) : '–';
        if (visualEstimateQuota) {
            const remaining = Number(data?.monthly_remaining);
            const limit = Number(data?.monthly_limit);
            visualEstimateQuota.textContent = data?.quota_enforced === false
                ? 'Ei käyttäjäkohtaista rajaa'
                : Number.isFinite(remaining)
                ? `${formatNumber(Math.max(0, remaining))}${Number.isFinite(limit) ? ` / ${formatNumber(limit)}` : ''}`
                : '–';
        }
        if (visualEstimateNote) {
            if (showcaseDemoMode) {
                visualEstimateNote.textContent = '';
                visualEstimateNote.classList.remove('is-error');
                return;
            }
            const modeLabel = data?.execution_mode === 'batch' ? 'Gemini-eräajo' : 'suora ajo';
            const defaultMessage = data
                ? `${data.model_display_name || data.model_name || 'Valittu malli'} · ${data.image_size || visualSelectedImageSize()} · ${modeLabel}. ${data.disclaimer || ''}`.trim()
                : 'Valitse projekti ja kuvamalli, niin hinta-arvio päivittyy.';
            visualEstimateNote.textContent = message || defaultMessage;
            visualEstimateNote.classList.toggle('is-error', Boolean(isError));
        }
    }

    async function updateVisualEstimate() {
        window.clearTimeout(visualEstimateTimer);
        visualEstimateTimer = null;
        const projectId = activeGraphicProjectId();
        const payload = visualEstimatePayload();
        const key = visualEstimateKey(projectId, payload);
        if (!projectId || !payload.model_name) {
            latestVisualEstimate = null;
            latestVisualEstimateKey = '';
            renderVisualEstimate(null);
            syncGraphicsControls();
            return null;
        }
        if (!payload.image_count) {
            latestVisualEstimate = null;
            latestVisualEstimateKey = '';
            renderVisualEstimate(null, 'Lisää vähintään yksi varsinainen luku hinta-arviota varten.', true);
            syncGraphicsControls();
            return null;
        }
        if (payload.image_count > VISUAL_MAX_IMAGES_PER_RUN) {
            latestVisualEstimate = null;
            latestVisualEstimateKey = key;
            renderVisualEstimate(null, `Kuvaerässä voi olla enintään ${VISUAL_MAX_IMAGES_PER_RUN} kuvaa. Vähennä vaihtoehtojen määrää.`, true);
            syncGraphicsControls();
            return null;
        }
        visualEstimateController?.abort();
        const controller = new AbortController();
        visualEstimateController = controller;
        renderVisualEstimate(null, 'Lasketaan valitun kuvaerän hinta-arviota…');
        try {
            const response = await apiFetch(`/api/projects/${projectId}/visual-image-jobs/estimate`, {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify(payload),
                signal: controller.signal,
            });
            const data = await response.json().catch(() => null);
            if (!response.ok) throw new Error(data?.detail || 'Kuvaerän hinta-arviota ei saatu laskettua.');
            if (controller.signal.aborted || visualEstimateKey() !== key) return null;
            latestVisualEstimate = data;
            latestVisualEstimateKey = key;
            const exceedsBatchMaximum = payload.execution_mode === 'batch'
                && Number(data?.max_batch_images) > 0
                && payload.image_count > Number(data.max_batch_images);
            const exceedsQuota = data?.quota_enforced !== false
                && Number.isFinite(Number(data?.monthly_remaining))
                && payload.image_count > Number(data.monthly_remaining);
            if (exceedsBatchMaximum) {
                renderVisualEstimate(data, `Valittu erä sisältää ${payload.image_count} kuvaa. Mallin eräajoraja on ${data.max_batch_images} kuvaa.`, true);
            } else if (exceedsQuota) {
                renderVisualEstimate(data, `Kuvaerä tarvitsee ${payload.image_count} kuvapyyntöä, mutta kuukausikiintiötä on jäljellä ${Math.max(0, Number(data.monthly_remaining))}.`, true);
            } else {
                renderVisualEstimate(data);
            }
            syncGraphicsControls();
            return data;
        } catch (error) {
            if (error?.name === 'AbortError') return null;
            if (visualEstimateKey() !== key) return null;
            latestVisualEstimate = null;
            latestVisualEstimateKey = '';
            renderVisualEstimate(null, networkFailureMessage(error), true);
            syncGraphicsControls();
            return null;
        } finally {
            if (visualEstimateController === controller) visualEstimateController = null;
        }
    }

    function scheduleVisualEstimate(options = {}) {
        window.clearTimeout(visualEstimateTimer);
        renderVisualEstimate(latestVisualEstimateKey === visualEstimateKey() ? latestVisualEstimate : null);
        visualEstimateTimer = window.setTimeout(updateVisualEstimate, options.immediate ? 0 : VISUAL_ESTIMATE_DEBOUNCE_MS);
        syncGraphicsControls();
    }

    function setInfographicStatus(message, isError = false) {
        if (!infographicStatus) return;
        infographicStatus.textContent = String(message || '');
        infographicStatus.classList.toggle('is-error', Boolean(isError));
    }

    function automaticGraphicsHtmlCover() {
        const validCover = item => Boolean(item?.id && item?.data_url);
        return currentCoverImages.find(item => item.asset_type === 'cover_image' && validCover(item))
            || currentCoverImages.find(item => item.asset_type === 'full_cover_image' && validCover(item))
            || null;
    }

    function setGraphicsHtmlStatus(message, isError = false) {
        const status = document.getElementById('graphics-html-status');
        if (!status) return;
        status.textContent = String(message || '');
        status.classList.toggle('is-error', Boolean(isError));
    }

    function htmlPresentationFilename(value) {
        const filename = String(value || '').trim() || 'kirjan-esittely.html';
        return filename
            .replace(/markkinointisivu/gi, 'esittely')
            .replace(/markkinointi(?=\.html?$)/gi, 'esittely');
    }

    function decodeHtmlDataUrl(dataUrl) {
        const value = String(dataUrl || '');
        const separator = value.indexOf(',');
        if (separator < 0 || !/^data:text\/html(?:;[^,]*)?$/i.test(value.slice(0, separator))) return '';
        const metadata = value.slice(0, separator);
        const payload = value.slice(separator + 1);
        try {
            if (!/;base64(?:;|$)/i.test(metadata)) return decodeURIComponent(payload);
            const binary = window.atob(payload);
            const bytes = Uint8Array.from(binary, character => character.charCodeAt(0));
            return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
        } catch (error) {
            return '';
        }
    }

    function setHtmlPreviewPlaceholder(empty, title, copy) {
        if (!empty) return;
        const titleElement = empty.querySelector('strong');
        const copyElement = empty.querySelector('p');
        if (titleElement) titleElement.textContent = title;
        if (copyElement) copyElement.textContent = copy;
        empty.hidden = false;
    }

    function clearHtmlPreviewFrame(frame) {
        if (!frame) return;
        window.clearTimeout(frame._skriptlabPreviewFallbackTimer);
        frame._skriptlabPreviewFallbackTimer = null;
        frame.onload = null;
        frame.onerror = null;
        frame.removeAttribute('src');
        frame.removeAttribute('srcdoc');
        frame.hidden = true;
    }

    function renderHtmlDataUrlPreview(frame, empty, dataUrl, filename) {
        clearHtmlPreviewFrame(frame);
        const source = decodeHtmlDataUrl(dataUrl);
        const readyTitle = 'HTML-esittely on valmis';
        const fallbackCopy = `${filename} on valmis ladattavaksi. Esikatselua ei voitu avata tässä selaimessa.`;
        if (!frame || !source) {
            setHtmlPreviewPlaceholder(empty, readyTitle, fallbackCopy);
            return false;
        }

        setHtmlPreviewPlaceholder(empty, readyTitle, 'Avataan esikatselua…');
        const showFallback = () => {
            window.clearTimeout(frame._skriptlabPreviewFallbackTimer);
            frame._skriptlabPreviewFallbackTimer = null;
            frame.onload = null;
            frame.onerror = null;
            frame.hidden = true;
            setHtmlPreviewPlaceholder(empty, readyTitle, fallbackCopy);
        };
        frame.onload = () => {
            window.clearTimeout(frame._skriptlabPreviewFallbackTimer);
            frame._skriptlabPreviewFallbackTimer = null;
            frame.onload = null;
            frame.onerror = null;
            frame.hidden = false;
            if (empty) empty.hidden = true;
        };
        frame.onerror = showFallback;
        frame._skriptlabPreviewFallbackTimer = window.setTimeout(showFallback, 4000);
        frame.srcdoc = source;
        return true;
    }

    function clearGraphicsHtmlResult() {
        latestGraphicsHtmlPage = null;
        clearHtmlPreviewFrame(graphicsHtmlPreviewFrame);
        if (graphicsHtmlPreviewEmpty) {
            graphicsHtmlPreviewEmpty.hidden = false;
            graphicsHtmlPreviewEmpty.classList.remove('is-working');
        }
        if (graphicsHtmlPreviewEmptyTitle) graphicsHtmlPreviewEmptyTitle.textContent = 'Esikatselu avautuu tähän';
        if (graphicsHtmlPreviewEmptyCopy) {
            graphicsHtmlPreviewEmptyCopy.textContent = 'Luo luonnos yhdellä painikkeella, kun projektilla on etukansi tai koko kansi.';
        }
        if (graphicsHtmlDownloadBtn) graphicsHtmlDownloadBtn.disabled = true;
        if (graphicsHtmlResultName) graphicsHtmlResultName.textContent = 'Ei vielä luotua tiedostoa';
        if (graphicsHtmlResultMeta) {
            graphicsHtmlResultMeta.textContent = 'Yhden tiedoston HTML · upotetut kuvat · responsiivinen';
        }
        if (graphicsHtmlBrowserName) graphicsHtmlBrowserName.textContent = 'kirjan-esittely.html';
    }

    function renderGraphicsHtmlWorkspace() {
        const project = window.manuscriptData;
        const cover = automaticGraphicsHtmlCover();
        if (latestGraphicsHtmlPage && (
            String(latestGraphicsHtmlPage.projectId) !== String(project?.id || '')
            || String(latestGraphicsHtmlPage.coverAssetId) !== String(cover?.id || '')
        )) clearGraphicsHtmlResult();

        if (graphicsHtmlCover) {
            graphicsHtmlCover.innerHTML = cover?.data_url
                ? `<img src="${cover.data_url}" alt="${escapeHtml(cover.title || 'HTML-luonnoksen kansi')}">`
                : '<span>KANSI</span>';
        }
        if (graphicsHtmlCoverTitle) {
            graphicsHtmlCoverTitle.textContent = cover?.title || 'Ei vielä kansikuvaa';
        }
        if (graphicsHtmlCoverDetail) {
            graphicsHtmlCoverDetail.textContent = cover
                ? 'Uusin kelvollinen etu- tai koko kansi käytetään luonnoksessa.'
                : 'Luo tai tuo ensin etukansi Kansi-välilehdellä.';
        }

        const editable = Boolean(project && canEditProject(project));
        const ready = Boolean(project?.id && cover?.id && editable);
        if (graphicsHtmlGenerateBtn) {
            graphicsHtmlGenerateBtn.disabled = graphicsHtmlGenerating || !ready;
            graphicsHtmlGenerateBtn.textContent = graphicsHtmlGenerating ? 'Luodaan HTML-luonnosta…' : 'Luo HTML-luonnos';
        }
        if (graphicsHtmlPreviewEmpty) {
            graphicsHtmlPreviewEmpty.classList.toggle('is-working', graphicsHtmlGenerating);
        }
        if (graphicsHtmlGenerating) {
            if (graphicsHtmlPreviewEmptyTitle) graphicsHtmlPreviewEmptyTitle.textContent = 'Luonnosta muodostetaan…';
            if (graphicsHtmlPreviewEmptyCopy) {
                graphicsHtmlPreviewEmptyCopy.textContent = 'Tekstit kootaan analyysistä ja kontekstimuistista turvalliseen HTML-pohjaan.';
            }
            return;
        }
        if (graphicsHtmlPreviewEmptyTitle && !latestGraphicsHtmlPage) {
            graphicsHtmlPreviewEmptyTitle.textContent = 'Esikatselu avautuu tähän';
        }
        if (graphicsHtmlPreviewEmptyCopy && !latestGraphicsHtmlPage) {
            graphicsHtmlPreviewEmptyCopy.textContent = 'Luo luonnos yhdellä painikkeella, kun projektilla on etukansi tai koko kansi.';
        }

        if (!project) {
            setGraphicsHtmlStatus('Valitse ensin käsikirjoitus.', true);
        } else if (!project.id) {
            setGraphicsHtmlStatus('Tallenna käsikirjoitus ennen HTML-luonnoksen luontia.', true);
        } else if (!editable) {
            setGraphicsHtmlStatus('HTML-luonnoksen luonti vaatii projektin muokkausoikeuden.', true);
        } else if (!cover) {
            setGraphicsHtmlStatus('Luo tai tuo ensin etukansi Kansi-välilehdellä.', true);
        } else if (latestGraphicsHtmlPage) {
            setGraphicsHtmlStatus('HTML-luonnos on valmis katseltavaksi ja ladattavaksi.');
        } else {
            setGraphicsHtmlStatus('Kansi on valmis. Luo HTML-luonnos yhdellä painikkeella.');
        }
    }

    async function generateGraphicsHtmlDraft() {
        const project = window.manuscriptData;
        const cover = automaticGraphicsHtmlCover();
        if (!project?.id) {
            setGraphicsHtmlStatus('Valitse ja tallenna käsikirjoitus ensin.', true);
            return;
        }
        if (!canEditProject(project)) {
            setGraphicsHtmlStatus('HTML-luonnoksen luonti vaatii projektin muokkausoikeuden.', true);
            return;
        }
        if (!cover?.id) {
            setGraphicsHtmlStatus('Luo tai tuo ensin etukansi Kansi-välilehdellä.', true);
            return;
        }

        clearGraphicsHtmlResult();
        graphicsHtmlGenerating = true;
        setGraphicsHtmlStatus('Muodostetaan HTML-luonnosta analyysistä, kontekstimuistista, kansikuvasta ja henkilökartasta…');
        renderGraphicsHtmlWorkspace();

        let finalStatus = null;
        try {
            const response = await apiFetch('/api/marketing/landing-page', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    project_id: project.id,
                    cover_asset_id: Number(cover.id)
                })
            });
            const data = await response.json().catch(() => null);
            if (!response.ok) throw new Error(data?.detail || 'HTML-luonnoksen luonti epäonnistui.');
            if (!data?.page?.data_url) throw new Error('Valmiin HTML-tiedoston sisältöä ei saatu.');
            if (
                String(window.manuscriptData?.id || '') !== String(project.id)
                || String(automaticGraphicsHtmlCover()?.id || '') !== String(cover.id)
            ) return;

            latestGraphicsHtmlPage = {
                projectId: project.id,
                coverAssetId: cover.id,
                dataUrl: data.page.data_url,
                filename: htmlPresentationFilename(data.filename)
            };
            if (graphicsHtmlDownloadBtn) graphicsHtmlDownloadBtn.disabled = false;
            if (graphicsHtmlResultName) graphicsHtmlResultName.textContent = latestGraphicsHtmlPage.filename;
            if (graphicsHtmlBrowserName) graphicsHtmlBrowserName.textContent = latestGraphicsHtmlPage.filename;
            if (graphicsHtmlResultMeta) {
                const mapMeta = data.character_map_included ? 'henkilökartta mukana' : 'ei tallennettua henkilökarttaa';
                graphicsHtmlResultMeta.textContent = `Analyysi · ${Number(data.project_memory_items_used || 0)} kontekstimuistin merkintää · ${mapMeta}`;
            }
            renderHtmlDataUrlPreview(
                graphicsHtmlPreviewFrame,
                graphicsHtmlPreviewEmpty,
                latestGraphicsHtmlPage.dataUrl,
                latestGraphicsHtmlPage.filename
            );
            const warnings = Array.isArray(data.warnings) ? data.warnings.filter(Boolean) : [];
            finalStatus = {
                message: warnings.length
                    ? `HTML-luonnos valmis. ${warnings.join(' ')}`
                    : 'HTML-luonnos valmis katseltavaksi ja ladattavaksi.',
                isError: false
            };
            loadUsage();
        } catch (error) {
            finalStatus = { message: networkFailureMessage(error), isError: true };
            loadUsage();
        } finally {
            graphicsHtmlGenerating = false;
            renderGraphicsHtmlWorkspace();
            if (finalStatus) setGraphicsHtmlStatus(finalStatus.message, finalStatus.isError);
        }
    }

    function downloadGraphicsHtmlDraft() {
        if (!latestGraphicsHtmlPage?.dataUrl) {
            setGraphicsHtmlStatus('Luo HTML-luonnos ennen lataamista.', true);
            return;
        }
        const link = document.createElement('a');
        link.href = latestGraphicsHtmlPage.dataUrl;
        link.download = latestGraphicsHtmlPage.filename || 'kirjan-esittely.html';
        document.body.appendChild(link);
        link.click();
        link.remove();
        setGraphicsHtmlStatus(`HTML-tiedosto ladattu: ${latestGraphicsHtmlPage.filename}.`);
    }

    function setGraphicsTab(panelId = 'graphics-panel-cover', options = {}) {
        const nextPanelId = graphicsTabPanels.some(panel => panel.id === panelId)
            ? panelId
            : 'graphics-panel-cover';
        graphicsActivePanel = nextPanelId;
        graphicsTabPanels.forEach(panel => {
            const active = panel.id === nextPanelId;
            panel.classList.toggle('hidden', !active);
            panel.setAttribute('aria-hidden', String(!active));
        });
        graphicsTabButtons.forEach(button => {
            const active = button.dataset.graphicsPanel === nextPanelId;
            button.classList.toggle('is-active', active);
            button.setAttribute('aria-selected', String(active));
            button.tabIndex = active ? 0 : -1;
            if (active && options.focus) button.focus();
        });

        if (nextPanelId === 'graphics-panel-cover') {
            loadImageModels();
            loadCoverImages();
        } else if (nextPanelId === 'graphics-panel-html') {
            renderGraphicsHtmlWorkspace();
            void loadCoverImages();
        } else {
            const projectId = activeGraphicProjectId();
            if (graphicAssetsLoadedProjectId !== projectId) loadGraphicAssets(false);
            if (nextPanelId === 'graphics-panel-images') {
                loadImageModels();
                renderVisualBatchDefaults();
                void resumeVisualImageBatchJob();
                scheduleVisualEstimate();
            } else if (nextPanelId === 'graphics-panel-infographics') {
                populateInfographicDefaults();
            }
            observeGraphicAssetPreviews();
        }
        syncGraphicsControls();
    }

    function handleGraphicsTabKeydown(event) {
        const currentIndex = graphicsTabButtons.indexOf(event.currentTarget);
        if (currentIndex < 0) return;
        let nextIndex = currentIndex;
        if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {
            nextIndex = (currentIndex + 1) % graphicsTabButtons.length;
        } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {
            nextIndex = (currentIndex - 1 + graphicsTabButtons.length) % graphicsTabButtons.length;
        } else if (event.key === 'Home') {
            nextIndex = 0;
        } else if (event.key === 'End') {
            nextIndex = graphicsTabButtons.length - 1;
        } else {
            return;
        }
        event.preventDefault();
        const nextButton = graphicsTabButtons[nextIndex];
        setGraphicsTab(nextButton.dataset.graphicsPanel, { focus: true });
    }

    function initializeGraphicsWorkspace() {
        updateIllustrationProjectText();
        renderVisualBatchDefaults();
        populateInfographicDefaults();
        setGraphicsTab(graphicsActivePanel);
    }

    function visualChapterEntries() {
        const projectTitle = normalizeBookSectionTitle(window.manuscriptData?.title || '').toLocaleLowerCase('fi-FI');
        return (window.manuscriptData?.chapters || [])
            .map((chapter, index) => ({ chapter, index }))
            .filter(({ chapter, index }) => {
                const title = normalizeBookSectionTitle(structureDisplayTitle(chapter, index)).toLocaleLowerCase('fi-FI');
                const id = String(chapter?.id || '').trim().toLocaleLowerCase('fi-FI').replace(/[\s-]+/g, '_');
                const apiKind = String(chapter?.kind || chapter?.placement || '').trim().toLocaleLowerCase('fi-FI');
                const structureKind = structureChapterKind(chapter);
                const excludedId = /^(?:alku|kansi|nimiolehti|title_page|valinimilehti|tekijanoikeus|omistus|epigrafi|sisallys|toc|esipuhe|johdanto|alkusoitto|prelude|overture|prologi|prologue|osa|part|aliluku|subchapter|epilogi|epilogue|loppu|jalkisanat|liite|sanasto|bibliografia|kiitokset|huomautukset|hakemisto|kolofoni)(?:_|$)/.test(id);
                const excludedTitle = /^(?:alkusoitto|prelude|overture|prologi|prologue|epilogi|epilogue|osa|part|aliluku|subchapter|kansi|cover|nimiölehti|nimiolehti|title page|sisällys|sisallys|table of contents|esipuhe|preface|johdanto|introduction|jälkisanat|jalkisanat|afterword|liite|appendix|sanasto|glossary|bibliografia|bibliography|kiitokset|acknowledgements|hakemisto|index|kolofoni|colophon)(?:\b|\s*[:\-–])/.test(title);
                const hasText = (chapter?.paragraphs || []).some(paragraph => String(paragraph || '').trim());
                return hasText
                    && chapterPlacement(chapter, index) === 'body'
                    && structureKind === 'chapter'
                    && !['front', 'part', 'back'].includes(apiKind)
                    && !excludedId
                    && !excludedTitle
                    && !(projectTitle && title === projectTitle);
            });
    }

    function visualChapterEntry(chapterId) {
        return visualChapterEntries().find(({ chapter }) => String(chapter.id || '') === String(chapterId || '')) || null;
    }

    function visualChapterExcerpt(chapter, index, maxChars = 560) {
        const title = normalizeBookSectionTitle(structureDisplayTitle(chapter, index)).toLocaleLowerCase('fi-FI');
        const text = (chapter?.paragraphs || [])
            .map(paragraph => String(paragraph || '').replace(/^#{1,6}\s+/, '').replace(/\s+/g, ' ').trim())
            .filter(paragraph => paragraph && paragraph.toLocaleLowerCase('fi-FI') !== title)
            .join(' ')
            .trim();
        if (text.length <= maxChars) return text;
        const compact = text.slice(0, maxChars + 1);
        const lastSpace = compact.lastIndexOf(' ');
        return `${compact.slice(0, lastSpace > maxChars * .65 ? lastSpace : maxChars).trim()}…`;
    }

    function visualChapterPrompt(chapter, index) {
        const title = structureDisplayTitle(chapter, index) || `Luku ${index + 1}`;
        const excerpt = visualChapterExcerpt(chapter, index);
        return [
            `Kuvita luvun ”${title}” yksi keskeinen, konkreettinen kohtaus.`,
            'Perusta henkilöt, tapahtumapaikka, toiminta, aikakausi ja tunnelma vain tämän luvun sisältöön.',
            'Älä kuvita luvun otsikkoa otsikkokorttina äläkä lisää kuvaan tekstiä.',
            excerpt ? `Luvun aineisto: ${excerpt}` : '',
        ].filter(Boolean).join(' ').slice(0, 1200);
    }

    function storedVisualPromptPlan() {
        const raw = window.manuscriptData?.analysis?.visual_world;
        if (!raw || typeof raw !== 'object') return null;
        const visualStyle = String(raw.visual_style || raw.shared_style || '').trim().slice(0, 700);
        const sourcePrompts = Array.isArray(raw.prompts)
            ? raw.prompts
            : Array.isArray(raw.chapter_prompts) ? raw.chapter_prompts : [];
        const prompts = sourcePrompts.map(item => {
            const entry = visualChapterEntry(item?.chapter_custom_id);
            const prompt = String(item?.prompt || '').trim().slice(0, 1200);
            if (!entry || !prompt) return null;
            return {
                chapter_custom_id: String(entry.chapter.id || ''),
                section_label: String(item.section_label || structureDisplayTitle(entry.chapter, entry.index) || `Luku ${entry.index + 1}`),
                visual_kind: String(item.visual_kind || 'scene'),
                aspect_ratio: String(item.aspect_ratio || '3:4'),
                prompt,
                prompt_source: ['fallback', 'generated', 'manual'].includes(String(item.prompt_source || ''))
                    ? String(item.prompt_source)
                    : 'generated',
            };
        }).filter(Boolean).slice(0, 10);
        if (!visualStyle && !prompts.length) return null;
        return {
            visual_style: visualStyle,
            prompts,
            generated_by: String(raw.generated_by || ''),
            without_text: typeof raw.without_text === 'boolean' ? raw.without_text : true,
            updated_at: String(raw.updated_at || ''),
        };
    }

    function rememberVisualPromptPlan(data, prompts) {
        if (!window.manuscriptData) return;
        window.manuscriptData.analysis = window.manuscriptData.analysis || {};
        window.manuscriptData.analysis.visual_world = {
            visual_style: String(data?.visual_style || '').trim().slice(0, 700),
            prompts: prompts.map(item => ({ ...item })),
            generated_by: String(data?.generated_by || ''),
            without_text: typeof data?.without_text === 'boolean'
                ? data.without_text
                : Boolean(visualWithoutText?.checked),
            updated_at: new Date().toISOString(),
        };
    }

    function nextUnusedVisualChapterEntry() {
        if ((visualBatchRows?.children.length || 0) >= 10) return null;
        const used = new Set(Array.from(visualBatchRows?.querySelectorAll('.visual-row-chapter') || []).map(select => String(select.value || '')));
        return visualChapterEntries().find(({ chapter }) => !used.has(String(chapter.id || ''))) || null;
    }

    function visualChapterTitle(chapterId) {
        const entry = visualChapterEntry(chapterId);
        return entry ? (structureDisplayTitle(entry.chapter, entry.index) || 'Nimetön luku') : 'Valitse luku';
    }

    function visualChapterOptions(selectedId = '') {
        const entries = visualChapterEntries();
        if (!entries.length) return '<option value="" selected disabled>Varsinaisia tekstillisiä lukuja ei löytynyt</option>';
        const resolvedId = entries.some(({ chapter }) => String(chapter.id || '') === String(selectedId || ''))
            ? String(selectedId || '')
            : String(entries[0].chapter.id || '');
        return entries.map(({ chapter, index }) => {
            const chapterId = String(chapter.id || '');
            const title = structureDisplayTitle(chapter, index) || `Luku ${index + 1}`;
            return `<option value="${escapeHtml(chapterId)}"${chapterId === resolvedId ? ' selected' : ''}>${escapeHtml(title)}</option>`;
        }).join('');
    }

    function visualKindOptions(selected = 'chapter_opening') {
        return visualKindDefinitions
            .filter(item => !showcaseDemoMode || item.value !== 'marketing')
            .map(item => (
            `<option value="${item.value}"${item.value === selected ? ' selected' : ''}>${escapeHtml(item.label)}</option>`
            )).join('');
    }

    function visualAspectRatioOptions(selected = '3:4') {
        return visualAspectRatioDefinitions.map(item => (
            `<option value="${item.value}"${item.value === selected ? ' selected' : ''}>${escapeHtml(item.label)}</option>`
        )).join('');
    }

    function renumberVisualBatchRows() {
        visualBatchRows?.querySelectorAll('.visual-batch-row').forEach((row, index) => {
            const number = row.querySelector('.visual-batch-row-number');
            if (number) number.textContent = String(index + 1).padStart(2, '0');
            const heading = row.querySelector('.visual-batch-row-title');
            if (heading) heading.textContent = `Kuvaehdotus ${index + 1}`;
        });
    }

    function addVisualBatchRow(initial = {}, options = {}) {
        if (!visualBatchRows) return null;
        const fallbackEntry = nextUnusedVisualChapterEntry() || visualChapterEntries()[0] || null;
        const selectedEntry = visualChapterEntry(initial.chapter_custom_id) || fallbackEntry;
        if (!selectedEntry) return null;
        const rowId = `visual-row-${++visualBatchRowSequence}`;
        const chapterId = String(selectedEntry.chapter.id || '');
        const sectionLabel = String(initial.section_label || structureDisplayTitle(selectedEntry.chapter, selectedEntry.index) || `Luku ${selectedEntry.index + 1}`);
        const chapterPrompt = String(initial.prompt || visualChapterPrompt(selectedEntry.chapter, selectedEntry.index));
        const promptSource = ['fallback', 'generated', 'manual'].includes(String(initial.prompt_source || ''))
            ? String(initial.prompt_source)
            : initial.prompt ? 'manual' : 'fallback';
        const row = document.createElement('article');
        row.className = 'visual-batch-row glass-panel';
        row.dataset.visualRowId = rowId;
        row.dataset.visualPromptSource = promptSource;
        row.innerHTML = `
            <div class="visual-batch-row-header">
                <span class="visual-batch-row-number">00</span>
                <div><strong class="visual-batch-row-title">Kuvaehdotus</strong><small>Yksi kuva tästä rivistä</small></div>
                <button class="visual-row-remove" type="button" aria-label="Poista kuvaehdotuksen rivi">Poista</button>
            </div>
            <div class="visual-batch-row-fields">
                <label class="graphics-field">
                    <span>Kirjan luku</span>
                    <select class="visual-row-chapter">${visualChapterOptions(chapterId)}</select>
                </label>
                <label class="graphics-field">
                    <span>Kuvan tehtävä</span>
                    <select class="visual-row-kind">${visualKindOptions(initial.visual_kind || 'chapter_opening')}</select>
                </label>
                <label class="graphics-field">
                    <span>Kuvasuhde</span>
                    <select class="visual-row-aspect">${visualAspectRatioOptions(initial.aspect_ratio || '3:4')}</select>
                </label>
                <label class="graphics-field">
                    <span>Kuvan nimi</span>
                    <input class="visual-row-label" type="text" maxlength="160" value="${escapeHtml(sectionLabel)}" placeholder="Esimerkiksi Luku 1 · avauskuva">
                </label>
                <label class="graphics-field graphics-field-wide">
                    <span>Lukukohtainen prompti</span>
                    <textarea class="visual-row-prompt" rows="4" maxlength="1200" placeholder="Luvun tekstiin perustuva prompti muodostetaan automaattisesti.">${escapeHtml(chapterPrompt)}</textarea>
                </label>
            </div>
            <p class="visual-batch-row-status" role="status">Odottaa generointia.</p>
        `;
        const chapterSelect = row.querySelector('.visual-row-chapter');
        const labelInput = row.querySelector('.visual-row-label');
        const promptInput = row.querySelector('.visual-row-prompt');
        chapterSelect?.addEventListener('change', () => {
            const entry = visualChapterEntry(chapterSelect.value);
            if (!entry) return;
            if (labelInput) labelInput.value = structureDisplayTitle(entry.chapter, entry.index) || `Luku ${entry.index + 1}`;
            if (promptInput) promptInput.value = visualChapterPrompt(entry.chapter, entry.index);
            row.dataset.visualPromptSource = 'fallback';
        });
        promptInput?.addEventListener('input', () => { row.dataset.visualPromptSource = 'manual'; });
        row.querySelector('.visual-row-remove')?.addEventListener('click', () => {
            row.remove();
            renumberVisualBatchRows();
            syncGraphicsControls();
            scheduleVisualEstimate();
            setVisualStatus(visualBatchRows.children.length
                ? `${visualBatchRows.children.length} kuvaehdotusta valmiina ajoon.`
                : 'Lisää vähintään yksi kuvaehdotuksen rivi.');
        });
        visualBatchRows.appendChild(row);
        renumberVisualBatchRows();
        if (options.focus) row.querySelector('.visual-row-chapter')?.focus();
        syncGraphicsControls();
        if (!options.skipEstimate) scheduleVisualEstimate();
        return row;
    }

    function refreshAutomaticVisualChapterPrompts() {
        visualBatchRows?.querySelectorAll('.visual-batch-row').forEach(row => {
            if (row.dataset.visualPromptSource !== 'fallback') return;
            const entry = visualChapterEntry(row.querySelector('.visual-row-chapter')?.value || '');
            const promptInput = row.querySelector('.visual-row-prompt');
            if (entry && promptInput) promptInput.value = visualChapterPrompt(entry.chapter, entry.index);
        });
    }

    function renderVisualBatchDefaults(force = false) {
        if (!visualBatchRows) return;
        const projectId = String(window.manuscriptData?.id || 'unsaved');
        const projectChanged = visualRowsInitializedProjectId !== projectId;
        if (!force && !projectChanged && visualBatchRows.children.length) {
            refreshAutomaticVisualChapterPrompts();
            return;
        }
        if (visualBatchController) return;
        visualBatchRows.replaceChildren();
        const savedPlan = storedVisualPromptPlan();
        if (projectChanged && visualSharedPrompt) visualSharedPrompt.value = savedPlan?.visual_style || '';
        if (projectChanged && visualWithoutText) visualWithoutText.checked = savedPlan?.without_text ?? true;
        if (savedPlan?.prompts.length) {
            savedPlan.prompts.forEach(item => addVisualBatchRow(item, { skipEstimate: true }));
            if (visualPromptCount) visualPromptCount.value = String(savedPlan.prompts.length);
        } else {
            const entries = visualChapterEntries().slice(0, 10);
            entries.forEach(({ chapter, index }) => addVisualBatchRow({
                chapter_custom_id: String(chapter.id || ''),
                section_label: structureDisplayTitle(chapter, index) || `Luku ${index + 1}`,
                visual_kind: 'scene',
                aspect_ratio: '3:4',
            }, { skipEstimate: true }));
            if (visualPromptCount) visualPromptCount.value = String(Math.min(10, Math.max(1, entries.length || 10)));
        }
        visualRowsInitializedProjectId = projectId;
        if (visualProgress) {
            visualProgress.max = Math.max(1, visualBatchRows.children.length);
            visualProgress.value = 0;
        }
        setVisualStatus(!window.manuscriptData
            ? 'Valitse projekti ennen kuvien generointia.'
            : visualBatchRows.children.length
                ? savedPlan?.prompts.length
                    ? `${visualBatchRows.children.length} tallennettua lukupromptia ja yhteinen kuvatyyli ladattiin.`
                    : `${visualBatchRows.children.length} luvun peruspromptit muodostettiin. Voit luoda analyysistä yhteisen tyylin ja tarkemmat promptit.`
                : 'Projektista ei löytynyt varsinaisia tekstillisiä lukuja Kuvamaailmaa varten.',
            Boolean(window.manuscriptData && !visualBatchRows.children.length));
        syncGraphicsControls();
        scheduleVisualEstimate();
    }

    function collectVisualBatchRows(options = {}) {
        const sharedPrompt = (visualSharedPrompt?.value || '').trim();
        const baseItems = Array.from(visualBatchRows?.querySelectorAll('.visual-batch-row') || []).map((row, index) => {
            const chapterId = row.querySelector('.visual-row-chapter')?.value || '';
            const specificPrompt = row.querySelector('.visual-row-prompt')?.value.trim() || '';
            const prompt = [sharedPrompt, specificPrompt].filter(Boolean).join('\n\n');
            const sectionLabel = row.querySelector('.visual-row-label')?.value.trim() || visualChapterTitle(chapterId);
            return {
                row,
                index,
                rowIndex: index,
                sectionLabel,
                sharedPrompt,
                specificPrompt,
                payload: {
                    model: visualModelSelect?.value || null,
                    visual_kind: row.querySelector('.visual-row-kind')?.value || 'chapter_opening',
                    section_label: sectionLabel,
                    chapter_custom_id: chapterId,
                    prompt: prompt.slice(0, 2000),
                    aspect_ratio: row.querySelector('.visual-row-aspect')?.value || '3:4',
                    image_size: visualSelectedImageSize(),
                    use_analysis: Boolean(visualUseAnalysis?.checked),
                    use_project_memory: Boolean(visualUseMemory?.checked),
                    without_text: Boolean(visualWithoutText?.checked),
                },
            };
        }).filter(item => item.payload.chapter_custom_id && item.payload.prompt);
        if (options.expandVariants === false) return baseItems;
        const variantCount = visualVariantCount();
        const expanded = [];
        baseItems.forEach(item => {
            for (let variantIndex = 1; variantIndex <= variantCount; variantIndex += 1) {
                const variantInstruction = variantCount > 1
                    ? `Variant ${variantIndex}/${variantCount}: keep style and characters consistent; vary composition or camera angle.`
                    : '';
                const prompt = [item.sharedPrompt, variantInstruction, item.specificPrompt]
                    .filter(Boolean)
                    .join('\n\n')
                    .slice(0, 2000);
                expanded.push({
                    ...item,
                    index: expanded.length,
                    variantIndex,
                    variantCount,
                    payload: {
                        ...item.payload,
                        section_label: variantCount > 1
                            ? `${item.sectionLabel} · vaihtoehto ${variantIndex}`
                            : item.sectionLabel,
                        prompt,
                        variant_index: variantIndex,
                    },
                });
            }
        });
        return expanded;
    }

    async function ensureGraphicProject() {
        if (window.manuscriptData && !window.manuscriptData.id) {
            const savedProject = await window.saveManuscriptToDB(window.manuscriptData);
            if (savedProject?.id) window.manuscriptData = savedProject;
        }
        return window.manuscriptData?.id || null;
    }

    function visualPromptPlanChapterIds(count) {
        const limit = Math.min(10, Math.max(1, Number(count) || 10));
        const ids = [];
        const seen = new Set();
        Array.from(visualBatchRows?.querySelectorAll('.visual-row-chapter') || []).forEach(select => {
            const chapterId = String(select.value || '');
            if (!chapterId || seen.has(chapterId) || !visualChapterEntry(chapterId) || ids.length >= limit) return;
            seen.add(chapterId);
            ids.push(chapterId);
        });
        visualChapterEntries().forEach(({ chapter }) => {
            const chapterId = String(chapter.id || '');
            if (!chapterId || seen.has(chapterId) || ids.length >= limit) return;
            seen.add(chapterId);
            ids.push(chapterId);
        });
        return ids;
    }

    function applyVisualPromptPlan(data) {
        const visualStyle = String(data?.visual_style || '').trim().slice(0, 700);
        const prompts = (Array.isArray(data?.prompts) ? data.prompts : []).map(item => {
            const entry = visualChapterEntry(item?.chapter_custom_id);
            const prompt = String(item?.prompt || '').trim().slice(0, 1200);
            if (!entry || !prompt) return null;
            return {
                chapter_custom_id: String(entry.chapter.id || ''),
                section_label: String(item.section_label || structureDisplayTitle(entry.chapter, entry.index) || `Luku ${entry.index + 1}`),
                visual_kind: String(item.visual_kind || 'scene'),
                aspect_ratio: String(item.aspect_ratio || '3:4'),
                prompt,
                prompt_source: ['fallback', 'generated'].includes(String(item.prompt_source || ''))
                    ? String(item.prompt_source)
                    : 'generated',
            };
        }).filter(Boolean).slice(0, 10);
        if (!prompts.length) throw new Error('Kuvapromptteja ei saatu muodostettua valituille luvuille.');
        if (visualSharedPrompt) visualSharedPrompt.value = visualStyle;
        if (visualWithoutText && typeof data?.without_text === 'boolean') {
            visualWithoutText.checked = data.without_text;
        }
        visualBatchRows?.replaceChildren();
        prompts.forEach(item => addVisualBatchRow(item, { skipEstimate: true }));
        rememberVisualPromptPlan({ ...data, visual_style: visualStyle }, prompts);
        visualRowsInitializedProjectId = String(window.manuscriptData?.id || 'unsaved');
        if (visualPromptCount) visualPromptCount.value = String(prompts.length);
        if (visualProgress) {
            visualProgress.max = Math.max(1, prompts.length);
            visualProgress.value = 0;
        }
        scheduleVisualEstimate();
        return prompts;
    }

    async function generateVisualPromptPlan() {
        if (visualPromptPlanController || visualBatchController || visualImageBatchSubmitting || visualImageBatchJobId) return;
        const projectId = await ensureGraphicProject();
        if (visualPromptPlanController || visualBatchController || visualImageBatchSubmitting || visualImageBatchJobId) return;
        if (!projectId) {
            setVisualStatus('Valitse tai tallenna käsikirjoitus ennen tyylin ja lukupromptien luontia.', true);
            return;
        }
        if (String(projectId) !== activeGraphicProjectId()) return;
        const availableCount = visualChapterEntries().length;
        if (!availableCount) {
            setVisualStatus('Projektista ei löytynyt varsinaisia tekstillisiä lukuja.', true);
            return;
        }
        const count = Math.min(10, availableCount, Math.max(1, Number(visualPromptCount?.value) || 10));
        if (visualPromptCount) visualPromptCount.value = String(count);
        const chapterIds = visualPromptPlanChapterIds(count);
        if (!chapterIds.length) {
            setVisualStatus('Valitse vähintään yksi varsinainen luku prompttisuunnitelmaan.', true);
            return;
        }
        const promptRun = { projectId: String(projectId) };
        visualPromptPlanController = promptRun;
        syncGraphicsControls();
        setVisualStatus(`Muodostetaan koko kirjan analyysistä yhteinen tyyli ja ${chapterIds.length} lukupromptia…`);
        try {
            const response = await apiFetch(`/api/projects/${projectId}/visual-prompts`, {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    chapter_custom_ids: chapterIds,
                    count: chapterIds.length,
                    style_hint: visualSharedPrompt?.value.trim() || null,
                    use_analysis: Boolean(visualUseAnalysis?.checked),
                    use_project_memory: Boolean(visualUseMemory?.checked),
                    without_text: Boolean(visualWithoutText?.checked),
                }),
            });
            const data = await response.json().catch(() => null);
            if (!response.ok) throw new Error(data?.detail || 'Tyylin ja lukupromptien luonti epäonnistui.');
            if (visualPromptPlanController !== promptRun || activeGraphicProjectId() !== String(projectId)) return;
            const prompts = applyVisualPromptPlan(data);
            const warnings = Array.isArray(data?.warnings) ? data.warnings.filter(Boolean) : [];
            setVisualStatus([
                `Yhteinen kuvatyyli ja ${prompts.length} lukukohtaista promptia luotiin ja tallennettiin projektiin.`,
                warnings.length ? warnings.join(' ') : '',
            ].filter(Boolean).join(' '));
            loadUsage();
        } catch (error) {
            if (visualPromptPlanController === promptRun && activeGraphicProjectId() === String(projectId)) {
                setVisualStatus(networkFailureMessage(error), true);
            }
        } finally {
            if (visualPromptPlanController === promptRun) visualPromptPlanController = null;
            syncGraphicsControls();
        }
    }

    function syncGraphicsControls() {
        const hasProject = Boolean(window.manuscriptData);
        const editable = hasProject && canEditProject(window.manuscriptData);
        const directRunning = Boolean(visualBatchController);
        const providerBatchRunning = visualImageBatchSubmitting || Boolean(visualImageBatchJobId);
        const promptRunning = Boolean(visualPromptPlanController);
        const graphicsRunning = directRunning || providerBatchRunning || promptRunning;
        const mode = visualExecutionMode();
        const imageCount = visualPlannedImageCount();
        const estimateIsCurrent = latestVisualEstimate && latestVisualEstimateKey === visualEstimateKey();
        const batchSupported = visualModelSupportsBatch();
        const batchMaximum = estimateIsCurrent ? Number(latestVisualEstimate.max_batch_images) : 0;
        const remaining = estimateIsCurrent ? Number(latestVisualEstimate.monthly_remaining) : NaN;
        const exceedsMaximum = imageCount > VISUAL_MAX_IMAGES_PER_RUN
            || (mode === 'batch' && batchMaximum > 0 && imageCount > batchMaximum);
        const exceedsQuota = latestVisualEstimate?.quota_enforced !== false
            && Number.isFinite(remaining)
            && imageCount > remaining;
        if (visualAddRowBtn) visualAddRowBtn.disabled = !editable || graphicsRunning || !nextUnusedVisualChapterEntry();
        if (visualGeneratePromptsBtn) {
            visualGeneratePromptsBtn.disabled = !editable || graphicsRunning || !visualChapterEntries().length;
            visualGeneratePromptsBtn.textContent = promptRunning ? 'Luodaan tyyliä ja prompteja…' : 'Luo tyyli ja lukupromptit';
        }
        if (visualGenerateAllBtn) {
            visualGenerateAllBtn.disabled = !editable
                || graphicsRunning
                || !imageCount
                || exceedsMaximum
                || exceedsQuota
                || (mode === 'batch' && !batchSupported);
            visualGenerateAllBtn.textContent = directRunning
                ? 'Luodaan kuvia…'
                : providerBatchRunning
                    ? 'Gemini-eräajo käynnissä…'
                    : mode === 'batch'
                        ? `Lähetä ${imageCount || ''} kuvaa eräajoon`.replace(/\s+/g, ' ').trim()
                        : `Luo ${imageCount || ''} kuvaa heti`.replace(/\s+/g, ' ').trim();
        }
        if (visualStopBtn) {
            visualStopBtn.classList.toggle('hidden', !directRunning && !providerBatchRunning);
            visualStopBtn.disabled = (!directRunning && !providerBatchRunning)
                || visualImageBatchSubmitting
                || visualBatchController?.stopRequested;
            visualStopBtn.textContent = visualImageBatchSubmitting
                ? 'Lähetetään…'
                : providerBatchRunning
                    ? 'Peru eräajo'
                    : (visualBatchController?.stopRequested ? 'Pysäytetään…' : 'Pysäytä');
        }
        visualBatchRows?.querySelectorAll('input, select, textarea, button').forEach(field => {
            field.disabled = !editable || graphicsRunning;
        });
        [
            visualPromptCount,
            visualSharedPrompt,
            visualUseAnalysis,
            visualUseMemory,
            visualWithoutText,
            visualModelSelect,
            visualImageSize,
            visualVariantsPerPrompt,
            ...visualExecutionModeInputs,
        ]
            .filter(Boolean)
            .forEach(field => {
                field.disabled = !editable
                    || graphicsRunning
                    || (field.value === 'batch' && !batchSupported);
            });
        if (infographicGenerateBtn) infographicGenerateBtn.disabled = !editable || infographicGenerateBtn.dataset.running === 'true';
    }

    async function waitForVisualBatch(batchRun, delayMs, statusMessage) {
        const deadline = Date.now() + Math.max(0, Number(delayMs || 0));
        let previousSeconds = null;
        while (Date.now() < deadline) {
            if (!visualBatchUsesActiveProject(batchRun)) {
                batchRun.stopRequested = true;
                batchRun.projectChanged = true;
            }
            if (batchRun.stopRequested) return false;
            const seconds = Math.max(1, Math.ceil((deadline - Date.now()) / 1000));
            if (seconds !== previousSeconds) {
                setVisualStatus(`${statusMessage} ${seconds} s…`);
                previousSeconds = seconds;
            }
            await wait(Math.min(500, Math.max(0, deadline - Date.now())));
        }
        return !batchRun.stopRequested;
    }

    function visualBatchErrorMessage(error) {
        const message = String(error?.message || '').trim();
        if (message && !/failed to fetch|networkerror|load failed/i.test(message)) return message;
        return 'Yhteys kuvamalliin katkesi. Valmiit kuvat säilyvät, ja epäonnistuneen luvun voi ajaa uudelleen.';
    }

    async function requestVisualBatchImage(projectId, item, batch, batchRun, rowStatus) {
        let lastError = null;
        for (let attempt = 1; attempt <= VISUAL_BATCH_MAX_REQUEST_ATTEMPTS; attempt += 1) {
            try {
                const response = await apiFetch(`/api/projects/${projectId}/visual-images`, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify(item.payload),
                });
                const data = await response.json().catch(() => null);
                if (response.ok) return data;
                const error = new Error(data?.detail || 'Kuvaehdotuksen generointi epäonnistui.');
                error.status = response.status;
                const retryAfter = Number(response.headers?.get?.('Retry-After') || 0);
                error.retryAfterMs = Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : 0;
                error.stopBatch = response.status === 429;
                throw error;
            } catch (error) {
                lastError = error;
                const retryable = [408, 425, 502, 503, 504].includes(Number(error?.status));
                if (error?.stopBatch || !retryable || attempt >= VISUAL_BATCH_MAX_REQUEST_ATTEMPTS) throw error;
                const delayMs = Math.max(error.retryAfterMs || 0, VISUAL_BATCH_RETRY_DELAY_MS * attempt);
                if (rowStatus) rowStatus.textContent = `Kuvamalli tarvitsee hetken. Uusi yritys ${attempt + 1}/${VISUAL_BATCH_MAX_REQUEST_ATTEMPTS} odottaa…`;
                const canContinue = await waitForVisualBatch(
                    batchRun,
                    delayMs,
                    `Kuvamalli tarvitsee hetken ennen luvun ${item.index + 1}/${batch.length} uutta yritystä. Odotetaan`,
                );
                if (!canContinue) {
                    const stoppedError = new Error('Kuvaerä pysäytettiin odotuksen aikana.');
                    stoppedError.batchStopped = true;
                    throw stoppedError;
                }
                if (rowStatus) rowStatus.textContent = `Generoidaan uudelleen ${item.index + 1}/${batch.length}…`;
            }
        }
        throw lastError || new Error('Kuvaehdotuksen generointi epäonnistui.');
    }

    async function generateVisualBatch() {
        if (visualExecutionMode() === 'batch') {
            await startVisualProviderBatch();
            return;
        }
        if (visualBatchController || visualImageBatchJobId) return;
        const projectId = await ensureGraphicProject();
        if (visualBatchController || visualImageBatchJobId) return;
        if (!projectId) {
            setVisualStatus('Valitse tai tallenna käsikirjoitus ennen kuvien generointia.', true);
            return;
        }
        if (String(projectId) !== activeGraphicProjectId()) return;
        const batch = collectVisualBatchRows();
        if (!batch.length) {
            setVisualStatus('Lisää vähintään yksi kuvaehdotuksen rivi.', true);
            return;
        }
        if (batch.length > VISUAL_MAX_IMAGES_PER_RUN) {
            setVisualStatus(`Yhdessä kuvaerässä voi olla enintään ${VISUAL_MAX_IMAGES_PER_RUN} kuvaa. Vähennä vaihtoehtojen määrää.`, true);
            return;
        }
        const batchRun = {
            projectId: String(projectId),
            stopRequested: false,
            projectChanged: false,
        };
        visualBatchController = batchRun;
        if (visualStopBtn) visualStopBtn.textContent = 'Pysäytä';
        syncGraphicsControls();
        if (visualProgress) {
            visualProgress.max = batch.length;
            visualProgress.value = 0;
        }
        batch.forEach(({ row }) => {
            const status = row.querySelector('.visual-batch-row-status');
            if (status) {
                status.textContent = 'Odottaa vuoroa…';
                status.classList.remove('is-error', 'is-complete', 'is-running');
            }
        });
        const failures = [];
        let completed = 0;
        let stopped = false;
        try {
            for (let batchIndex = 0; batchIndex < batch.length; batchIndex += 1) {
                const item = batch[batchIndex];
                if (!visualBatchUsesActiveProject(batchRun)) {
                    batchRun.stopRequested = true;
                    batchRun.projectChanged = true;
                }
                if (batchRun.stopRequested) {
                    stopped = true;
                    break;
                }
                const rowStatus = item.row.querySelector('.visual-batch-row-status');
                if (rowStatus) {
                    rowStatus.textContent = `Generoidaan ${item.index + 1}/${batch.length}…`;
                    rowStatus.classList.add('is-running');
                }
                setVisualStatus(`Generoidaan kuvaehdotusta ${item.index + 1}/${batch.length}: ${item.payload.section_label}. Valmiit kuvat tallentuvat heti.`);
                try {
                    const data = await requestVisualBatchImage(projectId, item, batch, batchRun, rowStatus);
                    completed += 1;
                    const activeProjectStillMatches = visualBatchUsesActiveProject(batchRun);
                    if (activeProjectStillMatches) {
                        addGraphicAsset(data, batchRun.projectId);
                    } else {
                        batchRun.stopRequested = true;
                        batchRun.projectChanged = true;
                    }
                    if (rowStatus) {
                        rowStatus.textContent = activeProjectStillMatches
                            ? item.variantCount > 1
                                ? `Vaihtoehto ${item.variantIndex}/${item.variantCount} valmis ja tallennettu.`
                                : 'Valmis ja tallennettu.'
                            : 'Valmis ja tallennettu aiempaan projektiin.';
                        rowStatus.classList.remove('is-running');
                        rowStatus.classList.add('is-complete');
                    }
                } catch (error) {
                    if (error?.batchStopped) {
                        stopped = true;
                        break;
                    }
                    const message = visualBatchErrorMessage(error);
                    failures.push({ label: item.payload.section_label, message });
                    if (rowStatus) {
                        rowStatus.textContent = message;
                        rowStatus.classList.remove('is-running');
                        rowStatus.classList.add('is-error');
                    }
                    if (error?.stopBatch) {
                        batchRun.stopRequested = true;
                        batchRun.stopReason = 'usage_limit';
                    }
                } finally {
                    if (visualProgress) visualProgress.value = item.index + 1;
                }
                if (!visualBatchUsesActiveProject(batchRun)) {
                    batchRun.stopRequested = true;
                    batchRun.projectChanged = true;
                }
                if (batchRun.stopRequested) {
                    stopped = true;
                    break;
                }
                if (batchIndex < batch.length - 1) {
                    const canContinue = await waitForVisualBatch(
                        batchRun,
                        VISUAL_BATCH_REQUEST_DELAY_MS,
                        `Kuva ${batchIndex + 1}/${batch.length} on käsitelty. Annetaan kuvamallille hetki ennen seuraavaa pyyntöä. Odotetaan`,
                    );
                    if (!canContinue) {
                        stopped = true;
                        break;
                    }
                }
            }
            await loadGraphicAssets(false, { force: true });
            loadUsage();
            if (batchRun.projectChanged) {
                // The active project owns the visible status and gallery now.
            } else if (batchRun.stopReason === 'usage_limit') {
                setVisualStatus(`Kuvaerä keskeytettiin käyttörajaan. ${completed}/${batch.length} kuvaa valmistui; valmiit kuvat ovat tallessa.`, true);
            } else if (stopped) {
                setVisualStatus(`Kuvaerä pysäytettiin. ${completed}/${batch.length} kuvaa valmistui${failures.length ? ` ja ${failures.length} epäonnistui` : ''}.`, Boolean(failures.length));
            } else if (failures.length) {
                setVisualStatus(`${completed}/${batch.length} kuvaa valmistui. ${failures.length} riviä epäonnistui; muut kuvat ovat tallessa.`, true);
            } else {
                setVisualStatus(`Kaikki ${completed} kuvaehdotusta luotiin ja tallennettiin.`);
            }
        } finally {
            if (visualBatchController === batchRun) visualBatchController = null;
            if (visualStopBtn) visualStopBtn.textContent = 'Pysäytä';
            if (batchRun.projectChanged) renderVisualBatchDefaults(true);
            syncGraphicsControls();
        }
    }

    function visualProviderJobId(job) {
        return job?.id ?? job?.batch_id ?? job?.job_id ?? null;
    }

    function visualProviderJobStatus(job) {
        return String(job?.status || 'queued').trim().toLowerCase();
    }

    function visualProviderJobCounts(job) {
        const total = Number(job?.total_requests ?? job?.image_count ?? job?.total_images ?? 0);
        const completed = Number(job?.completed_requests ?? job?.completed_images ?? job?.done_images ?? 0);
        const failed = Number(job?.failed_requests ?? job?.failed_images ?? 0);
        return {
            total: Number.isFinite(total) ? Math.max(0, total) : 0,
            completed: Number.isFinite(completed) ? Math.max(0, completed) : 0,
            failed: Number.isFinite(failed) ? Math.max(0, failed) : 0,
        };
    }

    function visualProviderJobTerminal(status) {
        return ['completed', 'done', 'partial', 'failed', 'error', 'cancelled', 'canceled', 'expired'].includes(String(status || '').toLowerCase());
    }

    function visualProviderBatchCountdown(targetCompletionAt) {
        const target = new Date(targetCompletionAt || '').getTime();
        if (!Number.isFinite(target)) return 'tavoiteaika enintään 24 h';
        const remaining = Math.max(0, Math.ceil((target - Date.now()) / 1000));
        if (!remaining) return '24 tunnin tavoiteaika täynnä';
        const hours = Math.floor(remaining / 3600);
        const minutes = Math.floor((remaining % 3600) / 60);
        return `tavoiteaikaa jäljellä ${hours} h ${String(minutes).padStart(2, '0')} min`;
    }

    function visualProviderJobPhase(job) {
        const status = visualProviderJobStatus(job);
        return ({
            submitting: 'Lähetetään Geminille',
            queued: 'Odottaa Geminin käsittelyä',
            running: 'Gemini luo kuvia',
            processing: 'Valmiita kuvia tallennetaan projektiin',
            partial: 'Eräajo valmistui osittain',
            completed: 'Eräajo valmistui',
            done: 'Eräajo valmistui',
        })[status] || 'Eräajo on käsittelyssä';
    }

    function applyVisualProviderJobSettings(job) {
        const modelName = String(job?.model_name || '');
        if (visualModelSelect && modelName) {
            const option = Array.from(visualModelSelect.options).find(item => (
                item.value === modelName || item.value.endsWith(`:${modelName}`)
            ));
            if (option) visualModelSelect.value = option.value;
        }
        syncVisualModelCapabilities();
        const imageSize = String(job?.image_size || '').toUpperCase();
        if (visualImageSize && Array.from(visualImageSize.options).some(option => option.value === imageSize)) {
            visualImageSize.value = imageSize;
        }
        const batchInput = visualExecutionModeInputs.find(input => input.value === 'batch');
        if (batchInput && !batchInput.disabled) batchInput.checked = true;
    }

    function updateVisualProviderBatchProgress(job) {
        const counts = visualProviderJobCounts(job);
        const processed = Math.min(counts.total, counts.completed + counts.failed);
        if (visualProgress) {
            visualProgress.max = Math.max(1, counts.total);
            visualProgress.value = processed;
        }
        const countCopy = counts.total
            ? ` ${counts.completed}/${counts.total} kuvaa valmiina${counts.failed ? `, ${counts.failed} epäonnistui` : ''}.`
            : '';
        setVisualStatus(`${visualProviderJobPhase(job)}.${countCopy} ${visualProviderBatchCountdown(job?.target_completion_at)}`.replace(/\.\s*\./g, '.'));
        const resultItems = Array.isArray(job?.items) ? job.items : [];
        visualBatchRows?.querySelectorAll('.visual-batch-row').forEach(row => {
            const rowStatus = row.querySelector('.visual-batch-row-status');
            if (!rowStatus) return;
            const chapterId = String(row.querySelector('.visual-row-chapter')?.value || '');
            const matches = resultItems.filter(item => String(item?.chapter_custom_id || '') === chapterId);
            const ready = matches.filter(item => ['completed', 'done', 'succeeded'].includes(String(item?.status || '').toLowerCase())).length;
            const failed = matches.filter(item => ['failed', 'error'].includes(String(item?.status || '').toLowerCase())).length;
            const processed = ready + failed;
            rowStatus.textContent = matches.length && processed
                ? `${ready}/${matches.length} vaihtoehtoa valmiina${failed ? `, ${failed} epäonnistui` : ''}.`
                : `${visualProviderJobPhase(job)}…`;
            rowStatus.classList.toggle(
                'is-running',
                !visualProviderJobTerminal(visualProviderJobStatus(job)) && (!matches.length || processed < matches.length),
            );
            rowStatus.classList.toggle('is-complete', Boolean(matches.length && ready === matches.length));
            rowStatus.classList.toggle('is-error', failed > 0);
        });
    }

    function clearVisualProviderBatchState(token = visualImageBatchPollToken) {
        if (token && visualImageBatchPollToken && token !== visualImageBatchPollToken) return;
        if (visualImageBatchPollToken) visualImageBatchPollToken.stopped = true;
        visualImageBatchPollToken = null;
        visualImageBatchJobId = null;
        visualImageBatchProjectId = null;
        visualImageBatchLastStatus = null;
        syncGraphicsControls();
    }

    function detachVisualProviderBatchForProjectChange(nextProjectId) {
        const currentProjectId = String(visualImageBatchProjectId || '');
        if (!currentProjectId || currentProjectId === String(nextProjectId || '')) return false;
        if (visualImageBatchPollToken) visualImageBatchPollToken.stopped = true;
        visualImageBatchPollToken = null;
        visualImageBatchJobId = null;
        visualImageBatchProjectId = null;
        visualImageBatchLastStatus = null;
        syncGraphicsControls();
        return true;
    }

    async function finishVisualProviderBatch(job, token) {
        if (visualImageBatchPollToken !== token || token.stopped) return;
        const status = visualProviderJobStatus(job);
        const counts = visualProviderJobCounts(job);
        const projectStillActive = activeGraphicProjectId() === token.projectId;
        clearVisualProviderBatchState(token);
        if (!projectStillActive) return;
        await loadGraphicAssets(false, { force: true });
        loadUsage();
        if (status === 'completed' || status === 'done') {
            setVisualStatus(`Gemini-eräajo valmistui. ${counts.completed || counts.total} kuvaa tallennettiin projektiin.`);
        } else if (status === 'partial') {
            setVisualStatus(`Gemini-eräajo valmistui osittain. ${counts.completed}/${counts.total} kuvaa tallennettiin ja ${counts.failed} epäonnistui.`, true);
        } else if (status === 'cancelled' || status === 'canceled') {
            setVisualStatus('Gemini-eräajo peruttiin. Vain ennen tämän eräajon käynnistämistä projektiin valmiiksi tallennetut kuvat säilyvät varmasti; keskeneräisen erän tuloksia ei luvata.');
        } else if (status === 'expired') {
            setVisualStatus('Gemini-eräajo ei valmistunut 24 tunnissa. Vain ennen tämän eräajon käynnistämistä projektiin valmiiksi tallennetut kuvat säilyvät varmasti; keskeneräisen erän tuloksia ei luvata.', true);
        } else {
            setVisualStatus(job?.error || job?.error_message || 'Gemini-eräajo epäonnistui.', true);
        }
        visualBatchRows?.querySelectorAll('.visual-batch-row-status').forEach(rowStatus => {
            rowStatus.textContent = status === 'completed' || status === 'done'
                ? 'Eräajo valmis. Kuvat on tallennettu projektiin.'
                : 'Eräajo päättyi. Tarkista tallennetut kuvat ja eräajon yhteenveto.';
            rowStatus.classList.remove('is-running');
            rowStatus.classList.toggle('is-complete', status === 'completed' || status === 'done');
            rowStatus.classList.toggle('is-error', !['completed', 'done', 'cancelled', 'canceled'].includes(status));
        });
        scheduleVisualEstimate({ immediate: true });
    }

    async function monitorVisualProviderBatch(initialJob) {
        const jobId = visualProviderJobId(initialJob);
        const projectId = String(initialJob?.project_id || visualImageBatchProjectId || activeGraphicProjectId());
        if (!jobId || !projectId) return;
        applyVisualProviderJobSettings(initialJob);
        const token = { jobId: String(jobId), projectId, stopped: false };
        if (visualImageBatchPollToken) visualImageBatchPollToken.stopped = true;
        visualImageBatchPollToken = token;
        visualImageBatchJobId = jobId;
        visualImageBatchProjectId = projectId;
        visualImageBatchLastStatus = initialJob;
        let job = initialJob;
        let consecutiveErrors = 0;
        syncGraphicsControls();
        while (!token.stopped && visualImageBatchPollToken === token) {
            if (activeGraphicProjectId() !== projectId) {
                token.stopped = true;
                break;
            }
            updateVisualProviderBatchProgress(job);
            const status = visualProviderJobStatus(job);
            if (visualProviderJobTerminal(status)) {
                await finishVisualProviderBatch(job, token);
                return;
            }
            await wait(VISUAL_BATCH_POLL_INTERVAL_MS);
            if (token.stopped || visualImageBatchPollToken !== token) break;
            try {
                const response = await apiFetch(`/api/visual-image-jobs/${jobId}`);
                const data = await response.json().catch(() => null);
                if (!response.ok) throw new Error(data?.detail || 'Eräajon tilaa ei saatu päivitettyä.');
                job = data?.job || data || {};
                visualImageBatchLastStatus = job;
                consecutiveErrors = 0;
            } catch (error) {
                consecutiveErrors += 1;
                if (consecutiveErrors >= 3) {
                    setVisualStatus('Yhteys eräajon tilaan katkesi. Työ jatkuu palvelimella; avaa Kuvamaailma myöhemmin nähdäksesi tilanteen.', true);
                    clearVisualProviderBatchState(token);
                    return;
                }
                setVisualStatus(`Eräajo jatkuu palvelimella. Tilan päivitys epäonnistui, yritetään uudelleen (${consecutiveErrors}/3)…`);
            }
        }
        if (visualImageBatchPollToken === token) clearVisualProviderBatchState(token);
    }

    async function resumeVisualImageBatchJob() {
        const projectId = activeGraphicProjectId();
        if (!projectId || visualBatchController || visualImageBatchJobId || visualImageBatchResumePromise) return;
        const requestedProjectId = String(projectId);
        visualImageBatchResumePromise = (async () => {
            try {
                const response = await apiFetch(`/api/projects/${requestedProjectId}/visual-image-jobs/active`);
                const data = await response.json().catch(() => null);
                if (response.status === 404 || response.status === 204) return;
                if (!response.ok) throw new Error(data?.detail || 'Keskeneräisen kuvaerän tilaa ei saatu ladattua.');
                const job = data?.job || data;
                if (!visualProviderJobId(job) || activeGraphicProjectId() !== requestedProjectId) return;
                visualImageBatchJobId = visualProviderJobId(job);
                visualImageBatchProjectId = requestedProjectId;
                updateVisualProviderBatchProgress(job);
                void monitorVisualProviderBatch(job);
            } catch (error) {
                if (activeGraphicProjectId() === requestedProjectId) {
                    setVisualStatus(networkFailureMessage(error), true);
                }
            }
        })();
        try {
            await visualImageBatchResumePromise;
        } finally {
            visualImageBatchResumePromise = null;
        }
    }

    function visualProviderBatchItems() {
        return collectVisualBatchRows().map(item => ({
            prompt: item.payload.prompt,
            section_label: item.sectionLabel,
            chapter_custom_id: item.payload.chapter_custom_id,
            visual_kind: item.payload.visual_kind,
            aspect_ratio: item.payload.aspect_ratio,
            variant_index: item.variantIndex,
        }));
    }

    async function startVisualProviderBatch() {
        if (visualBatchController || visualImageBatchSubmitting || visualImageBatchJobId) return;
        if (!visualModelSupportsBatch()) {
            setVisualStatus('Valittu kuvamalli ei tue Gemini-eräajoa. Valitse Gemini 3.1 Flash Image -malli tai käytä suoraa ajoa.', true);
            return;
        }
        const projectId = await ensureGraphicProject();
        if (!projectId || String(projectId) !== activeGraphicProjectId()) {
            setVisualStatus('Valitse tai tallenna käsikirjoitus ennen eräajon käynnistämistä.', true);
            return;
        }
        const items = visualProviderBatchItems();
        if (!items.length) {
            setVisualStatus('Lisää vähintään yksi kuvaehdotuksen rivi.', true);
            return;
        }
        if (items.length > VISUAL_MAX_IMAGES_PER_RUN) {
            setVisualStatus(`Gemini-erässä voi olla enintään ${VISUAL_MAX_IMAGES_PER_RUN} kuvaa. Vähennä vaihtoehtojen määrää.`, true);
            return;
        }
        const estimate = latestVisualEstimateKey === visualEstimateKey()
            ? latestVisualEstimate
            : await updateVisualEstimate();
        if (estimate && Number(estimate.max_batch_images) > 0 && items.length > Number(estimate.max_batch_images)) {
            setVisualStatus(`Valittu malli sallii enintään ${estimate.max_batch_images} kuvaa yhdessä eräajossa.`, true);
            return;
        }
        if (
            estimate
            && estimate.quota_enforced !== false
            && Number.isFinite(Number(estimate.monthly_remaining))
            && items.length > Number(estimate.monthly_remaining)
        ) {
            setVisualStatus(`Kuvaerä tarvitsee ${items.length} kuvapyyntöä, mutta kuukausikiintiötä on jäljellä ${Math.max(0, Number(estimate.monthly_remaining))}.`, true);
            return;
        }
        visualBatchRows?.querySelectorAll('.visual-batch-row-status').forEach(status => {
            status.textContent = 'Valmistellaan Gemini-eräajoa…';
            status.classList.remove('is-error', 'is-complete');
            status.classList.add('is-running');
        });
        if (visualProgress) {
            visualProgress.max = items.length;
            visualProgress.value = 0;
        }
        setVisualStatus(`Lähetetään ${items.length} kuvan erä Geminille. Voit sulkea sivun lähetyksen jälkeen.`);
        visualImageBatchSubmitting = true;
        syncGraphicsControls();
        try {
            const response = await apiFetch(`/api/projects/${projectId}/visual-image-jobs`, {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    model_name: String(selectedVisualModel()?.model_name || visualModelSelect?.value || ''),
                    image_size: visualSelectedImageSize(),
                    items,
                    use_analysis: Boolean(visualUseAnalysis?.checked),
                    use_project_memory: Boolean(visualUseMemory?.checked),
                    without_text: Boolean(visualWithoutText?.checked),
                }),
            });
            const data = await response.json().catch(() => null);
            if (!response.ok) throw new Error(data?.detail || 'Gemini-eräajoa ei saatu käynnistettyä.');
            const job = data?.job || data;
            if (!visualProviderJobId(job)) throw new Error('Palvelin ei palauttanut eräajon tunnistetta.');
            visualImageBatchJobId = visualProviderJobId(job);
            visualImageBatchProjectId = String(projectId);
            setVisualStatus(`Gemini-eräajo lähetettiin onnistuneesti. ${visualProviderBatchCountdown(job?.target_completion_at)}`);
            void monitorVisualProviderBatch(job);
            loadUsage();
        } catch (error) {
            setVisualStatus(networkFailureMessage(error), true);
            visualBatchRows?.querySelectorAll('.visual-batch-row-status').forEach(status => {
                status.textContent = 'Eräajon lähetys epäonnistui. Voit yrittää uudelleen.';
                status.classList.remove('is-running');
                status.classList.add('is-error');
            });
            clearVisualProviderBatchState();
        } finally {
            visualImageBatchSubmitting = false;
            syncGraphicsControls();
        }
    }

    async function cancelVisualProviderBatch() {
        const jobId = visualImageBatchJobId;
        if (!jobId) return;
        if (!window.confirm('Perutaanko käynnissä oleva Gemini-eräajo? Vain ennen tämän eräajon käynnistämistä projektiin valmiiksi tallennetut kuvat säilyvät varmasti. Keskeneräisen erän tulosten tallentumista ei voida luvata.')) return;
        if (visualStopBtn) {
            visualStopBtn.disabled = true;
            visualStopBtn.textContent = 'Perutaan…';
        }
        try {
            const response = await apiFetch(`/api/visual-image-jobs/${jobId}/cancel`, { method: 'POST' });
            const data = await response.json().catch(() => null);
            if (!response.ok) throw new Error(data?.detail || 'Gemini-eräajoa ei saatu peruttua.');
            const job = data?.job || data || { status: 'cancelled' };
            if (!job.status) job.status = 'cancelled';
            const token = visualImageBatchPollToken || {
                jobId: String(jobId),
                projectId: String(visualImageBatchProjectId || activeGraphicProjectId()),
                stopped: false,
            };
            if (!visualImageBatchPollToken) visualImageBatchPollToken = token;
            await finishVisualProviderBatch(job, token);
        } catch (error) {
            setVisualStatus(networkFailureMessage(error), true);
            syncGraphicsControls();
        }
    }

