    function setProductStatus(message, isError = false) {
        const status = document.getElementById('product-status');
        if (!status) return;
        status.textContent = message;
        status.style.color = isError ? '#ffb4b4' : 'var(--text-secondary)';
    }

    function collectProductFields() {
        const info = {};
        Object.entries(productFieldMap).forEach(([key, id]) => {
            const element = document.getElementById(id);
            info[key] = String(element?.value || '').trim();
        });
        info.missing_fields = productMissingFieldKeys(info);
        return info;
    }

    function productMissingFieldKeys(info = collectProductFields()) {
        const existing = new Set(Array.isArray(info?.missing_fields) ? info.missing_fields : []);
        Object.keys(productFieldMap).forEach(key => {
            if (String(info?.[key] || '').trim()) existing.delete(key);
        });
        productRequiredFieldKeys.forEach(key => {
            if (!String(info?.[key] || '').trim()) existing.add(key);
            else existing.delete(key);
        });
        return Array.from(existing).sort();
    }

    function markProductMissingFields(info = collectProductFields()) {
        const missing = new Set(productMissingFieldKeys(info));
        let completed = 0;
        document.querySelectorAll('.product-field-row').forEach(row => {
            const key = row.dataset.productKey;
            const isRequired = Boolean(key && productRequiredFieldKeys.has(key));
            const isMissing = Boolean(isRequired && missing.has(key));
            const field = row.querySelector('input, textarea, select');
            row.classList.toggle('product-required', isRequired);
            row.classList.toggle('product-missing', isMissing);
            if (field) {
                if (isRequired) field.setAttribute('aria-required', 'true');
                else field.removeAttribute('aria-required');
                if (isMissing) field.setAttribute('aria-invalid', 'true');
                else field.removeAttribute('aria-invalid');
            }
            if (key && String(info?.[key] || '').trim()) completed += 1;
        });
        const completedCount = document.getElementById('product-completed-count');
        const missingCount = document.getElementById('product-missing-count');
        if (completedCount) completedCount.textContent = String(completed);
        if (missingCount) missingCount.textContent = String(missing.size);
        return missing.size;
    }

    function currentProductBookMetrics() {
        const projectId = window.manuscriptData?.id;
        const manuscriptText = getFullManuscriptText(window.manuscriptData);
        let wordCount = countWords(manuscriptText);
        let characterCount = manuscriptText.length;
        let estimatedPageCount = wordCount
            ? Math.ceil((Math.ceil(wordCount / 250) + 8) / 4) * 4
            : 0;

        if (projectId) {
            try {
                const cached = JSON.parse(localStorage.getItem(`skriptlab_book_metrics_${projectId}`) || 'null');
                if (cached && String(cached.project_id || '') === String(projectId)) {
                    estimatedPageCount = Number(cached.estimated_page_count || estimatedPageCount);
                    wordCount = Number(cached.word_count || wordCount);
                    characterCount = Number(cached.character_count || characterCount);
                }
            } catch (error) {
                // Käytetään käsikirjoituksesta laskettuja arvoja.
            }
        }
        return {
            estimated_page_count: Math.max(0, Math.round(estimatedPageCount || 0)),
            word_count: Math.max(0, Math.round(wordCount || 0)),
            character_count: Math.max(0, Math.round(characterCount || 0)),
        };
    }

    function renderProductBookMetrics(metrics = currentProductBookMetrics()) {
        const pages = document.getElementById('product-book-pages');
        const words = document.getElementById('product-book-words');
        const characters = document.getElementById('product-book-characters');
        if (pages) pages.textContent = metrics.estimated_page_count ? `≈ ${formatNumber(metrics.estimated_page_count)}` : '—';
        if (words) words.textContent = metrics.word_count ? formatNumber(metrics.word_count) : '—';
        if (characters) characters.textContent = metrics.character_count ? formatNumber(metrics.character_count) : '—';
    }

    function productInfoFromAnalysis() {
        const analysis = window.manuscriptData?.analysis || {};
        const saved = analysis.product_info && typeof analysis.product_info === 'object' ? analysis.product_info : {};
        const info = {};
        Object.keys(productFieldMap).forEach(key => {
            info[key] = String(saved[key] || '').trim();
        });
        info.title = info.title || window.manuscriptData?.title || '';
        info.author = info.author || window.manuscriptData?.author || '';
        info.author_role = info.author_role || (info.author ? 'Tekijä, kirjoittaja' : '');
        info.contributors = info.contributors || (info.author ? `Kirjailija: ${info.author}` : '');
        info.product_format = info.product_format || 'Painettu kirja / e-kirja';
        info.language = info.language || 'suomi';
        info.is_translation = info.is_translation || 'Ei';
        info.ai_written = info.ai_written || 'Ei';
        info.ai_interior_images = info.ai_interior_images || 'Ei';
        info.main_content = info.main_content || 'Tekstiä';
        info.audience = info.audience || analysis.audience || '';
        info.genre = info.genre || analysis.genre || '';
        info.product_group = info.product_group || info.genre || '';
        info.thema_classes = info.thema_classes || analysis.thema_classes || '';
        info.main_subject = info.main_subject || analysis.main_subject || info.thema_classes || info.genre || '';
        info.additional_subjects = info.additional_subjects || analysis.additional_subjects || '';
        info.library_class = info.library_class || analysis.library_class || '';
        info.keywords = info.keywords || analysis.keywords || '';
        info.short_description = info.short_description || analysis.marketing_short || '';
        info.long_description = info.long_description || analysis.marketing_long || '';
        info.backcover = info.backcover || analysis.backcover || analysis.backcover_text || '';
        info.onix_summary = info.onix_summary || analysis.onix || '';
        const bookMetrics = currentProductBookMetrics();
        info.estimated_page_count = String(bookMetrics.estimated_page_count || '');
        info.word_count = String(bookMetrics.word_count || '');
        info.character_count = String(bookMetrics.character_count || '');
        renderProductBookMetrics(bookMetrics);
        info.missing_fields = Array.isArray(saved.missing_fields) ? saved.missing_fields : [];
        info.missing_fields = productMissingFieldKeys(info);
        return info;
    }

    function setProductFields(info, force = false) {
        Object.entries(productFieldMap).forEach(([key, id]) => {
            setMarketingFieldValue(id, info?.[key] || '', force || productDerivedFieldKeys.has(key));
        });
        markProductMissingFields();
    }

    function mergeProductInfo(existing, generated) {
        const merged = {};
        Object.keys(productFieldMap).forEach(key => {
            const currentValue = String(existing?.[key] || '').trim();
            const generatedValue = String(generated?.[key] || '').trim();
            if (currentValue && productManualFieldKeys.has(key)) {
                merged[key] = currentValue;
            } else if (generatedValue) {
                merged[key] = generatedValue;
            } else {
                merged[key] = currentValue;
            }
        });
        merged.missing_fields = productMissingFieldKeys({
            ...merged,
            missing_fields: Array.isArray(generated?.missing_fields) ? generated.missing_fields : []
        });
        return merged;
    }

    function applyProductInfoToAnalysis(info) {
        if (!window.manuscriptData) return;
        if (!window.manuscriptData.analysis) window.manuscriptData.analysis = {};
        window.manuscriptData.analysis.product_info = info;
        window.manuscriptData.analysis.onix = info.onix_summary || '';
        if (info.audience) window.manuscriptData.analysis.audience = info.audience;
        if (info.genre) window.manuscriptData.analysis.genre = info.genre;
        if (info.main_subject) window.manuscriptData.analysis.main_subject = info.main_subject;
        if (info.additional_subjects) window.manuscriptData.analysis.additional_subjects = info.additional_subjects;
        if (info.thema_classes) window.manuscriptData.analysis.thema_classes = info.thema_classes;
        if (info.library_class) window.manuscriptData.analysis.library_class = info.library_class;
        if (info.keywords) window.manuscriptData.analysis.keywords = info.keywords;
        if (info.short_description) window.manuscriptData.analysis.marketing_short = info.short_description;
        if (info.long_description) window.manuscriptData.analysis.marketing_long = info.long_description;
        if (info.backcover) window.manuscriptData.analysis.backcover = info.backcover;
    }

    async function saveProductInfo() {
        if (!window.manuscriptData) {
            setProductStatus('Valitse käsikirjoitus ensin.', true);
            return null;
        }
        const info = collectProductFields();
        applyProductInfoToAnalysis(info);
        const savedProject = await window.saveManuscriptToDB(window.manuscriptData);
        if (savedProject?.id) window.manuscriptData = savedProject;
        setProductFields(info, true);
        renderAnalysisSummary(window.manuscriptData.analysis);
        renderMarketingMaterialsFromAnalysis(false);
        const missingCount = markProductMissingFields(info);
        const syncPending = Boolean(window.manuscriptData?._db_sync_pending);
        const suffix = missingCount ? `${missingCount} tärkeää kenttää odottaa täydennystä.` : 'Tärkeät kentät ovat täytettynä.';
        setProductStatus(syncPending ? `Tuotetiedot tallennettu paikallisesti, tietokantasynkronointi odottaa. ${suffix}` : `Tuotetiedot tallennettu. ${suffix}`, syncPending);
        return info;
    }

    function renderProductInfo(force = false) {
        const current = document.getElementById('product-current-project');
        if (current) {
            current.textContent = window.manuscriptData
                ? `Käsikirjoitus: ${window.manuscriptData.title || 'Nimetön'}`
                : 'Käsikirjoitus: [Ei aktiivista teosta]';
        }
        if (!window.manuscriptData) {
            setProductFields({}, true);
            renderProductBookMetrics({ estimated_page_count: 0, word_count: 0, character_count: 0 });
            setProductStatus('Valitse käsikirjoitus ensin.', true);
            return;
        }
        const info = productInfoFromAnalysis();
        setProductFields(info, force);
        const missingCount = markProductMissingFields();
        if (!hasSavedAnalysis(window.manuscriptData.analysis)) {
            setProductStatus('Tee ensin analyysi, jotta tuotetiedot voidaan muodostaa teoksen metatiedoista.', true);
        } else if (window.manuscriptData.analysis?.product_info) {
            setProductStatus(missingCount ? `Tallennetut tuotetiedot ladattu. ${missingCount} tärkeää kenttää odottaa täydennystä.` : 'Tallennetut tuotetiedot ladattu.');
        } else {
            setProductStatus('Analyysi löytyi. Voit generoida tuotetietoluonnoksen AI:lla.');
        }
    }

    async function generateProductInfo(options = {}) {
        if (!window.manuscriptData) {
            setProductStatus('Valitse käsikirjoitus ensin.', true);
            return null;
        }
        if (!hasSavedAnalysis(window.manuscriptData.analysis)) {
            setProductStatus('Tee analyysi ensin. Tuotetiedot hyödyntävät analyysin genreä, kohderyhmää, synopsista ja metatietoja.', true);
            return null;
        }
        if (!window.manuscriptData.id) {
            const savedProject = await window.saveManuscriptToDB(window.manuscriptData);
            if (savedProject?.id) window.manuscriptData = savedProject;
        }
        if (!window.manuscriptData?.id) {
            setProductStatus('Käsikirjoitusta ei saatu tallennettua ennen tuotetietojen generointia.', true);
            return null;
        }

        const button = document.getElementById('product-generate-btn');
        if (button) button.disabled = true;
        setProductStatus('Generoidaan tuotetietoja analyysin ja käsikirjoitustietojen pohjalta...');
        try {
            const res = await apiFetch('/api/product-info/generate', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    project_id: window.manuscriptData.id,
                    model: typeof options?.model === 'string' ? options.model : null
                })
            });
            const data = await res.json().catch(() => null);
            if (!res.ok) throw new Error(data?.detail || 'Tuotetietojen generointi epäonnistui.');
            const merged = mergeProductInfo(collectProductFields(), data);
            const bookMetrics = currentProductBookMetrics();
            merged.estimated_page_count = String(bookMetrics.estimated_page_count || '');
            merged.word_count = String(bookMetrics.word_count || '');
            merged.character_count = String(bookMetrics.character_count || '');
            renderProductBookMetrics(bookMetrics);
            applyProductInfoToAnalysis(merged);
            const savedProject = await window.saveManuscriptToDB(window.manuscriptData);
            if (savedProject?.id) window.manuscriptData = savedProject;
            setProductFields(merged, true);
            renderAnalysisSummary(window.manuscriptData.analysis);
            renderMarketingMaterialsFromAnalysis(false);
            const missingCount = markProductMissingFields(merged);
            const missingText = missingCount ? ` ${missingCount} tärkeää kenttää jäi käsin täydennettäväksi.` : '';
            setProductStatus(data.warnings ? `${data.warnings}${missingText} Lähde: ${data.generated_by}.` : `Tuotetiedot generoitu ja tallennettu.${missingText} Lähde: ${data.generated_by}.`);
            loadUsage();
            return merged;
        } catch (err) {
            setProductStatus(err.message, true);
            alert('Tuotetietojen generointi epäonnistui: ' + networkFailureMessage(err));
            loadUsage();
            return null;
        } finally {
            if (button) button.disabled = false;
        }
    }

	    function marketingAnalysisText(analysis, keys, fallback = '') {
	        for (const key of keys) {
	            const value = analysis?.[key];
	            if (typeof value === 'string' && value.trim()) return value.trim();
	        }
	        return fallback;
	    }

	    function showMarketingPanel(panelId, focus = false) {
	        const panelIds = ['marketing-campaign-panel', 'marketing-html-panel'];
	        const selectedPanelId = panelIds.includes(panelId) ? panelId : panelIds[0];
	        document.querySelectorAll('.marketing-workspace-tab').forEach(tab => {
	            const active = tab.dataset.marketingPanel === selectedPanelId;
	            tab.classList.toggle('active', active);
	            tab.setAttribute('aria-selected', active ? 'true' : 'false');
	            tab.tabIndex = active ? 0 : -1;
	            if (active && focus) tab.focus();
	        });
	        panelIds.forEach(id => {
	            const panel = document.getElementById(id);
	            if (!panel) return;
	            const active = id === selectedPanelId;
	            panel.hidden = !active;
	            panel.setAttribute('aria-hidden', active ? 'false' : 'true');
	        });
	        if (selectedPanelId === 'marketing-html-panel') renderMarketingHtmlWorkspace();
	    }

	    function showMarketingCampaignPanel(panelId, focus = false) {
	        const panelIds = [
	            'marketing-campaign-plan-panel',
	            'marketing-campaign-preview-panel',
	            'marketing-campaign-copy-panel',
	            'marketing-campaign-launch-panel'
	        ];
	        const selectedPanelId = panelIds.includes(panelId) ? panelId : panelIds[0];
	        document.querySelectorAll('#marketing-campaign-panel .marketing-campaign-stage-tab').forEach(tab => {
	            const active = tab.dataset.marketingCampaignPanel === selectedPanelId;
	            tab.classList.toggle('active', active);
	            tab.setAttribute('aria-selected', active ? 'true' : 'false');
	            tab.tabIndex = active ? 0 : -1;
	            if (active && focus) tab.focus();
	        });
	        panelIds.forEach(id => {
	            const panel = document.getElementById(id);
	            if (!panel) return;
	            const active = id === selectedPanelId;
	            panel.hidden = !active;
	            panel.setAttribute('aria-hidden', active ? 'false' : 'true');
	        });
	        if (selectedPanelId === 'marketing-campaign-preview-panel') renderMarketingStudioVisuals();
	    }

	    function selectedMarketingCover() {
	        const selectedId = document.getElementById('marketing-cover-select')?.value || '';
	        return marketingContextCovers.find(item => String(item.id) === String(selectedId)) || null;
	    }

    function renderMarketingCoverTarget(element, cover) {
        if (!element) return;
        element.innerHTML = cover?.data_url
            ? `<img src="${cover.data_url}" alt="${escapeHtml(cover.title || 'Kampanjakansi')}">`
            : '<span>KANSI</span>';
    }

	    function marketingFieldValue(id, fallback = '') {
	        return document.getElementById(id)?.value?.trim() || fallback;
	    }

	    function setMarketingHtmlStatus(message, isError = false) {
	        const status = document.getElementById('marketing-html-status');
	        if (!status) return;
	        status.textContent = message || '';
	        status.classList.toggle('is-error', Boolean(isError));
	        status.style.color = isError ? '#ffb4b4' : 'var(--text-secondary)';
	    }

	    function clearMarketingHtmlResult() {
	        latestMarketingHtmlPage = null;
	        const frame = document.getElementById('marketing-html-preview-frame');
	        const empty = document.getElementById('marketing-html-preview-empty');
	        const download = document.getElementById('marketing-html-download-btn');
	        const name = document.getElementById('marketing-html-result-name');
	        const meta = document.getElementById('marketing-html-result-meta');
	        clearHtmlPreviewFrame(frame);
	        setHtmlPreviewPlaceholder(
	            empty,
	            'Esikatselu avautuu tähän',
	            'Kun kaikki kolme lähtöaineistoa ovat valmiina, luo ensimmäinen sivu.'
	        );
	        if (download) download.disabled = true;
	        if (name) name.textContent = 'Ei vielä luotua tiedostoa';
	        if (meta) meta.textContent = 'Yhden tiedoston HTML · upotettu kansikuva · responsiivinen';
	        const browserName = document.getElementById('marketing-html-browser-name');
	        if (browserName) browserName.textContent = 'kirjan-esittely.html';
	    }

	    function renderMarketingHtmlWorkspace() {
	        const project = window.manuscriptData;
	        const cover = selectedMarketingCover();
	        const coverTarget = document.getElementById('marketing-html-cover');
	        renderMarketingCoverTarget(coverTarget, cover);
	        if (coverTarget && !cover) coverTarget.innerHTML = '<span>KANSI VAADITAAN</span>';

	        const title = project?.title || 'Valitse kirja ja kansi';
	        const tagline = marketingFieldValue(
	            'marketing-tagline',
	            project ? `${title} — teoksen oma sivu analyysin ja kontekstimuistin pohjalta.` : 'Teoksen oma sivu syntyy analyysin ja kontekstimuistin pohjalta.'
	        );
	        const previewTitle = document.getElementById('marketing-html-preview-title');
	        const previewTagline = document.getElementById('marketing-html-preview-tagline');
	        if (previewTitle) previewTitle.textContent = title;
	        if (previewTagline) previewTagline.textContent = tagline;

	        const contextMatches = Boolean(
	            project?.id && String(marketingContextSummary.projectId || '') === String(project.id)
	        );
	        const analysisReady = contextMatches && marketingContextSummary.analysisAvailable;
	        const memoryCount = contextMatches ? Number(marketingContextSummary.projectMemoryCount || 0) : 0;
	        const memoryReady = memoryCount > 0;
	        const coverReady = Boolean(cover);
	        const readiness = [
	            ['marketing-html-analysis-readiness', analysisReady],
	            ['marketing-html-memory-readiness', memoryReady],
	            ['marketing-html-cover-readiness', coverReady]
	        ];
	        readiness.forEach(([id, ready]) => {
	            const item = document.getElementById(id);
	            if (!item) return;
	            item.classList.toggle('is-ready', ready);
	            item.classList.toggle('is-missing', Boolean(project) && !ready);
	        });

	        const analysisDetail = document.getElementById('marketing-html-analysis-detail');
	        const memoryDetail = document.getElementById('marketing-html-memory-detail');
	        const coverDetail = document.getElementById('marketing-html-cover-detail');
	        if (analysisDetail) {
	            analysisDetail.textContent = !project
	                ? 'Odottaa aktiivista projektia'
	                : analysisReady ? 'Tallennettu analyysi käytettävissä' : 'Tee projektin analyysi ensin';
	        }
	        if (memoryDetail) {
	            memoryDetail.textContent = !project
	                ? 'Odottaa aktiivista projektia'
	                : memoryReady ? `${memoryCount} käyttökelpoista muistimerkintää` : 'Täydennä ja tarkista kontekstimuisti';
	        }
	        if (coverDetail) {
	            coverDetail.textContent = coverReady ? (cover.title || 'Kansikuva valittu') : 'Valitse kansi yläreunasta';
	        }

	        if (latestMarketingHtmlPage && (
	            String(latestMarketingHtmlPage.projectId) !== String(project?.id || '')
	            || String(latestMarketingHtmlPage.coverAssetId) !== String(cover?.id || '')
	        )) clearMarketingHtmlResult();

	        const ready = Boolean(project?.id && analysisReady && memoryReady && coverReady);
	        const button = document.getElementById('marketing-html-generate-btn');
	        if (button) button.disabled = marketingHtmlGenerating || !ready;
	        if (!marketingHtmlGenerating) {
	            if (!project) {
	                setMarketingHtmlStatus('Valitse ensin käsikirjoitus.', true);
	            } else if (!contextMatches) {
	                setMarketingHtmlStatus('Tarkistetaan projektin lähtöaineistoja…');
	            } else if (!analysisReady) {
	                setMarketingHtmlStatus('HTML-sivu vaatii tallennetun analyysin.', true);
	            } else if (!memoryReady) {
	                setMarketingHtmlStatus('HTML-sivu vaatii vahvistettua tai tarkistettavaa kontekstimuistia.', true);
	            } else if (!coverReady) {
	                setMarketingHtmlStatus('Valitse vähintään yksi kansikuva yläreunasta.', true);
	            } else if (latestMarketingHtmlPage) {
	                setMarketingHtmlStatus('HTML-markkinointisivu on valmis esikatseltavaksi ja ladattavaksi.');
	            } else {
	                setMarketingHtmlStatus('Kaikki lähtöaineistot ovat valmiina. Voit luoda HTML-markkinointisivun.');
	            }
	        }
	    }

	    function renderMarketingStudioVisuals() {
	        const cover = selectedMarketingCover();
        renderMarketingCoverTarget(document.getElementById('marketing-hero-cover'), cover);
        renderMarketingCoverTarget(document.getElementById('marketing-preview-instagram-cover'), cover);
        renderMarketingCoverTarget(document.getElementById('marketing-preview-story-cover'), cover);

        const title = window.manuscriptData?.title || 'Teos';
        const tagline = marketingFieldValue('marketing-tagline', `${title} — tarina, joka jää mieleen.`);
        const emailSubject = marketingFieldValue('marketing-email-subject', `Tutustu teokseen ${title}`);
        const pressPitch = marketingFieldValue('marketing-press-pitch', 'Mediapitch muodostuu analyysin ja kampanjakonseptin perusteella.');
        const video = marketingFieldValue('marketing-video', 'Koukku, tunnelma ja toimintakehotus yhdessä käsikirjoituksessa.');
        const setText = (id, value) => {
            const element = document.getElementById(id);
            if (element) element.textContent = value;
        };
        setText('marketing-hero-tagline', tagline);
        setText('marketing-preview-instagram-tagline', tagline);
        setText('marketing-preview-story-tagline', tagline);
        setText('marketing-preview-email-subject', emailSubject);
        setText('marketing-preview-press-pitch', pressPitch);
        setText('marketing-preview-video-hook', video.split('\n').find(Boolean) || video);

        const readiness = [
            marketingFieldValue('marketing-campaign-concept'),
            marketingFieldValue('marketing-tagline'),
            marketingFieldValue('marketing-short'),
            [
                marketingFieldValue('marketing-instagram'),
                marketingFieldValue('marketing-facebook'),
                marketingFieldValue('marketing-tiktok'),
                marketingFieldValue('marketing-video')
            ].some(Boolean) ? 'channels' : ''
	        ].filter(Boolean).length;
	        setText('marketing-readiness-count', `${readiness}/4`);
	        renderMarketingHtmlWorkspace();
	    }

    function populateMarketingCovers(covers = []) {
        marketingContextCovers = Array.isArray(covers) ? covers : [];
        const select = document.getElementById('marketing-cover-select');
        if (!select) return;
        const previous = select.value;
	        select.innerHTML = [
	            '<option value="">Valitse kansikuva</option>',
            ...marketingContextCovers.map((cover, index) => (
                `<option value="${cover.id}">${escapeHtml(cover.title || `Kansi ${index + 1}`)}</option>`
            ))
        ].join('');
        if (marketingContextCovers.some(item => String(item.id) === String(previous))) {
            select.value = previous;
        } else if (marketingContextCovers.length) {
            select.value = String(marketingContextCovers[0].id);
        }
	        renderMarketingStudioVisuals();
	    }

	    async function loadMarketingContext() {
	        const requestedProjectId = window.manuscriptData?.id || null;
	        if (!requestedProjectId) {
	            marketingContextSummary = { projectId: null, analysisAvailable: false, projectMemoryCount: 0 };
	            populateMarketingCovers([]);
	            return;
	        }
	        if (String(marketingContextSummary.projectId || '') !== String(requestedProjectId)) {
	            marketingContextSummary = { projectId: null, analysisAvailable: false, projectMemoryCount: 0 };
	            populateMarketingCovers([]);
	        }
	        try {
	            const response = await apiFetch(`/api/projects/${requestedProjectId}/marketing/context`);
	            const data = await response.json().catch(() => null);
	            if (!response.ok) throw new Error(data?.detail || 'Kampanjan kansien lataus epäonnistui.');
	            if (String(window.manuscriptData?.id || '') !== String(requestedProjectId)) return;
	            marketingContextSummary = {
	                projectId: requestedProjectId,
	                analysisAvailable: Boolean(data?.analysis_available),
	                projectMemoryCount: Number(data?.project_memory_count || 0)
	            };
	            populateMarketingCovers(data?.covers || []);
            const genre = document.getElementById('marketing-genre-badge');
            const audience = document.getElementById('marketing-audience-badge');
            if (genre) genre.textContent = data?.genre || 'Genre odottaa analyysiä';
	            if (audience) audience.textContent = data?.audience || 'Kohderyhmä odottaa analyysiä';
	        } catch (error) {
	            if (String(window.manuscriptData?.id || '') !== String(requestedProjectId)) return;
	            marketingContextSummary = { projectId: requestedProjectId, analysisAvailable: false, projectMemoryCount: 0 };
	            populateMarketingCovers([]);
	            setMarketingStatus(error.message, true);
	            setMarketingHtmlStatus(error.message, true);
	        }
	    }

    function renderMarketingMaterialsFromAnalysis(force = false) {
        const current = document.getElementById('marketing-current-project');
        if (current) {
            current.textContent = window.manuscriptData
                ? `Käsikirjoitus: ${window.manuscriptData.title || 'Nimetön'}`
                : 'Käsikirjoitus: [Ei aktiivista teosta]';
        }
        const analysis = window.manuscriptData?.analysis || {};
        const title = window.manuscriptData?.title || 'Teos';
        const productInfo = analysis.product_info && typeof analysis.product_info === 'object' ? analysis.product_info : {};
        const shortText = analysis.marketing_short || analysis.backcover || analysis.synopsis || '';
        const longText = analysis.marketing_long || analysis.backcover || analysis.synopsis || '';
        setMarketingFieldValue('marketing-campaign-concept', analysis.campaign_concept || '', force);
        setMarketingFieldValue('marketing-tagline', analysis.marketing_tagline || '', force);
        setMarketingFieldValue('marketing-key-messages', analysis.marketing_key_messages || analysis.sales_points || productInfo.sales_points || '', force);
        setMarketingFieldValue('marketing-short', shortText, force);
        setMarketingFieldValue('marketing-long', longText, force);
        setMarketingFieldValue('marketing-instagram', analysis.instagram_post || '', force);
        setMarketingFieldValue('marketing-facebook', analysis.facebook_post || '', force);
        setMarketingFieldValue('marketing-tiktok', analysis.tiktok_post || '', force);
        setMarketingFieldValue('marketing-video', analysis.video_script || '', force);
        setMarketingFieldValue('marketing-hashtags', analysis.hashtags || '', force);
        setMarketingFieldValue('marketing-email-subject', analysis.marketing_email_subject || '', force);
        setMarketingFieldValue('marketing-press-pitch', analysis.marketing_press_pitch || '', force);
        setMarketingFieldValue('marketing-content-calendar', analysis.marketing_content_calendar || '', force);
        setMarketingFieldValue('marketing-campaign-focus', analysis.marketing_campaign_focus || '', force);
        const genreBadge = document.getElementById('marketing-genre-badge');
        const audienceBadge = document.getElementById('marketing-audience-badge');
        if (genreBadge) genreBadge.textContent = marketingAnalysisText(analysis, ['genre'], productInfo.genre || 'Genre odottaa analyysiä');
        if (audienceBadge) audienceBadge.textContent = marketingAnalysisText(analysis, ['audience', 'target_audience'], productInfo.audience || 'Kohderyhmä odottaa analyysiä');
        renderMarketingStudioVisuals();
        if (!window.manuscriptData) {
            setMarketingStatus('Valitse käsikirjoitus ensin.', true);
        } else if (!hasSavedAnalysis(analysis)) {
            setMarketingStatus('Tee ensin analyysi, jotta aineistot voidaan muodostaa teoksen metatiedoista.', true);
        } else if (!shortText && !longText) {
            setMarketingStatus(`${title}: analyysi löytyi. Voit luoda markkinointiaineistot AI:lla.`);
        } else {
            setMarketingStatus(`${title}: analyysin markkinointitiedot ladattu. Voit luoda uuden kampanjapaketin AI:lla.`);
        }
    }

    async function generateMarketingMaterials(options = {}) {
        if (!window.manuscriptData) {
            setMarketingStatus('Valitse käsikirjoitus ensin.', true);
            return;
        }
        if (!hasSavedAnalysis(window.manuscriptData.analysis)) {
            setMarketingStatus('Tee analyysi ensin. Markkinointiaineistot hyödyntävät analyysin synopsista, genreä, kohderyhmää ja tyyliä.', true);
            return;
        }
        if (!window.manuscriptData.id) {
            const savedProject = await window.saveManuscriptToDB(window.manuscriptData);
            if (savedProject?.id) window.manuscriptData = savedProject;
        }
        if (!window.manuscriptData?.id) {
            setMarketingStatus('Käsikirjoitusta ei saatu tallennettua ennen markkinointiaineistoja.', true);
            return;
        }

        const button = document.getElementById('marketing-generate-btn');
        if (button) {
            button.disabled = true;
            button.textContent = 'Rakennetaan kampanjaa…';
        }
        const goalSelect = document.getElementById('marketing-campaign-goal');
        const toneSelect = document.getElementById('marketing-campaign-tone');
        const campaignGoal = [
            goalSelect?.selectedOptions?.[0]?.textContent || '',
            marketingFieldValue('marketing-campaign-focus') ? `Painotus: ${marketingFieldValue('marketing-campaign-focus')}` : '',
            toneSelect?.selectedOptions?.[0]?.textContent ? `Sävy: ${toneSelect.selectedOptions[0].textContent}` : ''
        ].filter(Boolean).join('. ');
        setMarketingStatus('Rakennetaan kampanjakonseptia, kanavatekstejä ja lanseerauksen rytmiä…');
        try {
            const res = await apiFetch('/api/marketing/materials', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    project_id: window.manuscriptData.id,
                    model: typeof options?.model === 'string' ? options.model : null,
                    campaign_goal: campaignGoal
                })
            });
            const data = await res.json().catch(() => null);
            if (!res.ok) throw new Error(data?.detail || 'Markkinointiaineistojen luonti epäonnistui.');
            setMarketingFieldValue('marketing-campaign-concept', data.campaign_concept, true);
            setMarketingFieldValue('marketing-tagline', data.tagline, true);
            setMarketingFieldValue('marketing-key-messages', data.key_messages, true);
            setMarketingFieldValue('marketing-short', data.short_description, true);
            setMarketingFieldValue('marketing-long', data.long_description, true);
            setMarketingFieldValue('marketing-instagram', data.instagram_post, true);
            setMarketingFieldValue('marketing-facebook', data.facebook_post, true);
            setMarketingFieldValue('marketing-tiktok', data.tiktok_post, true);
            setMarketingFieldValue('marketing-video', data.video_script, true);
            setMarketingFieldValue('marketing-hashtags', data.hashtags, true);
            setMarketingFieldValue('marketing-email-subject', data.email_subject, true);
            setMarketingFieldValue('marketing-press-pitch', data.press_pitch, true);
            setMarketingFieldValue('marketing-content-calendar', data.content_calendar, true);
            if (!window.manuscriptData.analysis) window.manuscriptData.analysis = {};
            window.manuscriptData.analysis.campaign_concept = data.campaign_concept || '';
            window.manuscriptData.analysis.marketing_tagline = data.tagline || '';
            window.manuscriptData.analysis.marketing_key_messages = data.key_messages || '';
            window.manuscriptData.analysis.marketing_short = data.short_description || '';
            window.manuscriptData.analysis.marketing_long = data.long_description || '';
            window.manuscriptData.analysis.instagram_post = data.instagram_post || '';
            window.manuscriptData.analysis.facebook_post = data.facebook_post || '';
            window.manuscriptData.analysis.tiktok_post = data.tiktok_post || '';
            window.manuscriptData.analysis.video_script = data.video_script || '';
            window.manuscriptData.analysis.hashtags = data.hashtags || '';
            window.manuscriptData.analysis.marketing_email_subject = data.email_subject || '';
            window.manuscriptData.analysis.marketing_press_pitch = data.press_pitch || '';
            window.manuscriptData.analysis.marketing_content_calendar = data.content_calendar || '';
	            window.manuscriptData.analysis.marketing_campaign_focus = marketingFieldValue('marketing-campaign-focus');
	            await window.saveManuscriptToDB(window.manuscriptData);
	            renderProductInfo(false);
	            clearMarketingHtmlResult();
	            renderMarketingStudioVisuals();
            setMarketingStatus(data.warnings ? `${data.warnings} Lähde: ${data.generated_by}.` : `Kampanjapaketti valmis muokattavaksi. Lähde: ${data.generated_by}.`);
            loadUsage();
            return data;
        } catch (err) {
            setMarketingStatus(err.message, true);
            alert('Markkinointiaineistojen luonti epäonnistui: ' + networkFailureMessage(err));
            loadUsage();
            return null;
        } finally {
            if (button) {
                button.disabled = false;
                button.textContent = 'Luo kampanjapaketti AI:lla';
            }
        }
    }

    function marketingPackagePayload() {
        const goal = document.getElementById('marketing-campaign-goal')?.selectedOptions?.[0]?.textContent || '';
        const focus = marketingFieldValue('marketing-campaign-focus');
        const tone = document.getElementById('marketing-campaign-tone')?.selectedOptions?.[0]?.textContent || '';
        const coverValue = document.getElementById('marketing-cover-select')?.value || '';
        return {
            project_id: window.manuscriptData?.id || null,
            cover_asset_id: coverValue ? Number(coverValue) : null,
            campaign_goal: [goal, focus ? `Painotus: ${focus}` : '', tone ? `Sävy: ${tone}` : ''].filter(Boolean).join('. '),
            campaign_concept: marketingFieldValue('marketing-campaign-concept'),
            tagline: marketingFieldValue('marketing-tagline'),
            key_messages: marketingFieldValue('marketing-key-messages'),
            short_description: marketingFieldValue('marketing-short'),
            long_description: marketingFieldValue('marketing-long'),
            instagram_post: marketingFieldValue('marketing-instagram'),
            facebook_post: marketingFieldValue('marketing-facebook'),
            tiktok_post: marketingFieldValue('marketing-tiktok'),
            video_script: marketingFieldValue('marketing-video'),
            hashtags: marketingFieldValue('marketing-hashtags'),
            email_subject: marketingFieldValue('marketing-email-subject'),
            press_pitch: marketingFieldValue('marketing-press-pitch'),
            content_calendar: marketingFieldValue('marketing-content-calendar')
        };
    }

	    async function downloadMarketingPackage() {
        const button = document.getElementById('marketing-download-package-btn');
        if (!window.manuscriptData?.id) {
            setMarketingStatus('Valitse käsikirjoitus ensin.', true);
            return;
        }
        const payload = marketingPackagePayload();
        if (!payload.campaign_concept && !payload.short_description && !payload.instagram_post) {
            setMarketingStatus('Luo tai kirjoita kampanja-aineistot ennen ZIP-paketin muodostamista.', true);
            return;
        }
        if (button) {
            button.disabled = true;
            button.textContent = 'Muodostetaan ZIP…';
        }
        setMarketingStatus('Kootaan brief, kanavatekstit, media-aineisto, kalenteri ja kansi ZIP-pakettiin…');
        try {
            const response = await apiFetch('/api/marketing/package', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify(payload)
            });
            const data = await response.json().catch(() => null);
            if (!response.ok) throw new Error(data?.detail || 'Markkinointipaketin muodostaminen epäonnistui.');
            if (!data?.package?.data_url) throw new Error('Markkinointipaketin lataustiedostoa ei saatu.');
            const link = document.createElement('a');
            link.href = data.package.data_url;
            link.download = data.filename || 'markkinointipaketti.zip';
            document.body.appendChild(link);
            link.click();
            link.remove();
            setMarketingStatus(`Markkinointipaketti valmis: ${Number(data.files?.length || 0)} tiedostoa.`);
        } catch (error) {
            setMarketingStatus(error.message, true);
        } finally {
            if (button) {
                button.disabled = false;
                button.textContent = 'Muodosta ja lataa ZIP';
            }
	        }
	    }

	    function downloadLatestMarketingHtmlPage() {
	        if (!latestMarketingHtmlPage?.dataUrl) {
	            setMarketingHtmlStatus('Luo HTML-markkinointisivu ennen lataamista.', true);
	            return;
	        }
	        const link = document.createElement('a');
	        link.href = latestMarketingHtmlPage.dataUrl;
	        link.download = latestMarketingHtmlPage.filename || 'kirjan-esittely.html';
	        document.body.appendChild(link);
	        link.click();
	        link.remove();
	        setMarketingHtmlStatus(`HTML-tiedosto ladattu: ${latestMarketingHtmlPage.filename}.`);
	    }

	    async function generateMarketingHtmlPage() {
	        const project = window.manuscriptData;
	        const cover = selectedMarketingCover();
	        const contextMatches = Boolean(
	            project?.id && String(marketingContextSummary.projectId || '') === String(project.id)
	        );
	        if (!project?.id) {
	            setMarketingHtmlStatus('Valitse käsikirjoitus ensin.', true);
	            return;
	        }
	        if (!contextMatches || !marketingContextSummary.analysisAvailable) {
	            setMarketingHtmlStatus('Tee ja tallenna projektin analyysi ennen HTML-sivun luontia.', true);
	            return;
	        }
	        if (Number(marketingContextSummary.projectMemoryCount || 0) < 1) {
	            setMarketingHtmlStatus('Täydennä kontekstimuistiin vähintään yksi vahvistettu tai tarkistettava tieto.', true);
	            return;
	        }
	        if (!cover?.id) {
	            setMarketingHtmlStatus('Valitse vähintään yksi kansikuva yläreunasta.', true);
	            return;
	        }

	        const urlInputs = [
	            document.getElementById('marketing-html-primary-url'),
	            document.getElementById('marketing-html-secondary-url')
	        ];
	        const invalidUrl = urlInputs.find(input => input?.value?.trim() && !input.checkValidity());
	        if (invalidUrl) {
	            invalidUrl.focus();
	            setMarketingHtmlStatus('Kirjoita toimintakehotteen osoite kokonaisena https://-osoitteena.', true);
	            return;
	        }

	        const payload = {
	            project_id: project.id,
	            cover_asset_id: Number(cover.id),
	            visual_style: document.getElementById('marketing-html-style')?.value || 'editorial',
	            primary_cta_label: marketingFieldValue('marketing-html-primary-label', 'Tutustu kirjaan'),
	            primary_cta_url: marketingFieldValue('marketing-html-primary-url'),
	            secondary_cta_label: marketingFieldValue('marketing-html-secondary-label'),
	            secondary_cta_url: marketingFieldValue('marketing-html-secondary-url'),
	            tagline: marketingFieldValue('marketing-tagline'),
	            short_description: marketingFieldValue('marketing-short'),
	            long_description: marketingFieldValue('marketing-long'),
	            additional_instructions: marketingFieldValue('marketing-html-instructions')
	        };
	        const button = document.getElementById('marketing-html-generate-btn');
	        marketingHtmlGenerating = true;
	        if (button) button.textContent = 'Luodaan HTML-sivua…';
	        setMarketingHtmlStatus('Muodostetaan tekstit analyysistä ja kontekstimuistista sekä rakennetaan itsenäinen HTML-tiedosto…');
	        renderMarketingHtmlWorkspace();

	        let finalStatus = null;
	        try {
	            const response = await apiFetch('/api/marketing/landing-page', {
	                method: 'POST',
	                headers: {'Content-Type': 'application/json'},
	                body: JSON.stringify(payload)
	            });
	            const data = await response.json().catch(() => null);
	            if (!response.ok) throw new Error(data?.detail || 'HTML-markkinointisivun luonti epäonnistui.');
	            if (!data?.page?.data_url) throw new Error('Valmiin HTML-tiedoston sisältöä ei saatu.');
	            if (
	                String(window.manuscriptData?.id || '') !== String(project.id)
	                || String(selectedMarketingCover()?.id || '') !== String(cover.id)
	            ) return;

	            latestMarketingHtmlPage = {
	                projectId: project.id,
	                coverAssetId: cover.id,
	                dataUrl: data.page.data_url,
	                filename: htmlPresentationFilename(data.filename)
	            };
	            const frame = document.getElementById('marketing-html-preview-frame');
	            const empty = document.getElementById('marketing-html-preview-empty');
	            const download = document.getElementById('marketing-html-download-btn');
	            const name = document.getElementById('marketing-html-result-name');
	            const meta = document.getElementById('marketing-html-result-meta');
	            if (download) download.disabled = false;
	            if (name) name.textContent = latestMarketingHtmlPage.filename;
	            const browserName = document.getElementById('marketing-html-browser-name');
	            if (browserName) browserName.textContent = latestMarketingHtmlPage.filename;
	            if (meta) {
	                meta.textContent = `Analyysi · ${Number(data.project_memory_items_used || 0)} kontekstimuistin merkintää · valittu kansi`;
	            }
	            renderHtmlDataUrlPreview(frame, empty, latestMarketingHtmlPage.dataUrl, latestMarketingHtmlPage.filename);
	            const warnings = Array.isArray(data.warnings) ? data.warnings.filter(Boolean) : [];
	            finalStatus = {
	                message: warnings.length
	                    ? `HTML-markkinointisivu valmis. ${warnings.join(' ')}`
	                    : 'HTML-markkinointisivu valmis esikatseltavaksi ja ladattavaksi.',
	                isError: false
	            };
	            loadUsage();
	        } catch (error) {
	            finalStatus = { message: networkFailureMessage(error), isError: true };
	            loadUsage();
	        } finally {
	            marketingHtmlGenerating = false;
	            if (button) button.textContent = 'Luo HTML-markkinointisivu';
	            renderMarketingHtmlWorkspace();
	            if (finalStatus) setMarketingHtmlStatus(finalStatus.message, finalStatus.isError);
	        }
	    }

	    async function copyMarketingField(targetId) {
        const element = document.getElementById(targetId);
        const text = element?.value || '';
        if (!text.trim()) {
            setMarketingStatus('Ei kopioitavaa tekstiä.', true);
            return;
        }
        try {
            await navigator.clipboard.writeText(text);
            setMarketingStatus('Teksti kopioitu leikepöydälle.');
        } catch (err) {
            setMarketingStatus('Kopiointi epäonnistui. Voit valita tekstin ja kopioida sen käsin.', true);
        }
    }

    function marketingShareText(targetId, extraTargetId = '') {
        const mainText = document.getElementById(targetId)?.value?.trim() || '';
        const extraText = extraTargetId ? document.getElementById(extraTargetId)?.value?.trim() || '' : '';
        return [mainText, extraText].filter(Boolean).join('\n\n');
    }

    async function shareMarketingField(targetId, channel, extraTargetId = '') {
        const text = marketingShareText(targetId, extraTargetId);
        if (!text) {
            setMarketingStatus('Ei jaettavaa tekstiä.', true);
            return;
        }
        const title = `${window.manuscriptData?.title || 'SkriptLab'} - ${channel || 'markkinointiteksti'}`;
        if (typeof navigator.share === 'function') {
            try {
                await navigator.share({ title, text });
                setMarketingStatus(`${channel || 'Aineisto'} jaettu laitteen jakovalikolla.`);
                return;
            } catch (err) {
                if (err?.name === 'AbortError') {
                    setMarketingStatus('Jakaminen peruutettu.');
                    return;
                }
            }
        }
        try {
            await navigator.clipboard.writeText(text);
            setMarketingStatus('Laitteen jakovalikko ei ole käytettävissä tässä selaimessa. Teksti kopioitiin leikepöydälle.');
        } catch (err) {
            setMarketingStatus('Jakaminen ei ole käytettävissä. Voit valita tekstin ja kopioida sen käsin.', true);
        }
    }

    function renderImageModelSelects() {
        const selects = [coverModelSelect, visualModelSelect].filter(Boolean);
        const defaultModel = imageModels.find(model => model.is_default) || imageModels[0] || null;
        selects.forEach(select => {
            const currentValue = select.value;
            if (!imageModels.length) {
                select.innerHTML = '<option value="">Ei käytössä olevia kuvamalleja</option>';
                return;
            }
            select.innerHTML = imageModels
                .map(model => `<option value="${escapeHtml(`${model.provider}:${model.model_name}`)}">${escapeHtml(`${model.display_name} · ${model.model_name}`)}</option>`)
                .join('');
            if (currentValue && Array.from(select.options).some(option => option.value === currentValue)) {
                select.value = currentValue;
            } else if (defaultModel) {
                select.value = `${defaultModel.provider}:${defaultModel.model_name}`;
            }
        });
        if (visualModelSelect) {
            if (visualImageBatchJobId && visualImageBatchLastStatus) {
                applyVisualProviderJobSettings(visualImageBatchLastStatus);
            } else {
                syncVisualModelCapabilities();
            }
            scheduleVisualEstimate();
        }
    }

    async function loadImageModels(force = false) {
        if (!isViewAllowed('view-kuvitus')) return [];
        if (!coverModelSelect && !visualModelSelect) return [];
        if (imageModels.length && !force) {
            renderImageModelSelects();
            return imageModels;
        }
        try {
            const res = await apiFetch('/api/models/image');
            const data = await res.json();
            if (!res.ok) throw new Error(data.detail || 'Kuvamallien lataus epäonnistui.');
            imageModels = data || [];
            renderImageModelSelects();
            return imageModels;
        } catch (err) {
            [coverModelSelect, visualModelSelect].filter(Boolean).forEach(select => {
                select.innerHTML = '<option value="">Kuvamalleja ei saatu ladattua</option>';
            });
            setIllustrationStatus(err.message, true);
            setVisualStatus(err.message, true);
            return [];
        }
    }

    function graphicAssetTypeLabel(asset) {
        return asset?.asset_type === 'infographic' ? 'Infografiikka' : 'Kuvaehdotus';
    }

    function graphicAssetDate(value) {
        const date = new Date(value || '');
        return Number.isNaN(date.getTime()) ? '' : date.toLocaleString('fi-FI', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
        });
    }

    function graphicAssetFileName(asset) {
        const projectTitle = safeFileStem(window.manuscriptData?.title || 'projekti', 'projekti');
        const assetTitle = safeFileStem(asset?.title || graphicAssetTypeLabel(asset), asset?.asset_type === 'infographic' ? 'infografiikka' : 'kuvaehdotus');
        const mime = String(asset?.mime_type || '').toLowerCase();
        const extension = mime.includes('jpeg') || mime.includes('jpg')
            ? 'jpg'
            : mime.includes('webp')
                ? 'webp'
                : mime.includes('svg')
                    ? 'svg'
                    : 'png';
        return `${projectTitle}-${assetTitle}.${extension}`;
    }

    function graphicAssetStatusSetter(asset) {
        return asset?.asset_type === 'infographic' ? setInfographicStatus : setVisualStatus;
    }

    async function downloadGraphicAsset(asset) {
        const resolvedAsset = asset?.data_url ? asset : await loadGraphicAssetDetail(asset);
        if (!resolvedAsset?.data_url) {
            graphicAssetStatusSetter(asset)('Kuvatiedostoa ei löytynyt ladattavaksi.', true);
            return;
        }
        const link = document.createElement('a');
        link.href = resolvedAsset.data_url;
        link.download = graphicAssetFileName(resolvedAsset);
        document.body.appendChild(link);
        link.click();
        link.remove();
        if (resolvedAsset.asset_type === 'infographic') setInfographicStatus('Infografiikan lataus käynnistyi.');
        else setVisualStatus('Kuvaehdotuksen lataus käynnistyi.');
    }

    function updateGraphicAssetCardPreview(card, asset) {
        if (!card || !asset) return;
        const media = card.querySelector('.graphic-asset-media');
        const downloadButton = card.querySelector('.graphic-download-btn');
        if (asset.data_url && media) {
            media.replaceChildren();
            const image = document.createElement('img');
            image.src = asset.data_url;
            image.alt = asset.title || graphicAssetTypeLabel(asset);
            image.loading = 'lazy';
            media.appendChild(image);
            card.classList.remove('is-loading-preview', 'has-preview-error');
        }
        if (downloadButton) {
            downloadButton.disabled = !asset.data_url;
            downloadButton.textContent = asset.data_url ? 'Lataa' : 'Ei ladattavissa';
        }
    }

    async function loadGraphicAssetDetail(asset, card = null) {
        if (asset?.data_url) {
            updateGraphicAssetCardPreview(card, asset);
            return asset;
        }
        const projectId = activeGraphicProjectId();
        if (!projectId || !asset?.id || String(asset.project_id || '') !== projectId) return null;
        const requestKey = `${projectId}:${asset.id}`;
        let request = graphicAssetDetailRequests.get(requestKey);
        if (!request) {
            request = (async () => {
                const response = await apiFetch(`/api/projects/${projectId}/graphic-assets/${asset.id}`);
                const data = await response.json().catch(() => null);
                if (!response.ok) throw new Error(data?.detail || 'Grafiikka-aineiston esikatselua ei voitu ladata.');
                if (activeGraphicProjectId() !== projectId) return null;
                const current = currentGraphicAssets.find(item => String(item.id) === String(asset.id));
                if (!current) return null;
                Object.assign(current, data);
                return current;
            })().finally(() => graphicAssetDetailRequests.delete(requestKey));
            graphicAssetDetailRequests.set(requestKey, request);
        }
        try {
            const resolved = await request;
            if (!resolved) return null;
            updateGraphicAssetCardPreview(card, resolved);
            if (resolved.asset_type === 'infographic') {
                const infographics = currentGraphicAssets
                    .filter(item => item.asset_type === 'infographic')
                    .sort((left, right) => new Date(right.created_at || 0) - new Date(left.created_at || 0));
                if (String(infographics[0]?.id || '') === String(resolved.id)) renderLatestInfographic(infographics);
            }
            return resolved;
        } catch (error) {
            if (card?.isConnected) {
                card.classList.remove('is-loading-preview');
                card.classList.add('has-preview-error');
                const media = card.querySelector('.graphic-asset-media');
                if (media) media.innerHTML = '<span>Esikatselua ei voitu ladata</span>';
                const downloadButton = card.querySelector('.graphic-download-btn');
                if (downloadButton) {
                    downloadButton.disabled = false;
                    downloadButton.textContent = 'Yritä uudelleen';
                }
            }
            return null;
        }
    }

    function createGraphicAssetCard(asset) {
        const card = document.createElement('article');
        card.className = `graphic-asset-card glass-panel${asset.data_url ? '' : ' is-loading-preview'}`;
        card.dataset.graphicAssetId = String(asset.id || '');
        const kind = graphicAssetTypeLabel(asset);
        const date = graphicAssetDate(asset.created_at);
        const model = String(asset.model || '').trim();
        const material = String(asset.material_kind || '').trim();
        card.innerHTML = `
            <div class="graphic-asset-media"></div>
            <div class="graphic-asset-copy">
                <span>${escapeHtml(kind)}</span>
                <h4>${escapeHtml(asset.title || kind)}</h4>
                <p>${[material, model, date].filter(Boolean).map(escapeHtml).join(' · ')}</p>
            </div>
            ${asset.prompt ? `<details class="graphic-asset-prompt"><summary>Luonnissa käytetty ohje</summary><p>${escapeHtml(asset.prompt)}</p></details>` : ''}
            <div class="graphic-asset-actions">
                <button class="btn btn-secondary graphic-download-btn" type="button"${asset.data_url ? '' : ' disabled'}>${asset.data_url ? 'Lataa' : 'Ladataan…'}</button>
                ${canEditProject(window.manuscriptData || {}) ? '<button class="btn btn-secondary btn-danger-soft graphic-delete-btn" type="button">Poista</button>' : ''}
            </div>
        `;
        const media = card.querySelector('.graphic-asset-media');
        if (asset.data_url) {
            const image = document.createElement('img');
            image.src = asset.data_url;
            image.alt = asset.title || kind;
            image.loading = 'lazy';
            media.appendChild(image);
        } else {
            media.innerHTML = '<span>Ladataan esikatselua…</span>';
        }
        card.querySelector('.graphic-download-btn')?.addEventListener('click', () => downloadGraphicAsset(asset));
        card.querySelector('.graphic-delete-btn')?.addEventListener('click', () => deleteGraphicAsset(asset));
        return card;
    }

    function renderGraphicGallery(items, container, emptyState) {
        if (!container || !emptyState) return;
        container.replaceChildren();
        emptyState.hidden = items.length > 0;
        items.forEach(item => container.appendChild(createGraphicAssetCard(item)));
    }

    function observeGraphicAssetPreviews() {
        graphicAssetPreviewObserver?.disconnect();
        const cards = Array.from(document.querySelectorAll('.graphic-asset-card.is-loading-preview[data-graphic-asset-id]'));
        if (!cards.length) return;
        if (!('IntersectionObserver' in window)) {
            cards.forEach(card => {
                const asset = currentGraphicAssets.find(item => String(item.id) === card.dataset.graphicAssetId);
                if (asset) loadGraphicAssetDetail(asset, card);
            });
            return;
        }
        graphicAssetPreviewObserver = new IntersectionObserver(entries => {
            entries.forEach(entry => {
                if (!entry.isIntersecting) return;
                graphicAssetPreviewObserver?.unobserve(entry.target);
                const asset = currentGraphicAssets.find(item => String(item.id) === entry.target.dataset.graphicAssetId);
                if (asset) loadGraphicAssetDetail(asset, entry.target);
            });
        }, { rootMargin: '240px 0px' });
        cards.forEach(card => graphicAssetPreviewObserver.observe(card));
    }

    function renderLatestInfographic(items) {
        if (!infographicLatestPreview) return;
        const latest = items[0];
        if (!latest?.data_url) {
            infographicLatestPreview.innerHTML = latest
                ? '<div class="graphics-preview-empty is-working"><span>◇</span><strong>Ladataan infografiikkaa…</strong><small>Esikatselu avautuu hetken kuluttua.</small></div>'
                : '<div class="graphics-preview-empty"><span>◇</span><strong>Infografiikka ilmestyy tähän</strong><small>Valitse tyyppi ja paina Luo infografiikka.</small></div>';
            if (infographicPreviewTitle) infographicPreviewTitle.textContent = latest?.title || 'Esikatselu';
            return;
        }
        infographicLatestPreview.replaceChildren();
        const image = document.createElement('img');
        image.src = latest.data_url;
        image.alt = latest.title || 'Uusin infografiikka';
        infographicLatestPreview.appendChild(image);
        if (infographicPreviewTitle) infographicPreviewTitle.textContent = latest.title || 'Uusin infografiikka';
    }

    function renderGraphicAssets(items = []) {
        currentGraphicAssets = Array.isArray(items) ? items : [];
        const ordered = [...currentGraphicAssets].sort((left, right) => {
            return new Date(right.created_at || 0).getTime() - new Date(left.created_at || 0).getTime();
        });
        const visualItems = ordered.filter(item => item.asset_type === 'book_visual_image');
        const infographicItems = ordered.filter(item => item.asset_type === 'infographic');
        renderGraphicGallery(visualItems, visualGallery, visualEmptyState);
        renderGraphicGallery(infographicItems, infographicGallery, infographicEmptyState);
        renderLatestInfographic(infographicItems);
        updateGraphicLoadMoreButtons();
        observeGraphicAssetPreviews();
    }

    function addGraphicAsset(asset, expectedProjectId = activeGraphicProjectId()) {
        const projectId = String(expectedProjectId || '');
        if (!asset?.id || !projectId || activeGraphicProjectId() !== projectId || String(asset.project_id || '') !== projectId) return false;
        const cacheWasLoaded = graphicAssetsLoadedProjectId === projectId;
        if (!cacheWasLoaded) graphicAssetsLoadSequence += 1;
        currentGraphicAssets = [asset, ...currentGraphicAssets.filter(item => String(item.id) !== String(asset.id))];
        renderGraphicAssets(currentGraphicAssets);
        graphicAssetsLoadedProjectId = cacheWasLoaded ? projectId : null;
        return true;
    }

    function updateGraphicLoadMoreButtons() {
        [
            ['book_visual_image', visualLoadMoreBtn, 'Lataa lisää kuvaehdotuksia'],
            ['infographic', infographicLoadMoreBtn, 'Lataa lisää infografiikoita'],
        ].forEach(([assetType, button, label]) => {
            if (!button) return;
            const state = graphicAssetPagination[assetType];
            button.hidden = !state.nextCursor;
            button.disabled = state.loading;
            button.textContent = state.loading ? 'Ladataan…' : label;
        });
    }

    function mergeGraphicAssetMetadata(items) {
        const existing = new Map(currentGraphicAssets.map(item => [String(item.id), item]));
        return (Array.isArray(items) ? items : []).map(item => {
            const previous = existing.get(String(item.id));
            return previous?.data_url ? { ...item, data_url: previous.data_url } : item;
        });
    }

    async function requestGraphicAssetPage(projectId, assetType, cursor = null) {
        const params = new URLSearchParams({ asset_type: assetType, limit: String(GRAPHIC_ASSET_PAGE_SIZE) });
        if (cursor) params.set('cursor', String(cursor));
        const response = await apiFetch(`/api/projects/${projectId}/graphic-assets?${params.toString()}`);
        const data = await response.json().catch(() => null);
        if (!response.ok) throw new Error(data?.detail || 'Grafiikka-aineistojen lataus epäonnistui.');
        return {
            items: Array.isArray(data?.items) ? data.items : [],
            nextCursor: data?.next_cursor || null,
        };
    }

    async function loadGraphicAssets(showFeedback = false, options = {}) {
        const projectId = window.manuscriptData?.id;
        const force = Boolean(options?.force);
        if (!projectId) {
            invalidateGraphicAssetCache(true);
            if (showFeedback) {
                setVisualStatus('Valitse projekti nähdäksesi kuvaehdotukset.');
                setInfographicStatus('Valitse projekti nähdäksesi infografiikat.');
            }
            return [];
        }
        const requestedProjectId = String(projectId);
        if (!force && graphicAssetsLoadedProjectId === requestedProjectId) return currentGraphicAssets;
        const loadSequence = ++graphicAssetsLoadSequence;
        try {
            const [visualPage, infographicPage] = await Promise.all([
                requestGraphicAssetPage(projectId, 'book_visual_image'),
                requestGraphicAssetPage(projectId, 'infographic'),
            ]);
            if (loadSequence !== graphicAssetsLoadSequence || String(window.manuscriptData?.id || '') !== requestedProjectId) return [];
            graphicAssetPreviewObserver?.disconnect();
            graphicAssetDetailRequests.clear();
            graphicAssetPagination.book_visual_image.nextCursor = visualPage.nextCursor;
            graphicAssetPagination.infographic.nextCursor = infographicPage.nextCursor;
            const firstPageItems = mergeGraphicAssetMetadata([...visualPage.items, ...infographicPage.items]);
            graphicAssetsLoadedProjectId = requestedProjectId;
            renderGraphicAssets(firstPageItems);
            return currentGraphicAssets;
        } catch (error) {
            if (loadSequence !== graphicAssetsLoadSequence) return [];
            const message = error.message || 'Grafiikka-aineistojen lataus epäonnistui.';
            setVisualStatus(message, true);
            setInfographicStatus(message, true);
            return [];
        }
    }

    async function loadMoreGraphicAssets(assetType) {
        const projectId = activeGraphicProjectId();
        const state = graphicAssetPagination[assetType];
        if (!projectId || !state?.nextCursor || state.loading) return;
        const cursor = state.nextCursor;
        state.loading = true;
        updateGraphicLoadMoreButtons();
        try {
            const page = await requestGraphicAssetPage(projectId, assetType, cursor);
            if (activeGraphicProjectId() !== projectId) return;
            state.nextCursor = page.nextCursor;
            const mergedPage = mergeGraphicAssetMetadata(page.items);
            const ids = new Set(mergedPage.map(item => String(item.id)));
            currentGraphicAssets = [...currentGraphicAssets.filter(item => !ids.has(String(item.id))), ...mergedPage];
            renderGraphicAssets(currentGraphicAssets);
        } catch (error) {
            graphicAssetStatusSetter({ asset_type: assetType })(error.message || 'Grafiikka-aineistojen lataus epäonnistui.', true);
        } finally {
            state.loading = false;
            updateGraphicLoadMoreButtons();
        }
    }

    async function deleteGraphicAsset(asset) {
        const projectId = window.manuscriptData?.id;
        if (!projectId || !asset?.id || !canEditProject(window.manuscriptData || {})) return;
        if (String(asset.project_id || '') !== String(projectId)) return;
        const kind = asset.asset_type === 'infographic' ? 'infografiikka' : 'kuvaehdotus';
        if (!confirm(`Poistetaanko ${kind}?`)) return;
        const setStatus = asset.asset_type === 'infographic' ? setInfographicStatus : setVisualStatus;
        setStatus(`Poistetaan ${kind}a…`);
        try {
            const response = await apiFetch(`/api/projects/${projectId}/assets/${asset.id}`, { method: 'DELETE' });
            if (!response.ok) throw new Error(await apiErrorMessage(response, 'Grafiikka-aineiston poisto epäonnistui.'));
            if (activeGraphicProjectId() !== String(projectId)) return;
            currentGraphicAssets = currentGraphicAssets.filter(item => String(item.id) !== String(asset.id));
            renderGraphicAssets(currentGraphicAssets);
            setStatus(`${kind === 'infografiikka' ? 'Infografiikka' : 'Kuvaehdotus'} poistettu.`);
        } catch (error) {
            setStatus(error.message || 'Grafiikka-aineiston poisto epäonnistui.', true);
        }
    }

    function defaultInfographicTitle() {
        const label = infographicTypeLabels[infographicTypeSelect?.value] || 'Infografiikka';
        const title = String(window.manuscriptData?.title || '').trim();
        return title ? `${title} · ${label}` : label;
    }

    function populateInfographicDefaults(force = false) {
        if (!infographicTitleInput) return;
        const projectId = String(window.manuscriptData?.id || 'unsaved');
        const projectChanged = infographicTitleInput.dataset.projectId !== projectId;
        if (force || projectChanged || !infographicTitleInput.value.trim() || infographicTitleInput.dataset.autoTitle === 'true') {
            infographicTitleInput.value = defaultInfographicTitle();
            infographicTitleInput.dataset.autoTitle = 'true';
        }
        infographicTitleInput.dataset.projectId = projectId;
    }

    async function generateInfographic() {
        if (infographicGenerateBtn?.dataset.running === 'true') return;
        const projectId = await ensureGraphicProject();
        if (!projectId) {
            setInfographicStatus('Valitse tai tallenna käsikirjoitus ennen infografiikan luontia.', true);
            return;
        }
        if (String(projectId) !== activeGraphicProjectId()) return;
        populateInfographicDefaults();
        const type = infographicTypeSelect?.value || 'timeline';
        const title = infographicTitleInput?.value.trim() || defaultInfographicTitle();
        if (infographicGenerateBtn) {
            infographicGenerateBtn.dataset.running = 'true';
            infographicGenerateBtn.textContent = 'Luodaan infografiikkaa…';
        }
        syncGraphicsControls();
        setInfographicStatus(`Luodaan: ${infographicTypeLabels[type] || 'Infografiikka'}. Tässä voi mennä hetki.`);
        if (infographicLatestPreview) {
            infographicLatestPreview.innerHTML = '<div class="graphics-preview-empty is-working"><span>◇</span><strong>Jäsennetään projektin tietoja…</strong><small>Analyysi ja kontekstimuisti ohjaavat sisältöä valintojesi mukaan.</small></div>';
        }
        try {
            const response = await apiFetch(`/api/projects/${projectId}/infographics`, {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    infographic_type: type,
                    title,
                    focus: (infographicFocusInput?.value || '').trim(),
                    theme: infographicThemeSelect?.value || 'paper',
                    use_analysis: Boolean(infographicUseAnalysis?.checked),
                    use_project_memory: Boolean(infographicUseMemory?.checked),
                }),
            });
            const data = await response.json().catch(() => null);
            if (!response.ok) throw new Error(data?.detail || 'Infografiikan luonti epäonnistui.');
            if (!addGraphicAsset(data, String(projectId))) return;
            if (graphicAssetsLoadedProjectId !== String(projectId)) {
                await loadGraphicAssets(false, { force: true });
                if (activeGraphicProjectId() !== String(projectId)) return;
            }
            setInfographicStatus('Infografiikka luotiin ja tallennettiin projektiin.');
            loadUsage();
        } catch (error) {
            if (activeGraphicProjectId() === String(projectId)) {
                setInfographicStatus(networkFailureMessage(error), true);
                renderLatestInfographic(currentGraphicAssets.filter(item => item.asset_type === 'infographic'));
            }
        } finally {
            if (infographicGenerateBtn) {
                delete infographicGenerateBtn.dataset.running;
                infographicGenerateBtn.textContent = 'Luo infografiikka';
            }
            syncGraphicsControls();
        }
    }

    graphicsTabButtons.forEach(button => {
        button.addEventListener('click', () => setGraphicsTab(button.dataset.graphicsPanel));
        button.addEventListener('keydown', handleGraphicsTabKeydown);
    });
    graphicsHtmlGenerateBtn?.addEventListener('click', generateGraphicsHtmlDraft);
    graphicsHtmlDownloadBtn?.addEventListener('click', downloadGraphicsHtmlDraft);
    visualAddRowBtn?.addEventListener('click', () => {
        const entry = nextUnusedVisualChapterEntry();
        if (!entry) {
            setVisualStatus('Kaikille varsinaisille luvuille on jo kuvaehdotuksen rivi.', true);
            return;
        }
        addVisualBatchRow({
            chapter_custom_id: String(entry.chapter.id || ''),
            section_label: structureDisplayTitle(entry.chapter, entry.index) || `Luku ${entry.index + 1}`,
            visual_kind: 'scene',
            aspect_ratio: '3:4',
        }, { focus: true });
        setVisualStatus(`${visualBatchRows.children.length} luvun promptit ovat valmiina ajoon.`);
    });
    visualGenerateAllBtn?.addEventListener('click', generateVisualBatch);
    visualGeneratePromptsBtn?.addEventListener('click', generateVisualPromptPlan);
    visualLoadMoreBtn?.addEventListener('click', () => loadMoreGraphicAssets('book_visual_image'));
    visualModelSelect?.addEventListener('change', () => {
        syncVisualModelCapabilities();
        scheduleVisualEstimate({ immediate: true });
    });
    visualImageSize?.addEventListener('change', () => scheduleVisualEstimate({ immediate: true }));
    visualVariantsPerPrompt?.addEventListener('input', () => scheduleVisualEstimate());
    visualVariantsPerPrompt?.addEventListener('change', () => scheduleVisualEstimate({ immediate: true }));
    visualExecutionModeInputs.forEach(input => input.addEventListener('change', () => {
        syncVisualModelCapabilities();
        scheduleVisualEstimate({ immediate: true });
    }));
    visualStopBtn?.addEventListener('click', () => {
        if (visualImageBatchJobId) {
            void cancelVisualProviderBatch();
            return;
        }
        if (visualBatchController && !visualBatchController.stopRequested) {
            requestVisualBatchStop('Pysäytetään kuvaerää nykyisen pyynnön jälkeen…');
        }
    });
    infographicTypeSelect?.addEventListener('change', () => {
        if (infographicTitleInput?.dataset.autoTitle === 'true' || !infographicTitleInput?.value.trim()) {
            populateInfographicDefaults(true);
        }
    });
    infographicTitleInput?.addEventListener('input', () => {
        infographicTitleInput.dataset.autoTitle = infographicTitleInput.value.trim() ? 'false' : 'true';
    });
    infographicGenerateBtn?.addEventListener('click', generateInfographic);
    infographicLoadMoreBtn?.addEventListener('click', () => loadMoreGraphicAssets('infographic'));

    function coverAssetTypeLabel(item) {
        return item?.asset_type === 'full_cover_image'
            ? item?.material_kind === 'print_cover_layout' ? 'Painokansi · 300 DPI' : 'Koko kansi'
            : item?.asset_type === 'back_cover_image'
                ? 'Takakansi'
                : 'Etukansi';
    }

    function updateCoverReferenceStatus() {
        if (!coverReferenceStatus) return;
        if (!selectedCoverReference) {
            coverReferenceStatus.textContent = 'Ei valittua pohjakuvaa. Voit valita pohjakuvan tallennetuista kansista.';
            return;
        }
        coverReferenceStatus.textContent = `Pohjakuvana: ${coverAssetTypeLabel(selectedCoverReference)} - ${selectedCoverReference.title || 'nimetön kuva'}.`;
    }

    function selectCoverReference(item) {
        if (!item) return;
        selectedCoverReference = item;
        updateCoverReferenceStatus();
        setIllustrationStatus('Pohjakuva valittu seuraavaa generointia varten.');
    }

    function clearCoverReference(showStatus = true) {
        selectedCoverReference = null;
        updateCoverReferenceStatus();
        if (showStatus) setIllustrationStatus('Pohjakuva tyhjennetty.');
    }

    function renderCoverImages(items = []) {
        updateIllustrationProjectText();
        if (!coverGallery || !coverEmptyState || !coverLatestPreview) return;
        items = (Array.isArray(items) ? items : []).filter(item => (
            !showcaseDemoMode
            || (item.asset_type !== 'back_cover_image'
                && item.asset_type !== 'full_cover_image'
                && item.material_kind !== 'print_cover_layout')
        ));
        currentCoverImages = items;
        renderGraphicsHtmlWorkspace();
        renderCoverLayoutSourceOptions();
        populateCoverLayoutDefaults();
        if (selectedCoverReference && !currentCoverImages.some(item => String(item.id) === String(selectedCoverReference.id))) {
            selectedCoverReference = null;
        }
        updateCoverReferenceStatus();
        const coverItemsById = new Map(items.map(item => [String(item.id), item]));
        coverGallery.innerHTML = '';
        coverEmptyState.hidden = items.length > 0;

        if (!items.length) {
            coverLatestPreview.innerHTML = showcaseDemoMode
                ? 'Kansikuva ilmestyy tähän.'
                : 'Kansikuva tai takakansi ilmestyy tähän.';
            return;
        }

        coverLatestPreview.innerHTML = `
            <div class="cover-preview-stack">
                <img src="${items[0].data_url}" alt="Viimeisin kansi" style="width:100%; max-height:520px; object-fit:contain; border-radius:10px;">
                <button class="btn btn-secondary cover-reference-btn" type="button" data-cover-reference-id="${items[0].id}">Käytä pohjana</button>
                <button class="btn btn-secondary cover-download-btn" type="button" data-cover-download-id="${items[0].id}">Lataa kuva</button>
            </div>
        `;
        items.forEach(item => {
            const typeLabel = coverAssetTypeLabel(item);
            const imageShape = item.asset_type === 'full_cover_image'
                ? 'aspect-ratio:4 / 3; object-fit:contain;'
                : item.title.includes('1000 x 1000 px')
                    ? 'aspect-ratio:1 / 1; object-fit:cover;'
                    : item.title.includes('1000 x 1500 px')
                        ? 'aspect-ratio:2 / 3; object-fit:cover;'
                        : 'aspect-ratio:3 / 4; object-fit:cover;';
            const card = document.createElement('div');
            card.className = 'card glass-panel';
            card.style.display = 'flex';
            card.style.flexDirection = 'column';
            card.style.gap = '12px';
            card.innerHTML = `
                <img src="${item.data_url}" alt="${escapeHtml(item.title)}" style="width:100%; ${imageShape} border-radius:8px; border:1px solid var(--border-color); background:rgba(0,0,0,0.16);">
                <div>
                    <strong style="font-size:14px;">${escapeHtml(item.title)}</strong>
                    <p class="card-meta" style="margin:6px 0 0;">${typeLabel} · ${escapeHtml(item.model || 'Kuvamalli')}</p>
                </div>
                <details style="font-size:12px; color:var(--text-secondary);">
                    <summary>Prompti</summary>
                    <p style="white-space:pre-wrap; margin-top:8px;">${escapeHtml(item.prompt || '')}</p>
                </details>
                <div class="cover-card-actions">
                    <button class="btn btn-secondary cover-reference-btn" type="button" data-cover-reference-id="${item.id}">Käytä pohjana</button>
                    <button class="btn btn-secondary cover-download-btn" type="button" data-cover-download-id="${item.id}">Lataa kuva</button>
                    <button class="btn btn-secondary btn-danger-soft delete-cover-btn" type="button" data-asset-id="${item.id}">Poista kuva</button>
                </div>
            `;
            coverGallery.appendChild(card);
        });
        document.querySelectorAll('.cover-reference-btn').forEach(button => {
            button.addEventListener('click', () => selectCoverReference(coverItemsById.get(String(button.dataset.coverReferenceId))));
        });
        document.querySelectorAll('.cover-download-btn').forEach(button => {
            button.addEventListener('click', () => downloadCoverImage(coverItemsById.get(String(button.dataset.coverDownloadId))));
        });
        coverGallery.querySelectorAll('.delete-cover-btn').forEach(button => {
            button.addEventListener('click', () => deleteCoverImage(button.dataset.assetId));
        });
    }

    function safeFileStem(value, fallback = 'kansi') {
        return String(value || fallback)
            .trim()
            .toLowerCase()
            .replace(/[^a-z0-9åäö]+/gi, '-')
            .replace(/^-|-$/g, '') || fallback;
    }

    function coverImageFileName(asset) {
        const title = safeFileStem(window.manuscriptData?.title || asset?.title || 'kansi', 'kansi');
        const side = asset?.asset_type === 'full_cover_image'
            ? asset?.material_kind === 'print_cover_layout' ? 'painokansi-300dpi' : 'koko-kansi'
            : asset?.asset_type === 'back_cover_image'
                ? 'takakansi'
                : 'etukansi';
        const extension = String(asset?.mime_type || '').includes('jpeg') || String(asset?.mime_type || '').includes('jpg')
            ? 'jpg'
            : String(asset?.mime_type || '').includes('webp')
                ? 'webp'
                : 'png';
        return `${title}-${side}.${extension}`;
    }

    function downloadCoverImage(asset) {
        if (!asset?.data_url) {
            setIllustrationStatus('Kuvatiedostoa ei löytynyt ladattavaksi.', true);
            return;
        }
        const link = document.createElement('a');
        link.href = asset.data_url;
        link.download = coverImageFileName(asset);
        document.body.appendChild(link);
        link.click();
        link.remove();
        setIllustrationStatus('Kansikuva ladattu.');
    }

    async function uploadCoverImageFromInput() {
        if (window.manuscriptData && !window.manuscriptData.id) {
            const savedProject = await window.saveManuscriptToDB(window.manuscriptData);
            if (savedProject?.id) window.manuscriptData = savedProject;
        }
        if (!window.manuscriptData?.id) {
            setIllustrationStatus('Valitse tai tallenna käsikirjoitus ennen kuvan tuontia.', true);
            return;
        }
        const file = coverUploadInput?.files?.[0];
        if (!file) return;
        if (!['image/png', 'image/jpeg', 'image/webp'].includes(file.type)) {
            setIllustrationStatus('Kuvan pitää olla PNG-, JPG- tai WEBP-muodossa.', true);
            coverUploadInput.value = '';
            return;
        }
        const form = new FormData();
        form.append('file', file);
        form.append('cover_side', coverSideValue());
        form.append('title', file.name.replace(/\.[^.]+$/, '') || 'Ladattu kansikuva');
        if (coverUploadBtn) coverUploadBtn.disabled = true;
        setIllustrationStatus('Tallennetaan omaa kuvaa palveluun...');
        try {
            const res = await apiFetch(`/api/projects/${window.manuscriptData.id}/cover-images/upload`, {
                method: 'POST',
                body: form
            });
            const data = await res.json().catch(() => null);
            if (!res.ok) throw new Error(data?.detail || 'Kuvan tuonti epäonnistui.');
            await loadCoverImages();
            const uploaded = currentCoverImages.find(item => String(item.id) === String(data.id)) || data;
            selectCoverReference(uploaded);
            setIllustrationStatus('Kuva tallennettu palveluun ja valittu pohjakuvaksi.');
        } catch (err) {
            setIllustrationStatus(err.message || 'Kuvan tuonti epäonnistui.', true);
        } finally {
            if (coverUploadBtn) coverUploadBtn.disabled = false;
            if (coverUploadInput) coverUploadInput.value = '';
        }
    }

    async function loadCoverImages() {
        updateIllustrationProjectText();
        if (!window.manuscriptData?.id) {
            renderCoverImages([]);
            renderCoverLayout(null);
            setIllustrationStatus('Valitse tai tallenna käsikirjoitus ennen kansikuvan generointia.');
            return;
        }
        const requestedProjectId = window.manuscriptData.id;
        try {
            const res = await apiFetch(`/api/projects/${requestedProjectId}/cover-images`);
            const data = await res.json();
            if (!res.ok) throw new Error(data.detail || 'Kansikuvien lataus epäonnistui.');
            if (String(window.manuscriptData?.id || '') !== String(requestedProjectId)) return;
            renderCoverImages(data || []);
            await loadLatestCoverLayout();
            if (data?.length) setIllustrationStatus('Kansikuvat ladattu.');
        } catch (err) {
            setIllustrationStatus(err.message, true);
        }
    }

    async function deleteCoverImage(assetId) {
        if (!window.manuscriptData?.id || !assetId) return;
        if (!confirm('Poistetaanko kuva?')) return;
        setIllustrationStatus('Poistetaan kuvaa...');
        try {
            const res = await apiFetch(`/api/projects/${window.manuscriptData.id}/assets/${assetId}`, { method: 'DELETE' });
            if (!res.ok) throw new Error(await apiErrorMessage(res, 'Kuvan poisto epäonnistui.'));
            await loadCoverImages();
            setIllustrationStatus('Kuva poistettu.');
        } catch (err) {
            setIllustrationStatus(err.message, true);
        }
    }

    async function generateCoverImage() {
        if (!window.manuscriptData) {
            setIllustrationStatus('Valitse ensin käsikirjoitus.', true);
            return;
        }
        if (!window.manuscriptData.id) {
            const savedProject = await window.saveManuscriptToDB(window.manuscriptData);
            if (savedProject?.id) window.manuscriptData = savedProject;
        }
        if (!window.manuscriptData?.id) {
            setIllustrationStatus('Käsikirjoitusta ei saatu tallennettua ennen kansikuvaa.', true);
            return;
        }

        const coverSide = coverSideValue();
        const format = activeCoverFormat();
        const titleText = coverTitleInput?.value.trim() || coverTitleFromProject();
        const authorText = coverAuthorInput?.value.trim() || coverAuthorFromProject();
        const prompt = (coverPrompt?.value || '').trim();
        const fallbackPrompt = coverSide === 'back'
            ? analysisBackCoverText()
            : coverSide === 'full'
                ? [analysisCoverPrompt(), analysisBackCoverText()].filter(Boolean).join('\n\nTakakansiteksti:\n')
                : analysisCoverPrompt();
        if (!prompt && fallbackPrompt && coverPrompt) {
            coverPrompt.value = fallbackPrompt;
        }

        if (coverGenerateBtn) coverGenerateBtn.disabled = true;
        if (coverLatestPreview) {
            coverLatestPreview.innerHTML = `<div style="text-align:center; color:var(--text-secondary);">Generoidaan: ${coverSideLabel(coverSide)}...</div>`;
        }
        setIllustrationStatus(`${coverSideLabel(coverSide)} generoidaan formaattiin ${format.label}. Tässä voi mennä hetki.`);

        try {
            const res = await apiFetch(`/api/projects/${window.manuscriptData.id}/cover-images`, {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    prompt: (coverPrompt?.value || '').trim(),
                    cover_side: coverSide,
                    model: coverModelSelect?.value || null,
                    cover_format: format.key,
                    aspect_ratio: format.aspectRatio,
                    title_text: titleText,
                    author_text: authorText,
                    without_text: Boolean(coverWithoutTextInput?.checked),
                    spine_width_mm: coverSpineWidthInput?.value ? Number(coverSpineWidthInput.value) : null,
                    page_count: coverPageCountInput?.value ? Number(coverPageCountInput.value) : null,
                    reference_image_id: selectedCoverReference?.id || null,
                })
            });
            const data = await res.json().catch(() => null);
            if (!res.ok) throw new Error(data?.detail || 'Kansikuvan generointi epäonnistui.');
            setIllustrationStatus(`${coverSideLabel(coverSide)} tallennettu käsikirjoitukselle.`);
            await loadCoverImages();
            loadUsage();
        } catch (err) {
            if (coverLatestPreview) {
                coverLatestPreview.innerHTML = `${coverSideLabel(coverSide)} ei saatu generoitua.`;
            }
            const message = String(err?.message || err || '');
            setIllustrationStatus(message.includes('Failed to fetch') ? networkFailureMessage(err, 'cover') : message, true);
        } finally {
            if (coverGenerateBtn) coverGenerateBtn.disabled = false;
        }
    }

    if (coverLoadPromptBtn) {
        coverLoadPromptBtn.addEventListener('click', () => {
            const side = coverSideValue();
            const isBackCover = side === 'back';
            const isFullCover = side === 'full';
            const prompt = isFullCover
                ? [analysisCoverPrompt(), analysisBackCoverText()].filter(Boolean).join('\n\nTakakansiteksti:\n')
                : isBackCover ? analysisBackCoverText() : analysisCoverPrompt();
            if (!prompt) {
                setIllustrationStatus(isFullCover
                    ? 'Analyysista ei löytynyt etukannen promptia tai takakansitekstiä. Voit kirjoittaa täyden kannen ohjeen käsin.'
                    : isBackCover
                    ? 'Analyysista ei löytynyt takakansitekstiä. Voit kirjoittaa sen käsin.'
                    : 'Analyysista ei löytynyt kansikuvapromptia. Voit kirjoittaa promptin käsin.', true);
                return;
            }
            if (coverPrompt) coverPrompt.value = prompt;
            setIllustrationStatus(isFullCover ? 'Etukannen prompti ja takakansiteksti ladattu kenttään.' : isBackCover ? 'Takakansiteksti ladattu kenttään.' : 'Analyysin kansikuvaprompti ladattu kenttään.');
        });
    }

    if (coverSideSelect) {
        coverSideSelect.addEventListener('change', renderCoverFormatOptions);
    }
    if (coverFormatSelect) {
        coverFormatSelect.addEventListener('change', updateCoverFormatNote);
        renderCoverFormatOptions();
    }

    if (coverUploadBtn && coverUploadInput) {
        coverUploadBtn.addEventListener('click', () => coverUploadInput.click());
        coverUploadInput.addEventListener('change', uploadCoverImageFromInput);
    }

    if (coverClearReferenceBtn) {
        coverClearReferenceBtn.addEventListener('click', () => clearCoverReference(true));
    }

    if (coverGenerateBtn) {
        coverGenerateBtn.addEventListener('click', generateCoverImage);
    }

    [coverLayoutTrimSelect, coverLayoutPageCount, coverLayoutPaperSelect, coverLayoutBleedSelect].forEach(element => {
        element?.addEventListener('input', () => {
            if (element === coverLayoutPageCount) coverLayoutPageCount.dataset.source = 'manual';
            updateCoverLayoutMetrics();
        });
        element?.addEventListener('change', () => {
            if (element === coverLayoutTrimSelect && coverLayoutPageCount?.dataset.source !== 'manual') {
                coverLayoutPageCount.value = String(estimatedCoverLayoutPageCount());
            }
            updateCoverLayoutMetrics();
        });
    });
    coverLayoutEstimateBtn?.addEventListener('click', () => {
        if (coverLayoutPageCount) coverLayoutPageCount.value = String(estimatedCoverLayoutPageCount());
        if (coverLayoutPageCount) coverLayoutPageCount.dataset.source = 'inferred';
        updateCoverLayoutMetrics();
        setCoverLayoutStatus('Sivumäärä pääteltiin sanamäärästä ja pyöristettiin neljällä jaolliseksi.');
    });
    coverLayoutGenerateBtn?.addEventListener('click', generateCoverLayout);
    coverLayoutDownloadPng?.addEventListener('click', () => downloadCoverLayoutAsset(latestCoverLayout?.artwork, 'painokansi-300dpi', 'png'));
    coverLayoutDownloadPdf?.addEventListener('click', () => downloadCoverLayoutAsset(latestCoverLayout?.pdf, 'painokansi', 'pdf'));

    function layoutFileName(asset) {
        const safeTitle = (window.manuscriptData?.title || 'kasikirjoitus').toLowerCase().replace(/[^a-z0-9åäö]+/gi, '-').replace(/^-|-$/g, '') || 'kasikirjoitus';
        const extensions = {
            layout_pdf: 'pdf', layout_epub: 'epub', layout_latex: 'tex',
            layout_md: 'md', layout_docx: 'docx', layout_rtf: 'rtf',
            layout_icml: 'icml', layout_idml: 'idml'
        };
        return `${safeTitle}.${extensions[asset.asset_type] || 'bin'}`;
    }

    function layoutAssetLabel(asset) {
        return ({
            layout_pdf: 'PDF-taittovedos',
            layout_epub: 'EPUB-e-kirja',
            layout_latex: 'LaTeX-lähde',
            layout_md: 'Markdown-lähde',
            layout_docx: 'DOCX-taittopohja',
            layout_rtf: 'RTF-tekstilähde',
            layout_icml: 'InCopy-tekstiaineisto',
            layout_idml: 'InDesign-taittopohja'
        })[asset.asset_type] || 'Taittoaineisto';
    }

    function layoutAssetFormat(asset) {
        return ({
            layout_pdf: 'PDF', layout_epub: 'EPUB', layout_latex: 'LaTeX',
            layout_md: 'MD', layout_docx: 'DOCX', layout_rtf: 'RTF',
            layout_icml: 'ICML', layout_idml: 'IDML'
        })[asset.asset_type] || 'tiedosto';
    }

    function downloadAsset(asset) {
        if (!asset?.data_url) return;
        const link = document.createElement('a');
        link.href = asset.data_url;
        link.download = layoutFileName(asset);
        link.click();
    }

	    function renderLayoutAssets(items = []) {
	        currentLayoutAssets = Array.isArray(items) ? items : [];
	        const container = document.getElementById('layout-assets');
	        const status = document.getElementById('layout-status');
	        if (!container) return;
	        container.innerHTML = '';
	        if (!items.length) {
	            if (status) status.textContent = 'Ei ajettua taittoa vielä.';
	            renderWriterStage();
	            return;
	        }
	        if (status) status.textContent = 'Taittotiedostot tallennettu käsikirjoitukselle.';
	        renderWriterStage();
	        items.forEach(asset => {
            const card = document.createElement('div');
            card.className = 'card glass-panel';
            card.innerHTML = `
                <strong>${escapeHtml(layoutAssetLabel(asset))}</strong>
                <p class="card-meta">${escapeHtml(asset.title || '')}</p>
                <p class="card-meta">${escapeHtml(asset.model || 'python:layout-generator')}</p>
                <button class="btn btn-secondary layout-download-btn" type="button">Lataa ${layoutAssetFormat(asset)}</button>
            `;
            card.querySelector('.layout-download-btn')?.addEventListener('click', () => downloadAsset(asset));
            container.appendChild(card);
        });
    }

    async function loadLayoutAssets() {
        if (!window.manuscriptData?.id) {
            renderLayoutAssets([]);
            return;
        }
        const status = document.getElementById('layout-status');
        try {
            const res = await apiFetch(`/api/projects/${window.manuscriptData.id}/layout-assets`);
            const data = await res.json();
            if (!res.ok) throw new Error(data.detail || 'Taittotiedostojen lataus epäonnistui.');
            renderLayoutAssets(data || []);
        } catch (err) {
            if (status) status.textContent = err.message;
        }
    }

    async function runLayout() {
        const button = document.getElementById('layout-run-btn');
        const status = document.getElementById('layout-status');
        if (!window.manuscriptData?.id) {
            alert('Valitse tai tallenna käsikirjoitus ensin.');
            return;
        }
        if (button) button.disabled = true;
        if (status) status.textContent = 'Tallennetaan nykyinen toimitettu versio ja ajetaan taitto...';
        try {
            const savedProject = await window.saveManuscriptToDB(window.manuscriptData);
            if (savedProject?.id) window.manuscriptData = savedProject;
            const res = await apiFetch(`/api/projects/${window.manuscriptData.id}/layout/run`, {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    layout_style: document.getElementById('layout-size-select')?.value || 'A5',
                    include_markdown_markers: true,
                    hyphenation_level: document.getElementById('layout-hyphenation-select')?.value || 'balanced'
                })
            });
            const data = await res.json().catch(() => null);
            if (!res.ok) throw new Error(data?.detail || 'Taiton ajo epäonnistui.');
            renderLayoutAssets(Array.isArray(data.assets) ? data.assets : [data.pdf, data.epub, data.latex].filter(Boolean));
        } catch (err) {
            if (status) status.textContent = err.message;
            alert('Taiton ajo epäonnistui: ' + err.message);
        } finally {
            if (button) button.disabled = false;
        }
    }

    function proofreadChapterText(chapter) {
        return (chapter?.paragraphs || []).filter(Boolean).join('\n\n');
    }

    function proofreadWarningsArray(value) {
        if (Array.isArray(value)) return value.filter(Boolean).map(String);
        return value ? [String(value)] : [];
    }

    function setProofreadWarnings(id, warnings) {
        const el = document.getElementById(id);
        if (!el) return;
        const values = proofreadWarningsArray(warnings);
        el.textContent = values.join('\n');
        el.classList.toggle('hidden', !values.length);
    }

    let proofreadToastTimer = null;
    function proofreadToast(message) {
        const el = document.getElementById('proofread-toast');
        if (!el) {
            alert(demoUiText(message));
            return;
        }
        el.textContent = demoUiText(message);
        el.classList.remove('hidden');
        clearTimeout(proofreadToastTimer);
        proofreadToastTimer = setTimeout(() => el.classList.add('hidden'), 3400);
    }

    function setProofreadWorking(show, label = 'Hetki...') {
        const el = document.getElementById('proofread-working');
        const labelEl = document.getElementById('proofread-working-label');
        if (labelEl) labelEl.textContent = demoUiText(label);
        if (el) el.classList.toggle('hidden', !show);
    }

    function currentProofreadChapters() {
        return window.manuscriptData?.chapters || [];
    }

    function currentProofreadChapter() {
        return currentProofreadChapters()[proofreadSelection.cIndex || 0] || null;
    }

    function proofreadCleanupKinds() {
        return Array.from(document.querySelectorAll('[data-cleanup]'))
            .filter(element => element.checked)
            .map(element => element.dataset.cleanup);
    }

    function downloadProofreadText(text, filename) {
        const blob = new Blob([text || ''], { type: 'text/plain;charset=utf-8' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        link.remove();
        URL.revokeObjectURL(link.href);
    }

    async function ensureProofreadProjectSaved(label = 'Tallennetaan käsikirjoitusta...') {
        if (!window.manuscriptData) throw new Error('Valitse käsikirjoitus ensin.');
        setProofreadWorking(true, label);
        const savedProject = await window.saveManuscriptToDB(window.manuscriptData);
        if (savedProject?.id) {
            window.manuscriptData = savedProject;
            updateAvailableProject(savedProject);
        }
        if (!window.manuscriptData?.id) throw new Error('Tallenna käsikirjoitus ennen oikolukua.');
        return window.manuscriptData;
    }

    async function markProjectWorkflowStage(stage, status) {
        if (!window.manuscriptData?.id || !stage) return;
        const analysis = window.manuscriptData.analysis || {};
        const workflowState = {
            ...(analysis.workflow_state || {}),
            [stage]: {
                ...(analysis.workflow_state?.[stage] || {}),
                status,
                updated_at: new Date().toISOString(),
            },
        };
        window.manuscriptData.analysis = { ...analysis, workflow_state: workflowState };
        localStorage.setItem('skriptlab_manuscript', JSON.stringify(window.manuscriptData));
        try {
            const response = await apiFetch(`/api/projects/${window.manuscriptData.id}/metadata`, {
                method: 'PATCH',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ analysis: { workflow_state: workflowState } }),
            });
            const saved = await response.json().catch(() => null);
            if (response.ok && saved?.id) {
                window.manuscriptData = saved;
                updateAvailableProject(saved);
            }
        } catch (error) {
            console.warn('Työvaiheen tilan tallennus jäi paikalliseksi:', error);
        }
    }

    async function loadProofreadDefaultRules(force = false) {
        if (proofreadRulesLoaded && !force) return proofreadDefaultRules;
        try {
            const res = await apiFetch('/api/proofread/rules');
            if (!res.ok) throw new Error(await apiErrorMessage(res, 'Sääntöpromptin haku epäonnistui.'));
            const data = await res.json();
            proofreadDefaultRules = data.rules || DEFAULT_EXTRA_PROOFREAD_RULES;
        } catch (err) {
            proofreadDefaultRules = DEFAULT_EXTRA_PROOFREAD_RULES;
        }
        proofreadRulesLoaded = true;
        const textarea = document.getElementById('extra-rules');
        if (textarea && !textarea.value.trim()) textarea.value = proofreadDefaultRules;
        return proofreadDefaultRules;
    }

    function resetProofreadExtraRules() {
        const textarea = document.getElementById('extra-rules');
        if (textarea) textarea.value = proofreadDefaultRules || DEFAULT_EXTRA_PROOFREAD_RULES;
        proofreadToast('Oletussäännöt palautettu.');
    }

    function updateProofreadExtraScopeUi() {
        renderProofreadScopeChips();
    }

    function showProofreadPanel(panelId = 'oikoluku') {
        const aliases = {
            'proofread-panel-chapter': 'oikoluku',
            'proofread-panel-pdf': 'tarkistus',
            'proofread-panel-finishing': 'viimeistely',
        };
        const next = aliases[panelId] || panelId || 'oikoluku';
        proofreadPanel = next;
        ['oikoluku', 'tarkistus', 'viimeistely'].forEach(name => {
            document.getElementById(`panel-${name}`)?.classList.toggle('hidden', name !== next);
            document.getElementById(`tab-${name}`)?.classList.toggle('is-active', name === next);
            document.getElementById(`tab-${name}`)?.classList.toggle('active', name === next);
        });
        if (next === 'tarkistus') {
            loadProofreadDefaultRules();
            renderProofreadScopeChips();
        }
        if (next === 'viimeistely') {
            scheduleProofreadPreview();
        }
    }

    function renderProofreadChapterBar() {
        const titleEl = document.getElementById('chapter-title-text');
        const subEl = document.getElementById('chapter-title-sub');
        const prev = document.getElementById('btn-prev-chapter');
        const next = document.getElementById('btn-next-chapter');
        const projectTitle = document.getElementById('proofread-project-title');
        const statusText = document.getElementById('proofread-status-text');
        const previewName = document.getElementById('preview-chapter-name');
        const chapters = currentProofreadChapters();
        if (projectTitle) projectTitle.textContent = window.manuscriptData?.title || 'Ei aktiivista teosta';
        if (!chapters.length) {
            if (titleEl) titleEl.textContent = demoUiText('Valitse käsikirjoitus');
            if (subEl) subEl.textContent = '';
            if (statusText) statusText.textContent = demoUiText('Lataa tai valitse käsikirjoitus ensin.');
            if (prev) prev.disabled = true;
            if (next) next.disabled = true;
            return;
        }
        if (proofreadSelection.cIndex === null || !chapters[proofreadSelection.cIndex]) {
            proofreadSelection.cIndex = firstBodyChapterIndex(chapters);
        }
        const index = proofreadSelection.cIndex || 0;
        const chapter = chapters[index];
        const title = chapter?.toc_title || chapter?.title || `Luku ${index + 1}`;
        const words = proofreadChapterText(chapter).split(/\s+/).filter(Boolean).length;
        if (titleEl) titleEl.textContent = title;
        if (subEl) subEl.textContent = `Luku ${index + 1}/${chapters.length}${words ? ` · noin ${formatNumber(words)} sanaa` : ''}`;
        if (statusText) {
            const proofreadState = window.manuscriptData?.analysis?.workflow_state?.proofread?.status || '';
            if (window.manuscriptData?.analysis?.finishing || proofreadState === 'done') {
                statusText.textContent = 'Viimeistelty versio valmis.';
            } else if (proofreadState === 'progress') {
                statusText.textContent = 'Oikoluku kesken.';
            } else {
                statusText.textContent = demoUiText(window.manuscriptData?.id
                    ? 'Valmis aloitettavaksi.'
                    : 'Käsikirjoitus tallennetaan ennen ajoa.');
            }
        }
        if (previewName) previewName.textContent = `- ${title}`;
        if (prev) prev.disabled = index <= 0;
        if (next) next.disabled = index >= chapters.length - 1;
    }

    function gotoProofreadChapter(index) {
        const chapters = currentProofreadChapters();
        if (!chapters.length) return;
        proofreadSelection.cIndex = Math.max(0, Math.min(index, chapters.length - 1));
        proofreadSuggestions = [];
        proofreadExtraFindings = [];
        renderProofreadView();
        if (proofreadPanel === 'viimeistely') scheduleProofreadPreview();
    }

    function renderProofreadChapterSheet() {
        const list = document.getElementById('chapter-sheet-list');
        if (!list) return;
        const chapters = currentProofreadChapters();
        list.innerHTML = chapters.map((chapter, index) => `
            <li>
                <button class="toc-item ${index === proofreadSelection.cIndex ? 'is-current' : ''}" data-proofread-chapter-index="${index}" type="button">
                    <span class="toc-title">${escapeHtml(chapter.toc_title || chapter.title || `Luku ${index + 1}`)}</span>
                </button>
            </li>
        `).join('');
        list.querySelectorAll('[data-proofread-chapter-index]').forEach(button => {
            button.addEventListener('click', () => {
                closeProofreadSheets();
                gotoProofreadChapter(Number(button.dataset.proofreadChapterIndex || 0));
            });
        });
    }

    function openProofreadSheet() {
        renderProofreadChapterSheet();
        document.getElementById('sheet-backdrop')?.classList.remove('hidden');
        document.getElementById('chapter-sheet')?.classList.remove('hidden');
    }

    function closeProofreadSheets() {
        document.getElementById('sheet-backdrop')?.classList.add('hidden');
        document.getElementById('chapter-sheet')?.classList.add('hidden');
    }

    function renderProofreadSuggestions() {
        const list = document.getElementById('suggestions-list');
        const summary = document.getElementById('proofread-summary');
        const acceptAll = document.getElementById('accept-all-row');
        if (!list) return;
        const open = proofreadSuggestions.filter(item => item.status === 'open');
        if (acceptAll) acceptAll.classList.toggle('hidden', open.length < 2);
        if (summary) {
            summary.classList.toggle('hidden', !proofreadSuggestions.length);
            summary.textContent = proofreadSuggestions.length
                ? `${proofreadSuggestions.length} korjausehdotusta, ${open.length} avointa.`
                : '';
        }
        if (!proofreadSuggestions.length) {
            list.innerHTML = '<p class="card-meta">Ei ehdotuksia vielä.</p>';
            return;
        }
        list.innerHTML = proofreadSuggestions.map((item, index) => {
            const statusText = {
                accepted: 'Hyväksytty',
                rejected: 'Hylätty',
                stale: 'Kohtaa ei enää löytynyt',
                open: 'Avoin',
            }[item.status || 'open'] || 'Avoin';
            return `
                <article class="suggestion-item ${item.status && item.status !== 'open' ? 'is-done' : ''}">
                    <div class="suggestion-head">
                        <span class="badge">${escapeHtml(item.type || 'oikoluku')}</span>
                        <span class="where">Kappale ${Number.isInteger(item.paragraph_index) ? item.paragraph_index + 1 : '?'}</span>
                        <span class="where">${escapeHtml(statusText)}</span>
                    </div>
                    <div class="suggestion-change">
                        <del>${escapeHtml(item.original || '')}</del>
                        <span class="arrow">muuttuu</span>
                        <ins>${escapeHtml(item.replacement || '')}</ins>
                    </div>
                    ${item.reason ? `<p class="suggestion-reason">${escapeHtml(item.reason)}</p>` : ''}
                    ${item.status === 'open' ? `
                        <div class="proofread-actions-row">
                            <button class="btn btn-secondary reject-proofread-btn" data-proofread-index="${index}" type="button">Hylkää</button>
                            <button class="btn btn-primary accept-proofread-btn" data-proofread-index="${index}" type="button">Hyväksy</button>
                        </div>
                    ` : ''}
                </article>
            `;
        }).join('');
        list.querySelectorAll('.accept-proofread-btn').forEach(button => {
            button.addEventListener('click', () => acceptProofreadSuggestion(Number(button.dataset.proofreadIndex)));
        });
        list.querySelectorAll('.reject-proofread-btn').forEach(button => {
            button.addEventListener('click', () => {
                const suggestion = proofreadSuggestions[Number(button.dataset.proofreadIndex)];
                if (!suggestion) return;
                suggestion.status = 'rejected';
                renderProofreadSuggestions();
            });
        });
    }

    function renderProofreadScopeChips() {
        const container = document.getElementById('scope-chips');
        const uploadRow = document.getElementById('pdf-upload-row');
        if (!container) return;
        const scopes = [
            ['chapter', 'Valittu luku'],
            ['book', 'Koko kirja'],
            ['pdf', 'PDF-tiedosto'],
        ];
        container.innerHTML = scopes.map(([value, label]) => `
            <button class="tool-chip ${value === proofreadScope ? 'is-active' : ''}" data-proofread-scope="${value}" type="button">${label}</button>
        `).join('');
        container.querySelectorAll('[data-proofread-scope]').forEach(button => {
            button.addEventListener('click', () => {
                proofreadScope = button.dataset.proofreadScope || 'chapter';
                renderProofreadScopeChips();
            });
        });
        if (uploadRow) uploadRow.classList.toggle('hidden', proofreadScope !== 'pdf');
    }

    function renderProofreadExtraFindings(summary = '', warnings = []) {
        const list = document.getElementById('findings-list');
        const summaryEl = document.getElementById('extra-summary');
        if (!list) return;
        setProofreadWarnings('extra-warnings', warnings);
        if (summaryEl) {
            summaryEl.classList.toggle('hidden', !summary);
            summaryEl.textContent = summary;
        }
        if (!proofreadExtraFindings.length) {
            list.innerHTML = '<p class="card-meta">Ei löydöksiä vielä.</p>';
            return;
        }
        list.innerHTML = proofreadExtraFindings.map(item => `
            <article class="finding-item" data-severity="${escapeHtml(item.severity || 'tarkista')}">
                <div class="finding-head">
                    <span class="badge">${escapeHtml(item.category || 'viimeistely')}</span>
                    ${item.location ? `<span class="where">${escapeHtml(item.location)}</span>` : ''}
                </div>
                ${item.excerpt ? `<span class="excerpt">${escapeHtml(item.excerpt)}</span>` : ''}
                ${item.issue ? `<p class="issue">${escapeHtml(item.issue)}</p>` : ''}
                ${item.suggestion ? `<p class="fix">${escapeHtml(item.suggestion)}</p>` : ''}
            </article>
        `).join('');
    }

    function renderProofreadView() {
        renderProofreadChapterBar();
        renderProofreadSuggestions();
        renderProofreadScopeChips();
        renderProofreadExtraFindings();
        loadProofreadDefaultRules();
        showProofreadPanel(proofreadPanel);
    }

    async function runProofreadChapter() {
        const button = document.getElementById('btn-run-proofread');
        const chapterIndex = proofreadSelection.cIndex ?? 0;
        if (!currentProofreadChapters()[chapterIndex]) {
            proofreadToast('Valitse luku ensin.');
            return;
        }
        if (button) button.disabled = true;
        proofreadSuggestions = [];
        renderProofreadSuggestions();
        setProofreadWarnings('proofread-warnings', []);
        try {
            await ensureProofreadProjectSaved('Tallennetaan nykyinen versio...');
            setProofreadWorking(true, 'Oikoluetaan lukua...');
            const res = await apiFetch('/api/proofread/chapter', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    project_id: window.manuscriptData.id,
                    chapter_index: chapterIndex,
                }),
            });
            const data = await res.json().catch(() => null);
            if (!res.ok) throw new Error(data?.detail || 'Oikoluku epäonnistui.');
            proofreadSuggestions = (data.suggestions || []).map(item => ({ ...item, status: 'open' }));
            setProofreadWarnings('proofread-warnings', data.warnings || []);
            renderProofreadSuggestions();
            await markProjectWorkflowStage('proofread', 'progress');
            loadUsage();
        } catch (err) {
            proofreadToast('Oikoluku epäonnistui: ' + err.message);
            loadUsage();
        } finally {
            setProofreadWorking(false);
            if (button) button.disabled = false;
        }
    }

    async function runProofreadExtraCheck() {
        const button = document.getElementById('btn-run-extra');
        const rules = document.getElementById('extra-rules')?.value?.trim() || proofreadDefaultRules || DEFAULT_EXTRA_PROOFREAD_RULES;
        const chapterIndex = proofreadSelection.cIndex ?? 0;
        const pdfFile = document.getElementById('pdf-file')?.files?.[0] || null;
        if (proofreadScope === 'pdf') {
            if (!pdfFile) {
                proofreadToast('Valitse PDF-tiedosto ensin.');
                return;
            }
            if (!pdfFile.name.toLowerCase().endsWith('.pdf')) {
                proofreadToast('Tarkistin ottaa vastaan PDF-tiedoston.');
                return;
            }
        }
        if (proofreadScope !== 'pdf' && !currentProofreadChapters()[chapterIndex]) {
            proofreadToast('Valitse luku tai käsikirjoitus ensin.');
            return;
        }
        if (button) button.disabled = true;
        proofreadExtraFindings = [];
        renderProofreadExtraFindings('', []);
        try {
            let res;
            if (proofreadScope === 'pdf') {
                setProofreadWorking(true, 'Luetaan PDF-tiedostoa...');
                const formData = new FormData();
                formData.append('file', pdfFile);
                formData.append('rules_prompt', rules);
                if (window.manuscriptData?.id) formData.append('project_id', String(window.manuscriptData.id));
                res = await apiFetch('/api/proofread/pdf-check', { method: 'POST', body: formData });
            } else {
                await ensureProofreadProjectSaved('Tallennetaan nykyinen versio...');
                setProofreadWorking(true, proofreadScope === 'book' ? 'Tarkistetaan koko kirjaa...' : 'Tarkistetaan lukua...');
                res = await apiFetch('/api/proofread/extra-check', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        project_id: window.manuscriptData.id,
                        scope: proofreadScope,
                        chapter_index: proofreadScope === 'chapter' ? chapterIndex : null,
                        rules_prompt: rules,
                    }),
                });
            }
            const data = await res.json().catch(() => null);
            if (!res.ok) throw new Error(data?.detail || 'Tarkistus epäonnistui.');
            proofreadExtraFindings = Array.isArray(data.findings) ? data.findings : [];
            renderProofreadExtraFindings(data.summary || `${proofreadExtraFindings.length} löydöstä.`, data.warnings || []);
            await markProjectWorkflowStage('proofread', 'progress');
            loadUsage();
        } catch (err) {
            proofreadToast('Tarkistus epäonnistui: ' + err.message);
            loadUsage();
        } finally {
            setProofreadWorking(false);
            if (button) button.disabled = false;
        }
    }

    async function acceptProofreadSuggestion(index) {
        const suggestion = proofreadSuggestions[index];
        const chapter = currentProofreadChapter();
        if (!suggestion || !chapter) return;
        const changed = applyProofreadSuggestionToChapter(chapter, suggestion);
        if (!changed) {
            suggestion.status = 'stale';
            renderProofreadSuggestions();
            proofreadToast('Kohtaa ei enää löytynyt. Ehdotus voi olla vanhentunut.');
            return;
        }
        try {
            setProofreadWorking(true, 'Tallennetaan korjausta...');
            const saved = await window.saveProjectChapterToDB(window.manuscriptData, proofreadSelection.cIndex);
            if (saved?.id) {
                window.manuscriptData = saved;
                updateAvailableProject(saved);
            }
            suggestion.status = 'accepted';
            renderBookOverview();
            renderWritingView();
            renderProofreadView();
            renderMarketingMaterialsFromAnalysis(false);
            if (window.renderNavList) window.renderNavList();
        } catch (err) {
            proofreadToast('Korjauksen tallennus epäonnistui: ' + err.message);
        } finally {
            setProofreadWorking(false);
        }
    }

    async function acceptAllOpenProofreadSuggestions() {
        const chapter = currentProofreadChapter();
        if (!chapter) return;
        let applied = 0;
        proofreadSuggestions.forEach(suggestion => {
            if (suggestion.status !== 'open') return;
            if (applyProofreadSuggestionToChapter(chapter, suggestion)) {
                suggestion.status = 'accepted';
                applied++;
            } else {
                suggestion.status = 'stale';
            }
        });
        if (!applied) {
            renderProofreadSuggestions();
            proofreadToast('Ei hyväksyttäviä ehdotuksia.');
            return;
        }
        try {
            setProofreadWorking(true, 'Tallennetaan korjauksia...');
            const saved = await window.saveProjectChapterToDB(window.manuscriptData, proofreadSelection.cIndex);
            if (saved?.id) {
                window.manuscriptData = saved;
                updateAvailableProject(saved);
            }
            renderBookOverview();
            renderWritingView();
            renderProofreadView();
            proofreadToast(`${applied} korjausta tallennettu.`);
        } catch (err) {
            proofreadToast('Korjausten tallennus epäonnistui: ' + err.message);
        } finally {
            setProofreadWorking(false);
        }
    }

    function scheduleProofreadPreview() {
        clearTimeout(proofreadPreviewTimer);
        proofreadPreviewTimer = setTimeout(refreshProofreadPreview, 350);
    }

    async function refreshProofreadPreview() {
        const preview = document.getElementById('finishing-preview');
        const chips = document.getElementById('cleanup-counts');
        if (!preview) return;
        if (!window.manuscriptData?.id) {
            preview.textContent = demoUiText('Tallenna käsikirjoitus ennen viimeistelyn esikatselua.');
            if (chips) chips.innerHTML = '';
            return;
        }
        try {
            const res = await apiFetch('/api/proofread/finishing/preview', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    project_id: window.manuscriptData.id,
                    scope: 'chapter',
                    chapter_index: proofreadSelection.cIndex ?? 0,
                    settings: {
                        paragraph_style: proofreadParagraphStyle,
                        hyphenation: proofreadHyphenation,
                    },
                    cleanup: proofreadCleanupKinds(),
                }),
            });
            const data = await res.json().catch(() => null);
            if (!res.ok) throw new Error(data?.detail || 'Esikatselu epäonnistui.');
            preview.textContent = data.text || '';
            if (chips) {
                const counts = data.cleanup_counts || {};
                const total = Object.values(counts).reduce((sum, value) => sum + Number(value || 0), 0);
                chips.innerHTML = total
                    ? `<span class="badge">Siistintä löysi ${formatNumber(total)} kohtaa koko kirjasta</span>`
                    : '<span class="badge">Ei automaattisia siistintöjä</span>';
            }
        } catch (err) {
            preview.textContent = 'Esikatselu epäonnistui: ' + err.message;
            if (chips) chips.innerHTML = '';
        }
    }

    async function downloadProofreadFinished() {
        try {
            await ensureProofreadProjectSaved('Tallennetaan ennen TXT-koontia...');
            setProofreadWorking(true, 'Kootaan viimeisteltyä TXT:tä...');
            const res = await apiFetch('/api/proofread/finishing/preview', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    project_id: window.manuscriptData.id,
                    scope: 'book',
                    settings: {
                        paragraph_style: proofreadParagraphStyle,
                        hyphenation: proofreadHyphenation,
                    },
                    cleanup: proofreadCleanupKinds(),
                }),
            });
            const data = await res.json().catch(() => null);
            if (!res.ok) throw new Error(data?.detail || 'TXT-koonti epäonnistui.');
            const slug = (window.manuscriptData.title || 'kirja').toLowerCase().replace(/[^a-z0-9åäö]+/g, '-').replace(/^-|-$/g, '');
            downloadProofreadText(data.text || '', `viimeistelty-${slug || 'kirja'}.txt`);
        } catch (err) {
            proofreadToast('TXT-lataus epäonnistui: ' + err.message);
        } finally {
            setProofreadWorking(false);
        }
    }

    async function applyProofreadFinishing() {
        try {
            await ensureProofreadProjectSaved('Tallennetaan ennen viimeistelyä...');
            setProofreadWorking(true, 'Valmistellaan viimeisteltyä versiota...');
            const res = await apiFetch('/api/proofread/finishing/apply', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    project_id: window.manuscriptData.id,
                    cleanup: proofreadCleanupKinds(),
                    settings: {
                        paragraph_style: proofreadParagraphStyle,
                        hyphenation: proofreadHyphenation,
                    },
                }),
            });
            const result = await res.json().catch(() => null);
            if (!res.ok) throw new Error(result?.detail || 'Viimeistely epäonnistui.');
            setProofreadWorking(false);
            const total = Number(result.total_changes || 0);
            const message = total
                ? `Siistintä muuttaa ${formatNumber(total)} kohtaa koko käsikirjoituksesta.\n\nLuodaanko viimeistelty versio? Nykyiset luvut korvataan.`
                : 'Siistintä ei löytänyt korjattavaa. Tallennetaanko kappale- ja tavutusasetukset silti?';
            if (!confirm(demoUiText(message))) return;
            setProofreadWorking(true, 'Tallennetaan viimeisteltyä versiota...');
            const saveRes = await apiFetch('/api/projects', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    id: window.manuscriptData.id,
                    title: window.manuscriptData.title,
                    author: window.manuscriptData.author,
                    chapters: result.chapters || [],
                    replace_chapters: true,
                }),
            });
            const saved = await saveRes.json().catch(() => null);
            if (!saveRes.ok) throw new Error(saved?.detail || 'Viimeistellyn version tallennus epäonnistui.');
            const workflowState = {
                ...(window.manuscriptData.analysis?.workflow_state || {}),
                proofread: {
                    ...(window.manuscriptData.analysis?.workflow_state?.proofread || {}),
                    status: 'done',
                    updated_at: new Date().toISOString(),
                },
            };
            const metadataRes = await apiFetch(`/api/projects/${window.manuscriptData.id}/metadata`, {
                method: 'PATCH',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    analysis: {
                        ...(result.finishing_metadata || {}),
                        workflow_state: workflowState,
                    },
                }),
            });
            const metadataProject = await metadataRes.json().catch(() => null);
            if (!metadataRes.ok) throw new Error(metadataProject?.detail || 'Viimeistelyn metadatan tallennus epäonnistui.');
            window.manuscriptData = metadataProject || saved;
            updateAvailableProject(window.manuscriptData);
            renderBookOverview();
            renderWritingView();
            renderProofreadView();
            if (window.renderNavList) window.renderNavList();
            proofreadToast('Viimeistelty versio tallennettu.');
        } catch (err) {
            proofreadToast('Viimeistely epäonnistui: ' + err.message);
        } finally {
            setProofreadWorking(false);
        }
    }

    function applyProofreadSuggestionToChapter(chapter, suggestion) {
        if (!chapter || !suggestion?.original || !suggestion?.replacement) return false;
        let changed = false;
        const targetIndex = Number.isInteger(suggestion.paragraph_index) ? suggestion.paragraph_index : -1;
        if (targetIndex >= 0 && chapter.paragraphs?.[targetIndex]?.includes(suggestion.original)) {
            chapter.paragraphs[targetIndex] = chapter.paragraphs[targetIndex].replace(suggestion.original, suggestion.replacement);
            changed = true;
        } else {
            for (let i = 0; i < (chapter.paragraphs || []).length; i++) {
                if (chapter.paragraphs[i].includes(suggestion.original)) {
                    chapter.paragraphs[i] = chapter.paragraphs[i].replace(suggestion.original, suggestion.replacement);
                    suggestion.paragraph_index = i;
                    changed = true;
                    break;
                }
            }
        }
        return changed;
    }

    function bodyChapterEntries() {
        return (window.manuscriptData?.chapters || [])
            .map((chapter, index) => ({ chapter, index }))
            .filter(({ chapter, index }) => chapterPlacement(chapter, index) === 'body' && (chapter.paragraphs || []).join('').trim());
    }

    function developmentData() {
        if (!window.manuscriptData) return {};
        window.manuscriptData.analysis = window.manuscriptData.analysis || {};
        window.manuscriptData.analysis.development_editing = window.manuscriptData.analysis.development_editing || {};
        return window.manuscriptData.analysis.development_editing;
    }

    function compactDevelopmentText(value, maxChars = 1800) {
        const text = analysisValue(value).replace(/\s+/g, ' ').trim();
        const safeMaxChars = Math.max(1, Math.floor(Number(maxChars || 1)));
        if (!text || text.length <= safeMaxChars) return text;
        if (safeMaxChars < 40) return text.slice(0, safeMaxChars);
        const marker = ' ... ';
        const contentBudget = safeMaxChars - marker.length;
        const head = Math.max(1, Math.floor(contentBudget * 0.62));
        const tail = Math.max(1, contentBudget - head);
        return `${text.slice(0, head).trimEnd()}${marker}${text.slice(-tail).trimStart()}`.slice(0, safeMaxChars);
    }

    // Leave room for the server's safety wrapper and the strictest enabled
    // provider prompt cap (Mistral 36k).
    const LONG_EDIT_REQUEST_MAX_INPUT_CHARS = 35000;

    function checkedLongEditInput(text, prompt, label = 'Mallipyyntö') {
        const safeText = String(text || '');
        const safePrompt = String(prompt || '');
        const inputChars = safeText.length + safePrompt.length;
        if (inputChars > LONG_EDIT_REQUEST_MAX_INPUT_CHARS) {
            throw new Error(
                `${label} on ${formatNumber(inputChars)} merkkiä, joten sitä ei lähetetty `
                + `(${formatNumber(LONG_EDIT_REQUEST_MAX_INPUT_CHARS)} merkin turvaraja). Jaa aineisto pienempiin osiin.`
            );
        }
        return { text: safeText, prompt: safePrompt, inputChars };
    }

    function longEditErrorMessage(value, fallback) {
        if (typeof value === 'string' && value.trim()) return value.trim();
        if (value && typeof value === 'object') {
            try {
                return JSON.stringify(value);
            } catch (_) {
                return fallback;
            }
        }
        return fallback;
    }

    async function readLongEditStream(response, { timerKey = '', label = 'Mallipyyntö', onEvent = null } = {}) {
        let finalPayload = null;
        let streamError = null;
        let rawText = '';
        let buffer = '';
        const handleLine = line => {
            const trimmed = String(line || '').trim();
            if (!trimmed) return;
            let event = null;
            try {
                event = JSON.parse(trimmed);
            } catch (_) {
                return;
            }
            if (typeof onEvent === 'function') {
                try {
                    onEvent(event);
                } catch (error) {
                    console.warn(`${label}: edistymistiedon käsittely epäonnistui.`, error);
                }
            }
            if (event?.type === 'heartbeat') {
                if (timerKey) updateLongOperationTimer(timerKey, { heartbeat: true });
                return;
            }
            if (event?.type === 'error' || event?.detail || event?.error) {
                streamError = longEditErrorMessage(event.detail || event.error, `${label} epäonnistui.`);
                return;
            }
            if (event?.type === 'result' || Object.prototype.hasOwnProperty.call(event || {}, 'edited_text')) {
                finalPayload = event;
            }
        };

        if (response.body?.getReader) {
            const reader = response.body.getReader();
            const decoder = new TextDecoder();
            while (true) {
                const { done, value } = await reader.read();
                if (done) break;
                const decoded = decoder.decode(value, { stream: true });
                if (timerKey && decoded && (decoded.trim() === '' || /^\s{512,}/.test(decoded))) {
                    updateLongOperationTimer(timerKey, { heartbeat: true });
                }
                rawText += decoded;
                buffer += decoded;
                const lines = buffer.split(/\r?\n/);
                buffer = lines.pop() || '';
                lines.forEach(handleLine);
            }
            const tail = decoder.decode();
            rawText += tail;
            buffer += tail;
            handleLine(buffer);
        } else {
            rawText = await response.text();
            rawText.split(/\r?\n/).forEach(handleLine);
        }

        if (!finalPayload && !streamError) {
            try {
                const fallbackPayload = JSON.parse(rawText.trim());
                if (fallbackPayload?.detail || fallbackPayload?.error || fallbackPayload?.type === 'error') {
                    streamError = longEditErrorMessage(fallbackPayload.detail || fallbackPayload.error, `${label} epäonnistui.`);
                } else {
                    finalPayload = fallbackPayload;
                }
            } catch (_) {
                // NDJSON contains several JSON objects, so parsing the whole body is only a compatibility fallback.
            }
        }
        if (!response.ok || streamError) {
            throw new Error(streamError || `${label} epäonnistui.`);
        }
        if (!finalPayload) throw new Error(`${label} ei palauttanut lopputulosta.`);
        return finalPayload;
    }

    async function requestLongEdit(payload, { signal, timerKey = '', label = 'Mallipyyntö' } = {}) {
        const response = await apiFetch('/api/edit/stream', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            signal,
            body: JSON.stringify(payload)
        });
        return readLongEditStream(response, { timerKey, label });
    }

