    async function saveAudioChapterEdits() {
        const entry = currentAudioChapterEntry();
        if (!window.manuscriptData || !entry) {
            setAudioStatus('Valitse käsikirjoitus ja osio ensin.', true);
            return;
        }
        const updatedAt = new Date().toISOString();
        const scoped = audioTextForScope(entry);
        const audio = { ...audioDataFromAnalysis() };
        audio.chapters = { ...(audio.chapters || {}) };
        audio.chapters[audioChapterKey(entry)] = {
            ...savedAudioChapter(entry),
            chapter_index: entry.index,
            chapter_id: entry.chapter.id || `osio_${entry.index + 1}`,
            chapter_title: audioChapterTitle(entry),
            scope: document.getElementById('audio-scope-select')?.value || 'sample_1500',
            production_mode: document.getElementById('audio-production-mode')?.value || 'single_narrator',
            source_char_count: scoped.text.length,
            source_truncated: scoped.shortened,
            audio_script: document.getElementById('audio-chapter-script')?.value || '',
            cast_list: document.getElementById('audio-cast-list')?.value || '',
            pronunciation_guide: document.getElementById('audio-chapter-pronunciation')?.value || '',
            production_notes: document.getElementById('audio-production-notes')?.value || '',
            updated_at: updatedAt
        };
        audio.updated_at = updatedAt;
        try {
            await persistAudioData(audio, `${audioChapterTitle(entry)}: tuotantoaineisto tallennettu.`);
            const saveTime = document.getElementById('audio-chapter-save-time');
            if (saveTime) saveTime.textContent = formatAudioSaveTime(updatedAt);
        } catch (err) {
            setAudioStatus(err.message, true);
        }
    }

    function downloadAudioChapterPackage() {
        const entry = currentAudioChapterEntry();
        if (!entry) {
            setAudioStatus('Valitse ensin osio.', true);
            return;
        }
        const sections = [
            document.getElementById('audio-chapter-script')?.value || '',
            `# Roolilista\n\n${document.getElementById('audio-cast-list')?.value || ''}`,
            `# Ääntämisohjeet\n\n${document.getElementById('audio-chapter-pronunciation')?.value || ''}`,
            `# Tuotantohuomiot\n\n${document.getElementById('audio-production-notes')?.value || ''}`
        ];
        if (!sections.some(section => section.trim())) {
            setAudioStatus('Ladattavaa tuotantoaineistoa ei vielä ole.', true);
            return;
        }
        const safeTitle = audioChapterTitle(entry).toLowerCase().replace(/[^a-z0-9åäö]+/gi, '-').replace(/^-|-$/g, '') || 'audio-osio';
        const blob = new Blob([sections.join('\n\n---\n\n')], {type: 'text/plain;charset=utf-8'});
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `${safeTitle}-tuotantoaineisto.txt`;
        link.click();
        URL.revokeObjectURL(link.href);
    }

    function firstAudioSampleText(maxChars = 5000) {
        const entry = currentAudioChapterEntry();
        if (!entry) return '';
        const safeMaxChars = Math.max(100, Math.min(Number(maxChars) || 5000, 5000));
        return audioTextForScope(entry).text.slice(0, safeMaxChars);
    }

    function audioPreviewNow() {
        return window.performance?.now ? window.performance.now() : Date.now();
    }

    function formatAudioPreviewElapsed(seconds) {
        return `${Math.max(0, Number(seconds) || 0).toLocaleString('fi-FI', {
            minimumFractionDigits: 1,
            maximumFractionDigits: 1
        })} s`;
    }

    function formatAudioPreviewDuration(seconds) {
        const total = Math.max(0, Math.round(Number(seconds) || 0));
        if (total < 60) return `${total} s`;
        const hours = Math.floor(total / 3600);
        const minutes = Math.floor((total % 3600) / 60);
        const remainingSeconds = total % 60;
        if (hours) return `${hours} h ${minutes} min`;
        return remainingSeconds ? `${minutes} min ${remainingSeconds} s` : `${minutes} min`;
    }

    function estimateAudioPreview(text, provider, modelId, playbackSpeed = 1) {
        const normalizedText = String(text || '').trim();
        const wordCount = normalizedText ? normalizedText.split(/\s+/u).filter(Boolean).length : 0;
        const characterCount = normalizedText.length;
        const effectiveWordCount = Math.max(wordCount, Math.ceil(characterCount / 7));
        const safePlaybackSpeed = Math.max(.5, Math.min(2, Number(playbackSpeed) || 1));
        const estimatedAudioSeconds = Math.max(1, Math.ceil(((effectiveWordCount / 150) * 60) / safePlaybackSpeed));
        const normalizedProvider = String(provider || '').toLowerCase();
        const normalizedModel = String(modelId || '').toLowerCase();
        let baseSeconds = 7;
        let realtimeFactor = .42;
        const estimateCalibration = normalizedProvider === 'gemini'
            ? 1.5
            : normalizedProvider === 'elevenlabs' ? .5 : 1;
        if (normalizedProvider === 'gemini') {
            baseSeconds = normalizedModel.includes('pro') ? 10 : 7;
            realtimeFactor = normalizedModel.includes('pro') ? .58 : .38;
        } else if (normalizedModel.includes('flash')) {
            baseSeconds = 5;
            realtimeFactor = .28;
        } else if (normalizedModel.includes('v3')) {
            baseSeconds = 9;
            realtimeFactor = .62;
        }
        const baselineGenerationSeconds = Math.max(
            5,
            Math.ceil(baseSeconds + estimatedAudioSeconds * realtimeFactor)
        );
        return {
            character_count: characterCount,
            word_count: wordCount,
            estimated_audio_seconds: estimatedAudioSeconds,
            estimated_generation_seconds: Math.max(
                5,
                Math.ceil(baselineGenerationSeconds * estimateCalibration)
            )
        };
    }

    function audioPreviewUi(provider) {
        const gemini = provider === 'gemini';
        return {
            waiting: document.getElementById(gemini ? 'audio-gemini-preview-waiting' : 'audio-eleven-preview-waiting'),
            elapsed: document.getElementById(gemini ? 'audio-gemini-preview-elapsed' : 'audio-eleven-preview-elapsed'),
            estimate: document.getElementById(gemini ? 'audio-gemini-preview-waiting-estimate' : 'audio-eleven-preview-waiting-estimate'),
            list: document.getElementById(gemini ? 'audio-gemini-preview-list' : 'audio-eleven-preview-list')
        };
    }

    function updateAudioPreviewElapsed(provider) {
        const state = audioPreviewRuns[provider];
        if (!state?.running) return 0;
        const elapsedSeconds = Math.max(0, (audioPreviewNow() - state.startedAt) / 1000);
        const elapsed = audioPreviewUi(provider).elapsed;
        if (elapsed) elapsed.textContent = formatAudioPreviewElapsed(elapsedSeconds);
        return elapsedSeconds;
    }

    function beginAudioPreviewRun(provider, estimate) {
        const state = audioPreviewRuns[provider];
        if (!state || state.running) return false;
        const ui = audioPreviewUi(provider);
        state.running = true;
        state.startedAt = audioPreviewNow();
        if (state.timer) window.clearInterval(state.timer);
        if (ui.elapsed) ui.elapsed.textContent = formatAudioPreviewElapsed(0);
        if (ui.estimate) {
            ui.estimate.textContent = `Arvioitu valmistumisaika noin ${formatAudioPreviewDuration(estimate?.estimated_generation_seconds)}.`;
        }
        ui.waiting?.classList.remove('hidden');
        state.timer = window.setInterval(() => updateAudioPreviewElapsed(provider), 100);
        return true;
    }

    function finishAudioPreviewRun(provider) {
        const state = audioPreviewRuns[provider];
        if (!state) return 0;
        const elapsedSeconds = state.running
            ? Math.max(0, (audioPreviewNow() - state.startedAt) / 1000)
            : 0;
        state.running = false;
        if (state.timer) window.clearInterval(state.timer);
        state.timer = null;
        audioPreviewUi(provider).waiting?.classList.add('hidden');
        return elapsedSeconds;
    }

    function renderAudioPreviewEmptyState(provider) {
        const list = audioPreviewUi(provider).list;
        if (!list || list.querySelector('.audio-preview-result')) return;
        const name = provider === 'gemini' ? 'Gemini' : 'ElevenLabs';
        list.innerHTML = `<p class="audio-preview-empty">Valmiit ${name}-testit ilmestyvät tähän vertailua varten.</p>`;
    }

    function appendAudioPreviewResult(provider, blob, preview) {
        const list = audioPreviewUi(provider).list;
        if (!list) throw new Error('Testinäytteiden vertailulistaa ei löytynyt.');
        list.querySelector('.audio-preview-empty')?.remove();
        const previewId = `audio-preview-${Date.now()}-${++audioPreviewSequence}`;
        const objectUrl = URL.createObjectURL(blob);
        audioPreviewObjectUrls.set(previewId, objectUrl);
        const createdAt = new Date(preview.created_at || Date.now());
        const createdLabel = Number.isNaN(createdAt.getTime())
            ? 'Luontiaika ei saatavilla'
            : createdAt.toLocaleString('fi-FI', { dateStyle: 'short', timeStyle: 'medium' });
        const providerName = preview.provider_name || (provider === 'gemini' ? 'Gemini TTS' : 'ElevenLabs');
        const article = document.createElement('article');
        article.className = `audio-preview-result is-${provider}`;
        article.dataset.previewId = previewId;
        article.innerHTML = `
            <div class="audio-preview-result-heading">
                <div>
                    <span>${escapeHtml(providerName)}</span>
                    <strong>${escapeHtml(preview.voice_name || 'Nimetön ääni')}</strong>
                </div>
                <button class="audio-preview-delete" type="button" aria-label="Poista testinäyte">Poista</button>
            </div>
            <div class="audio-preview-facts">
                <span><small>Malli</small>${escapeHtml(preview.model_name || preview.model_id || 'Ei tiedossa')}</span>
                <span><small>Syöte</small>${formatNumber(preview.character_count || 0)} merkkiä · ${formatNumber(preview.word_count || 0)} sanaa</span>
                <span><small>Äänikesto, arvio</small>${escapeHtml(formatAudioPreviewDuration(preview.estimated_audio_seconds))}</span>
                <span><small>Valmistuminen, arvio</small>${escapeHtml(formatAudioPreviewDuration(preview.estimated_generation_seconds))}</span>
                <span><small>Toteutunut aika</small>${escapeHtml(formatAudioPreviewElapsed(preview.elapsed_seconds))}</span>
                <span><small>Luotu</small>${escapeHtml(createdLabel)}</span>
            </div>
            <audio class="audio-preview-player" controls preload="metadata"></audio>
        `;
        const player = article.querySelector('.audio-preview-player');
        player.src = objectUrl;
        article.querySelector('.audio-preview-delete')?.addEventListener('click', () => {
            player.pause();
            player.removeAttribute('src');
            player.load();
            const url = audioPreviewObjectUrls.get(previewId);
            if (url) URL.revokeObjectURL(url);
            audioPreviewObjectUrls.delete(previewId);
            article.remove();
            renderAudioPreviewEmptyState(provider);
        });
        list.prepend(article);
        return player;
    }

    function audioPlayer() {
        return document.getElementById('audio-eleven-player');
    }

    async function testGeminiTtsVoice() {
        if (!window.manuscriptData?.id) {
            setAudioStatus('Valitse tallennettu käsikirjoitus ensin.', true);
            return;
        }
        const modelId = document.getElementById('audio-gemini-model-select')?.value || '';
        const model = geminiTtsModels.find(item => item.model_name === modelId);
        if (!model) {
            setAudioStatus('Valitse ensin Gemini TTS -malli.', true);
            return;
        }
        const text = firstAudioSampleText(700);
        if (!text) {
            setAudioStatus('Valitusta osiosta ei löytynyt kuunneltavaa tekstiä.', true);
            return;
        }
        const voiceName = document.getElementById('audio-gemini-voice-select')?.value || 'Kore';
        const button = document.getElementById('audio-gemini-test-btn');
        const estimate = estimateAudioPreview(text, 'gemini', model.model_name);
        stopAudioVoice(false);
        if (!beginAudioPreviewRun('gemini', estimate)) return;
        if (button) button.disabled = true;
        setAudioStatus(
            `Luodaan ${model.display_name} -testinäyte äänellä ${voiceName}. `
            + `Arvioitu valmistumisaika noin ${formatAudioPreviewDuration(estimate.estimated_generation_seconds)}.`
        );
        try {
            const res = await apiFetch('/api/audio/gemini-tts-preview', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    project_id: window.manuscriptData.id,
                    text,
                    model_id: model.model_name,
                    voice_name: voiceName,
                    delivery: document.getElementById('audio-gemini-delivery-select')?.value || 'natural'
                })
            });
            if (!res.ok) {
                const data = await res.json().catch(() => null);
                throw new Error(data?.detail || 'Gemini TTS -testinäytteen luonti epäonnistui.');
            }
            const blob = await res.blob();
            if (!blob.size || !String(blob.type || '').startsWith('audio/')) {
                throw new Error('Gemini TTS ei palauttanut toistettavaa äänitiedostoa.');
            }
            const elapsedSeconds = finishAudioPreviewRun('gemini');
            const preview = {
                created_at: res.headers.get('X-Audio-Created-At') || new Date().toISOString(),
                provider: 'gemini',
                provider_name: 'Gemini TTS',
                model_id: res.headers.get('X-Audio-Model') || model.model_name,
                model_name: model.display_name,
                voice_name: res.headers.get('X-Audio-Voice') || voiceName,
                ...estimate,
                elapsed_seconds: elapsedSeconds
            };
            const player = appendAudioPreviewResult('gemini', blob, preview);
            player.onended = () => setAudioStatus('Gemini TTS -testinäyte päättyi.');
            await persistGeminiTtsSettings(preview);
            try {
                await player.play();
                setAudioStatus(`${audioChapterTitle(currentAudioChapterEntry())}: Gemini TTS -testinäytettä toistetaan.`);
            } catch (err) {
                setAudioStatus('Gemini-testinäyte on valmis. Käynnistä se soittimen painikkeesta.');
            }
        } catch (err) {
            setAudioStatus(err.message || 'Gemini TTS -äänitesti epäonnistui.', true);
        } finally {
            finishAudioPreviewRun('gemini');
            renderGeminiTtsMeta();
        }
    }

    async function playSelectedVoicePreview() {
        const select = document.getElementById('audio-voice-select');
        const voice = elevenLabsVoices.find(item => item.voice_id === select?.value);
        if (!voice?.preview_url) {
            setAudioStatus('Tälle äänelle ei ole saatavilla valmista esittelynäytettä.', true);
            return;
        }
        stopAudioVoice(false);
        const player = audioPlayer();
        if (!player) return;
        player.src = voice.preview_url;
        player.classList.remove('hidden');
        setAudioStatus(`Toistetaan lukijaäänen ${voice.name} valmis esittelynäyte.`);
        try {
            await player.play();
        } catch (err) {
            setAudioStatus('Esittely on ladattu soittimeen. Käynnistä se soittimen painikkeesta.');
        }
    }

    async function testAudioVoice() {
        if (!window.manuscriptData?.id) {
            setAudioStatus('Valitse tallennettu käsikirjoitus ensin.', true);
            return;
        }
        const selectedVoiceId = document.getElementById('audio-voice-select')?.value || '';
        if (!selectedVoiceId) {
            setAudioStatus('Valitse ensin ElevenLabs-lukijaääni.', true);
            return;
        }
        const text = firstAudioSampleText(2000);
        if (!text) {
            setAudioStatus('Valitusta osiosta ei löytynyt kuunneltavaa tekstiä.', true);
            return;
        }
        const button = document.getElementById('audio-test-voice-btn');
        const selectedVoice = elevenLabsVoices.find(voice => voice.voice_id === selectedVoiceId);
        const selectedModel = document.getElementById('audio-tts-model-select');
        const modelId = selectedModel?.value || 'eleven_multilingual_v2';
        const modelName = selectedModel?.selectedOptions?.[0]?.textContent?.trim() || modelId;
        const selectedSpeed = Number(document.getElementById('audio-rate-select')?.value || 1);
        const estimate = estimateAudioPreview(text, 'elevenlabs', modelId, selectedSpeed);
        stopAudioVoice(false);
        if (!beginAudioPreviewRun('elevenlabs', estimate)) return;
        if (button) button.disabled = true;
        setAudioStatus(
            `Luodaan lukijaäänellä ${selectedVoice?.name || 'valittu ääni'} lyhyt testinäyte ElevenLabsissa. `
            + `Arvioitu valmistumisaika noin ${formatAudioPreviewDuration(estimate.estimated_generation_seconds)}.`
        );
        try {
            const res = await apiFetch('/api/audio/tts-preview', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    project_id: window.manuscriptData.id,
                    voice_id: selectedVoiceId,
                    text,
                    model_id: modelId,
                    delivery: document.getElementById('audio-delivery-select')?.value || 'natural',
                    speed: selectedSpeed
                })
            });
            if (!res.ok) {
                const data = await res.json().catch(() => null);
                throw new Error(data?.detail || 'ElevenLabs-äänitestin luonti epäonnistui.');
            }
            const blob = await res.blob();
            if (!blob.size || !String(blob.type || '').startsWith('audio/')) {
                throw new Error('ElevenLabs ei palauttanut toistettavaa äänitiedostoa.');
            }
            const elapsedSeconds = finishAudioPreviewRun('elevenlabs');
            const preview = {
                created_at: res.headers.get('X-Audio-Created-At') || new Date().toISOString(),
                provider: 'elevenlabs',
                provider_name: 'ElevenLabs',
                model_id: res.headers.get('X-Audio-Model') || modelId,
                model_name: modelName,
                voice_name: selectedVoice?.name || selectedVoiceId,
                ...estimate,
                elapsed_seconds: elapsedSeconds
            };
            const player = appendAudioPreviewResult('elevenlabs', blob, preview);
            player.onended = () => setAudioStatus('ElevenLabs-testinäyte päättyi.');
            await persistAudioVoiceSettings(preview);
            try {
                await player.play();
                setAudioStatus(`${audioChapterTitle(currentAudioChapterEntry())}: ElevenLabs-testinäytettä toistetaan.`);
            } catch (err) {
                setAudioStatus('Testinäyte on valmis. Käynnistä se soittimen painikkeesta.');
            }
        } catch (err) {
            setAudioStatus(err.message || 'ElevenLabs-äänitesti epäonnistui.', true);
        } finally {
            finishAudioPreviewRun('elevenlabs');
            if (button) button.disabled = false;
        }
    }

    function stopAudioVoice(showStatus = true) {
        if (window.speechSynthesis) window.speechSynthesis.cancel();
        [audioPlayer(), ...document.querySelectorAll('.audio-preview-player')].forEach(player => {
            if (!player) return;
            player.pause();
            player.currentTime = 0;
        });
        if (showStatus) {
            const generationRunning = audioPreviewRuns.gemini.running || audioPreviewRuns.elevenlabs.running;
            setAudioStatus(generationRunning
                ? 'Toisto pysäytetty. Käynnissä oleva testinäytteen luonti jatkuu palvelimella.'
                : 'Äänitesti pysäytetty.');
        }
    }

    function workflowPlanSignature(plan) {
        return JSON.stringify({
            template: plan?.templateId || plan?.template_id || 'custom',
            modules: (plan?.modules || []).map(module => [
                module.id,
                workflowModuleExecutionMode(module),
                module.resolvedModel || module.resolved_model || module.model || ''
            ]),
            settings: plan?.settings || {}
        });
    }

    function workflowPlanSnapshot(plan) {
        return {
            templateId: plan?.templateId || plan?.template_id || 'custom',
            customized: Boolean(plan?.customized),
            modules: (plan?.modules || []).map(module => ({
                id: module.id,
                executionMode: workflowModuleExecutionMode(module),
                execution_mode: workflowModuleExecutionMode(module),
                model: module.model || '',
                resolvedModel: module.resolvedModel || module.resolved_model || module.model || ''
            })),
            settings: plan?.settings && typeof plan.settings === 'object' ? { ...plan.settings } : {}
        };
    }

    async function executeWorkflowModule(module, plan) {
        const options = { model: workflowModuleModel(module, plan) || null };
        switch (module.id) {
            case 'analysis':
                return runWorkflowAnalysis(options);
            case 'project_memory':
                return runWorkflowProjectMemory(options);
            case 'structure':
                return runWorkflowStructure();
            case 'development_feedback':
                return runWorkflowDevelopmentFeedback(options);
            case 'edit':
                return runWorkflowEditChapters(options);
            case 'proofread':
                return runWorkflowProofreadChapters(options);
            case 'translation':
                return runWorkflowTranslation(module, plan);
            case 'translation_review':
                return runWorkflowTranslationReview(module, plan);
            case 'product':
                return runWorkflowProductInfo(options);
            case 'marketing':
                return runWorkflowMarketingMaterials(options);
            case 'covers':
                return runWorkflowCovers(options);
            case 'misc':
                return runWorkflowMisc({
                    ...options,
                    extended: (plan?.templateId || plan?.template_id) === 'publisher'
                });
            case 'layout':
                return runWorkflowLayout();
            case 'audio':
                return runWorkflowAudio(module, plan);
            default:
                throw new Error(`Tuntematonta työnkulkumoduulia ei voida käynnistää: ${module.id || 'tuntematon'}.`);
        }
    }

    async function runAiWorkflow(requestedPlan, controller = workflowStudio) {
        if (workflowRunning) return;
        const plan = requestedPlan?.modules ? requestedPlan : controller?.getPlan?.();
        const modules = Array.isArray(plan?.modules) ? plan.modules.filter(module => module?.id) : [];
        if (!window.manuscriptData?.chapters?.length) {
            setWorkflowStatus('Valitse tekstillinen käsikirjoitus ennen työnkulun käynnistämistä.', true);
            return;
        }
        if (!modules.length) {
            setWorkflowStatus('Lisää työnkulkuun vähintään yksi moduuli.', true);
            return;
        }

        workflowRunning = true;
        controller?.setRunning?.(true);
        const signature = workflowPlanSignature(plan);
        const previousRun = controller?.getRunState?.() || {};
        const sameRun = String(previousRun.projectId || '') === String(window.manuscriptData?.id || '')
            && previousRun.planSignature === signature
            && ['running', 'queued', 'error'].includes(previousRun.status);
        let startIndex = sameRun ? Math.max(0, Number(previousRun.currentIndex || 0)) : 0;
        if (!sameRun) {
            startIndex = 0;
            controller?.resetStepStatuses?.();
            workflowLatestTranslation = null;
            controller?.setRunState?.({});
        } else {
            startIndex = Math.min(startIndex, modules.length);
        }
        workflowRunStatePatch({
            status: 'running',
            running: true,
            projectId: window.manuscriptData?.id || null,
            planSignature: signature,
            planSnapshot: workflowPlanSnapshot(plan),
            currentIndex: startIndex,
            startedAt: sameRun && previousRun.startedAt ? previousRun.startedAt : new Date().toISOString(),
            finishedAt: null
        });
        setWorkflowStatus(startIndex
            ? `Jatketaan työnkulkua vaiheesta ${startIndex + 1}/${modules.length}.`
            : `Työnkulku käynnissä · 0/${modules.length} vaihetta valmiina.`);

        try {
            await ensureWorkflowProject();
            workflowRunStatePatch({ projectId: window.manuscriptData.id });
            await markProjectWorkflowStage('ai_workflow', 'running');
            for (let index = startIndex; index < modules.length; index += 1) {
                const module = modules[index];
                workflowRunStatePatch({ status: 'running', currentIndex: index, currentStepId: module.id });
                setWorkflowStep(module.id, 'running', `Vaihe ${index + 1}/${modules.length} käynnistyy.`);
                try {
                    await executeWorkflowModule(module, plan);
                } catch (error) {
                    const message = networkFailureMessage(error);
                    setWorkflowStep(module.id, 'error', message);
                    workflowRunStatePatch({ status: 'error', running: false, currentIndex: index, currentStepId: module.id, error: message });
                    throw error;
                }
                workflowRunStatePatch({
                    status: 'running',
                    currentIndex: index + 1,
                    currentStepId: null,
                    activeJob: null,
                    error: ''
                });
                setWorkflowStatus(`Työnkulku etenee · ${index + 1}/${modules.length} vaihetta valmiina.`);
            }
            await loadUsage();
            await markProjectWorkflowStage('ai_workflow', 'completed');
            workflowRunStatePatch({
                status: 'completed',
                running: false,
                currentIndex: modules.length,
                currentStepId: null,
                activeJob: null,
                finishedAt: new Date().toISOString(),
                error: ''
            });
            setWorkflowStatus(`Työnkulku valmis. Kaikki ${modules.length} valittua vaihetta on käsitelty ja tulokset on tallennettu.`);
        } catch (error) {
            await markProjectWorkflowStage('ai_workflow', 'error').catch(() => null);
            workflowRunStatePatch({ status: 'error', running: false, error: networkFailureMessage(error) });
            setWorkflowStatus(`Työnkulku odottaa jatkamista: ${networkFailureMessage(error)}`, true);
        } finally {
            workflowRunning = false;
            workflowRunStatePatch({ running: false });
            controller?.setRunning?.(false);
            renderWorkflowView();
        }
    }

    // --- 6. Global Task Manager ---
    window.startLongTask = function(title, desc, durationSeconds) {
        const overlay = document.getElementById('global-task-overlay');
        const titleEl = document.getElementById('task-title');
        const descEl = document.getElementById('task-desc');
        const barEl = document.getElementById('task-progress-bar');
        const timeEl = document.getElementById('task-time-left');
        const percentEl = document.getElementById('task-percent');
        const closeBtn = document.getElementById('task-close-btn');

        if(!overlay) return;

        overlay.classList.remove('hidden');
        if(closeBtn) closeBtn.classList.add('hidden');
        
        titleEl.textContent = title;
        descEl.textContent = desc;
        barEl.style.width = '0%';
        percentEl.textContent = '0%';
        
        let timeLeft = durationSeconds;
        const total = durationSeconds;
        
        const formatTime = (secs) => {
            const m = Math.floor(secs / 60);
            const s = Math.floor(secs % 60);
            return `${m} min ${s < 10 ? '0' : ''}${s} s`;
        };
        
        timeEl.textContent = `Arvioitu aika: ${formatTime(timeLeft)}`;

        const interval = setInterval(() => {
            timeLeft -= 1;
            if (timeLeft <= 0) {
                clearInterval(interval);
                barEl.style.width = '100%';
                percentEl.textContent = '100%';
                timeEl.textContent = 'Valmis!';
                titleEl.textContent = '✨ Tehtävä suoritettu';
                if(closeBtn) closeBtn.classList.remove('hidden');
            } else {
                const p = Math.floor(((total - timeLeft) / total) * 100);
                barEl.style.width = `${p}%`;
                percentEl.textContent = `${p}%`;
                timeEl.textContent = `Arvioitu aika: ${formatTime(timeLeft)}`;
            }
        }, 1000);
    };

