    async function fetchSavedTranslation(translationId) {
        const res = await apiFetch(`/api/translations/${translationId}`);
        const data = await res.json().catch(() => null);
        if (!res.ok) throw new Error(data?.detail || 'Valmiin käännöksen haku epäonnistui.');
        return data;
    }

    function translationBatchCountdown(targetCompletionAt) {
        const target = new Date(targetCompletionAt || '').getTime();
        if (!Number.isFinite(target)) return 'tavoiteaika enintään 24 h';
        const remaining = Math.max(0, Math.ceil((target - Date.now()) / 1000));
        if (remaining <= 0) return '24 h määräaika täynnä – työ päättyy ja varaus vapautetaan';
        const hours = Math.floor(remaining / 3600);
        const minutes = Math.floor((remaining % 3600) / 60);
        const seconds = remaining % 60;
        return `tavoiteaikaa jäljellä ${hours}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
    }

    function translationJobProgressText(job, label) {
        const done = Number(job?.done_chunks || 0);
        const total = Number(job?.total_chunks || 0);
        if (job?.execution_mode === 'batch') {
            const phase = job.status === 'processing'
                ? 'Vastausta tallennetaan projektiin.'
                : demoPriceSafeText(job.message || 'Eräajo on Geminin käsittelyssä.', 'Eräajo on Geminin käsittelyssä.');
            return `${label}: ${phase} ${translationBatchCountdown(job.target_completion_at)}`;
        }
        return total
            ? `${label} käynnissä. Osa ${Math.min(done, total)}/${total}.`
            : demoPriceSafeText(job?.message || `${label} käynnissä.`, `${label} käynnissä.`);
    }

    function translationStoppedError(status, label) {
        const normalized = String(status || 'cancelled').trim().toLowerCase();
        const error = new Error(normalized === 'expired'
            ? `${label} päättyi 24 tunnin määräaikaan. Työvaraus vapautettiin.`
            : `${label} pysäytettiin.`);
        error.name = 'OperationStoppedError';
        error.operationStopped = true;
        error.operationStatus = normalized;
        return error;
    }

    function translationCancelButtonId(view) {
        return ({
            translation: 'translation-cancel-btn',
            finnish: 'finnish-translation-cancel-btn',
            workspace: 'translation-workspace-cancel-btn'
        })[view] || '';
    }

    function setActiveTranslationJob(view, jobId, expectedJobId = null) {
        if (!Object.prototype.hasOwnProperty.call(activeTranslationJobIds, view)) return;
        if (
            expectedJobId !== null
            && String(activeTranslationJobIds[view] || '') !== String(expectedJobId || '')
        ) return;
        activeTranslationJobIds[view] = jobId || null;
        const button = document.getElementById(translationCancelButtonId(view));
        if (button) {
            button.classList.toggle('hidden', !jobId);
            button.disabled = !jobId;
            button.textContent = view === 'workspace' ? 'Pysäytä käännös' : 'Pysäytä käännös';
        }
    }

    function stopTranslationJobPolling(jobId, status = 'cancelled') {
        const token = translationJobPollTokens.get(String(jobId));
        if (!token) return;
        token.stoppedStatus = String(status || 'cancelled').trim().toLowerCase();
        if (token.requestController) token.requestController.abort();
        if (typeof token.wake === 'function') token.wake();
    }

    function waitForTranslationJobPoll(milliseconds, token) {
        return new Promise(resolve => {
            const finish = () => {
                if (token.timer) window.clearTimeout(token.timer);
                token.timer = null;
                token.wake = null;
                resolve();
            };
            token.wake = finish;
            token.timer = window.setTimeout(finish, milliseconds);
        });
    }

    async function requestTranslationJobCancellation(jobId) {
        const response = await apiFetch(`/api/translations/jobs/${jobId}/cancel`, { method: 'POST' });
        const data = await response.json().catch(() => null);
        if (!response.ok) throw new Error(demoPriceSafeText(
            data?.detail || 'Työn pysäyttäminen epäonnistui.',
            'Työn pysäyttäminen epäonnistui.'
        ));
        return data || {};
    }

    async function cancelTranslationJob(view) {
        const jobId = activeTranslationJobIds[view];
        if (!jobId) return;
        if (!window.confirm('Pysäytetäänkö käynnissä oleva käännös? Jo valmistuneet osat voidaan säilyttää palvelimella.')) return;
        const button = document.getElementById(translationCancelButtonId(view));
        if (button) {
            button.disabled = true;
            button.textContent = 'Pysäytetään…';
        }
        try {
            const data = await requestTranslationJobCancellation(jobId);
            const status = String(data?.status || data?.job?.status || 'cancelled').trim().toLowerCase();
            stopTranslationJobPolling(jobId, status);
            setActiveTranslationJob(view, null, jobId);
            if (view === 'workspace') {
                setTranslationWorkspaceProgress(0, 'Käännös pysäytettiin', 'Työvaraus on vapautettu.');
            } else {
                const statusElement = document.getElementById(
                    view === 'finnish' ? 'finnish-translation-status' : 'translation-status'
                );
                if (statusElement) statusElement.textContent = 'Käännös pysäytettiin. Työvaraus on vapautettu.';
            }
        } catch (err) {
            if (button) {
                button.disabled = false;
                button.textContent = 'Pysäytä käännös';
            }
            const statusElement = document.getElementById(
                view === 'workspace' ? 'translation-workspace-run-status'
                    : view === 'finnish' ? 'finnish-translation-status'
                    : 'translation-status'
            );
            if (statusElement) statusElement.textContent = demoPriceSafeText(
                err?.message || 'Työn pysäyttäminen epäonnistui.',
                'Työn pysäyttäminen epäonnistui.'
            );
        }
    }

    async function pollTranslationJob(jobId, statusEl, label, onProgress = null) {
        let latestJob = null;
        let countdownInterval = null;
        const token = { stoppedStatus: null, requestController: null, wake: null, timer: null };
        translationJobPollTokens.set(String(jobId), token);
        try {
            while (true) {
                if (token.stoppedStatus) throw translationStoppedError(token.stoppedStatus, label);
                token.requestController = new AbortController();
                let res;
                try {
                    res = await apiFetch(`/api/translations/jobs/${jobId}`, { signal: token.requestController.signal });
                } catch (err) {
                    if (token.stoppedStatus && err?.name === 'AbortError') {
                        throw translationStoppedError(token.stoppedStatus, label);
                    }
                    throw err;
                } finally {
                    token.requestController = null;
                }
                const job = await res.json().catch(() => null);
                if (!res.ok) throw new Error(demoPriceSafeText(
                    job?.detail || 'Käännöstyön tilan haku epäonnistui.',
                    'Käännöstyön tilan haku epäonnistui.'
                ));
                latestJob = job;
                if (statusEl) statusEl.textContent = translationJobProgressText(job, label);
                if (typeof onProgress === 'function') onProgress(job);
                if (job?.execution_mode === 'batch' && !countdownInterval) {
                    countdownInterval = window.setInterval(() => {
                        if (statusEl && latestJob) statusEl.textContent = translationJobProgressText(latestJob, label);
                        if (typeof onProgress === 'function' && latestJob) onProgress(latestJob);
                    }, 1000);
                }
                if ((job.status === 'done' || job.status === 'completed' || job.status === 'partial') && job.translation_id) {
                    const savedTranslation = await fetchSavedTranslation(job.translation_id);
                    if (job.status === 'partial') {
                        savedTranslation.batch_job_status = 'partial';
                        if (job.error || job.message) {
                            savedTranslation.batch_job_error = demoPriceSafeText(
                                job.error || job.message,
                                'Kaikkia segmenttejä ei voitu käsitellä.'
                            );
                        }
                    }
                    return savedTranslation;
                }
                if (job.status === 'done' || job.status === 'completed' || job.status === 'partial') {
                    throw new Error(demoPriceSafeText(
                        job.message || `${label} valmistui, mutta valmista käännöstä ei löytynyt.`,
                        `${label} valmistui, mutta valmista käännöstä ei löytynyt.`
                    ));
                }
                if (job.status === 'failed' || job.status === 'error') {
                    throw new Error(demoPriceSafeText(
                        job.error || job.message || `${label} epäonnistui.`,
                        `${label} epäonnistui.`
                    ));
                }
                if (['cancelled', 'canceled', 'cancel_requested', 'expired'].includes(String(job.status || '').toLowerCase())) {
                    throw translationStoppedError(job.status, label);
                }
                await waitForTranslationJobPoll(job?.execution_mode === 'batch' ? 15000 : 2500, token);
            }
        } finally {
            window.clearInterval(countdownInterval);
            if (token.timer) window.clearTimeout(token.timer);
            if (translationJobPollTokens.get(String(jobId)) === token) {
                translationJobPollTokens.delete(String(jobId));
            }
        }
    }

    async function runTranslationJob(payload, statusEl, label, view) {
        const res = await apiFetch('/api/translations/jobs', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify(payload)
        });
        const job = await res.json().catch(() => null);
        if (!res.ok) throw new Error(demoPriceSafeText(
            job?.detail || `${label} ei käynnistynyt.`,
            `${label} ei käynnistynyt.`
        ));
        if (statusEl) {
            const total = Number(job?.total_chunks || 0);
            statusEl.textContent = job?.execution_mode === 'batch'
                ? `${label} lähetetty eräajoon. ${translationBatchCountdown(job.target_completion_at)}`
                : (total ? `${label} jonossa. ${total} osaa odottaa käännöstä.` : `${label} jonossa.`);
        }
        setActiveTranslationJob(view, job.job_id);
        try {
            return await pollTranslationJob(job.job_id, statusEl, label);
        } finally {
            setActiveTranslationJob(view, null, job.job_id);
        }
    }

    async function createFinnishTranslationGuidelines(options = {}) {
        const useModel = options.useModel !== false;
        const payload = finnishTranslationRequestPayload({ includeInstructions: true });
        payload.use_model = useModel;
        if (useModel) payload.model = null;
        const project = currentFinnishTranslationProject();
        const textarea = document.getElementById('finnish-translation-instructions');
        const button = document.getElementById(useModel ? 'finnish-translation-guidelines-btn' : 'finnish-translation-analysis-guidelines-btn');
        const alternateButton = document.getElementById(useModel ? 'finnish-translation-analysis-guidelines-btn' : 'finnish-translation-guidelines-btn');
        const status = document.getElementById('finnish-translation-guidelines-status');
        if (!payload.project_id || !project) {
            alert('Valitse ensin käsikirjoitus.');
            return;
        }
        const actionLabel = useModel ? 'mallilla luodulla käännöspromptilla' : 'analyysin perusteella luodulla käännöspromptilla';
        if (textarea?.value?.trim() && !confirm(`Korvataanko nykyinen hienosäätö ${actionLabel}?`)) {
            return;
        }
        if (button) button.disabled = true;
        if (alternateButton) alternateButton.disabled = true;
        if (status) {
            status.textContent = useModel
                ? 'Luodaan käännöspromptia mallilla...'
                : 'Luodaan käännöspromptia analyysin perusteella ilman mallikutsua...';
        }
        try {
            const res = await apiFetch('/api/translations/guidelines', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            if (!res.ok) throw new Error(data.detail || 'Käännösohjeiden luonti epäonnistui.');
            if (!data.guidelines) throw new Error('Käännösohjeet jäivät tyhjiksi.');
            if (textarea) {
                textarea.value = data.guidelines;
            }
            latestFinnishTranslationEstimate = null;
            if (status) {
                status.textContent = data.warnings
                    ? `Käännösprompti luotu. ${data.warnings}`
                    : `Käännösprompti luotu ${useModel ? 'mallilla' : 'analyysin perusteella'}.`;
            }
            if (hasTranslationAnalysis(project)) {
                await updateFinnishTranslationEstimate();
            }
            loadUsage();
        } catch (err) {
            if (status) status.textContent = err.message;
            alert('Käännöspromptin luonti epäonnistui: ' + networkFailureMessage(err));
        } finally {
            if (button) button.disabled = false;
            if (alternateButton) alternateButton.disabled = false;
        }
    }

    async function saveFinnishTranslationInstructions() {
        const project = currentFinnishTranslationProject();
        const textarea = document.getElementById('finnish-translation-instructions');
        const status = document.getElementById('finnish-translation-guidelines-status');
        const button = document.getElementById('finnish-translation-save-instructions-btn');
        const promptText = String(textarea?.value || '').trim();
        if (!project?.id) {
            alert('Valitse ensin käsikirjoitus.');
            return;
        }
        if (!promptText) {
            alert('Kirjoita tai luo ensin käännöspromptti.');
            return;
        }
        const analysis = project.analysis && typeof project.analysis === 'object' ? project.analysis : {};
        const savedAt = new Date().toISOString();
        const promptEntry = {
            prompt: promptText,
            saved_at: savedAt,
            source_language: finnishTranslationSourceLanguage(),
            target_language: finnishTranslationTargetLanguage(),
            style: document.getElementById('finnish-translation-style-select')?.value || '',
            model: document.getElementById('finnish-translation-model-select')?.value || '',
        };
        const existing = Array.isArray(analysis.translation_prompts) ? analysis.translation_prompts : [];
        const deduped = existing.filter(item => String(item?.prompt || '').trim() !== promptText);
        const payload = {
            analysis: {
                translation_prompt: promptText,
                translation_prompt_saved_at: savedAt,
                translation_prompt_meta: promptEntry,
                translation_prompts: [promptEntry, ...deduped].slice(0, 10),
            },
        };
        if (button) button.disabled = true;
        if (status) status.textContent = 'Tallennetaan käännösprompttia...';
        try {
            const res = await apiFetch(`/api/projects/${project.id}/metadata`, {
                method: 'PATCH',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify(payload)
            });
            const savedProject = await res.json();
            if (!res.ok) throw new Error(savedProject.detail || 'Käännöspromptin tallennus epäonnistui.');
            replaceAvailableProject(savedProject);
            loadedTranslationPromptProjectId = String(savedProject.id);
            latestFinnishTranslationEstimate = null;
            if (status) status.textContent = 'Käännöspromptti tallennettu.';
            await updateFinnishTranslationEstimate();
        } catch (err) {
            if (status) status.textContent = err.message;
            alert('Käännöspromptin tallennus epäonnistui: ' + networkFailureMessage(err));
        } finally {
            if (button) button.disabled = false;
        }
    }

    async function clearFinnishTranslationInstructions() {
        const textarea = document.getElementById('finnish-translation-instructions');
        const status = document.getElementById('finnish-translation-guidelines-status');
        if (!textarea) return;
        if (textarea.value.trim() && !confirm('Tyhjennetäänkö räätälöity käännösprompti?')) {
            return;
        }
        textarea.value = '';
        latestFinnishTranslationEstimate = null;
        if (status) status.textContent = 'Käännösprompti tyhjennetty.';
        const project = currentFinnishTranslationProject();
        if (project && hasTranslationAnalysis(project)) {
            await updateFinnishTranslationEstimate();
        }
    }

    async function updateTranslationEstimate() {
        const estimateEl = document.getElementById('translation-estimate');
        const payload = translationRequestPayload();
        updateTranslationChunkAdvice('translation');
        if (!estimateEl || !payload.project_id) {
            if (estimateEl) estimateEl.textContent = demoUiText('Valitse ensin käsikirjoitus.');
            latestTranslationEstimate = null;
            return;
        }
        const project = currentTranslationProject();
        if (!updateTranslationAnalysisNotice(project)) {
            estimateEl.textContent = translationAnalysisMessage();
            latestTranslationEstimate = null;
            return;
        }
        estimateEl.textContent = 'Lasketaan arviota...';
        try {
            const data = await fetchTranslationEstimate(payload);
            estimateEl.textContent = translationEstimateSummary(data, payload);
        } catch (err) {
            latestTranslationEstimate = null;
            estimateEl.textContent = err.message;
        }
    }

    async function updateFinnishTranslationEstimate() {
        const estimateEl = document.getElementById('finnish-translation-estimate');
        const payload = finnishTranslationRequestPayload();
        updateUnifiedTranslationLabels();
        updateTranslationChunkAdvice('finnish-translation');
        if (!estimateEl || !payload.project_id) {
            if (estimateEl) estimateEl.textContent = demoUiText('Valitse ensin käsikirjoitus.');
            latestFinnishTranslationEstimate = null;
            return;
        }
        const project = currentFinnishTranslationProject();
        if (!updateFinnishTranslationAnalysisNotice(project)) {
            estimateEl.textContent = finnishTranslationAnalysisMessage();
            latestFinnishTranslationEstimate = null;
            return;
        }
        estimateEl.textContent = 'Lasketaan käännöksen osia...';
        try {
            const data = await fetchFinnishTranslationEstimate(payload);
            estimateEl.textContent = translationEstimateSummary(data, payload, true);
        } catch (err) {
            latestFinnishTranslationEstimate = null;
            estimateEl.textContent = err.message;
        }
    }

    function translationHistoryCard(item, options = {}) {
        const isFinnish = options.isFinnish === true;
        const idAttr = isFinnish ? 'data-finnish-translation-id' : 'data-translation-id';
        const exportAttr = isFinnish ? 'data-finnish-translation-export-id' : 'data-translation-export-id';
        const deleteAttr = isFinnish ? 'data-finnish-translation-delete-id' : 'data-translation-delete-id';
        const label = item.target_language_label || (isFinnish ? 'Käännös' : item.target_language);
        return `
            <div class="translation-history-card" style="display:flex; align-items:center; gap:10px; flex-wrap:wrap; padding:10px 12px; border-radius:8px; border:1px solid var(--border-color); background:rgba(255,255,255,0.05);">
                <button class="translation-history-open" ${idAttr}="${item.id}" type="button" style="flex:1 1 240px; min-width:180px; text-align:left; border:0; background:transparent; color:var(--text-primary); cursor:pointer; padding:0;">
                    <strong>${escapeHtml(label)}</strong> · ${escapeHtml(item.style_label)} · ${item.chunks_count} osaa · ${escapeHtml(translationStatusLabel(item.status))}
                </button>
                <div style="display:flex; gap:8px; flex-wrap:wrap;">
                    <button class="btn btn-secondary" ${exportAttr}="${item.id}" type="button" style="padding:6px 10px; font-size:12px;">${escapeHtml(demoUiText('Vie käsikirjoitukseksi'))}</button>
                    <button class="btn btn-secondary btn-danger-soft" ${deleteAttr}="${item.id}" type="button" style="padding:6px 10px; font-size:12px;">Poista</button>
                </div>
            </div>
        `;
    }

    async function exportTranslationAsProject(translationId, options = {}) {
        const isFinnish = options.isFinnish === true;
        const status = document.getElementById(isFinnish ? 'finnish-translation-status' : 'translation-status');
        const label = 'Käännös';
        const genitiveLabel = 'Käännöksen';
        if (!translationId) return;
        try {
            if (status) status.textContent = demoUiText(`${label} viedään uudeksi käsikirjoitukseksi...`);
            const res = await apiFetch(`/api/translations/${translationId}/export-project`, { method: 'POST' });
            if (!res.ok) throw new Error(await apiErrorMessage(res, 'Käännöksen vienti epäonnistui.'));
            const project = await res.json();
            updateAvailableProject(project);
            setActiveManuscript(project);
            await loadProjects();
            if (status) status.textContent = demoUiText(`Uusi käsikirjoitus luotu: ${project.title || 'Nimetön'}.`);
            alert(demoUiText(`Uusi käsikirjoitus luotu: ${project.title || 'Nimetön'}`));
            return project;
        } catch (err) {
            if (status) status.textContent = err.message;
            alert(`${genitiveLabel} vienti epäonnistui: ${err.message}`);
            return null;
        }
    }

    async function deleteSavedTranslation(translationId, options = {}) {
        const isFinnish = options.isFinnish === true;
        const status = document.getElementById(isFinnish ? 'finnish-translation-status' : 'translation-status');
        const label = 'käännös';
        const genitiveLabel = 'Käännöksen';
        const partitiveLabel = 'käännöstä';
        if (!translationId) return;
        if (!confirm(`Poistetaanko tallennettu ${label}?`)) return;
        try {
            if (status) status.textContent = `Poistetaan tallennettua ${partitiveLabel}...`;
            const res = await apiFetch(`/api/translations/${translationId}`, { method: 'DELETE' });
            if (!res.ok) throw new Error(await apiErrorMessage(res, 'Käännöksen poisto epäonnistui.'));
            if (isFinnish) {
                if (selectedFinnishTranslation && String(selectedFinnishTranslation.id) === String(translationId)) {
                    selectedFinnishTranslation = null;
                    latestFinnishTranslationText = '';
                }
                currentFinnishTranslationHistory = currentFinnishTranslationHistory.filter(item => String(item.id) !== String(translationId));
                await renderFinnishTranslationHistory();
            } else {
                if (selectedTranslation && String(selectedTranslation.id) === String(translationId)) {
                    selectedTranslation = null;
                    latestTranslationText = '';
                }
                currentTranslationHistory = currentTranslationHistory.filter(item => String(item.id) !== String(translationId));
                await renderTranslationHistory();
            }
            if (status) status.textContent = `Tallennettu ${label} poistettu.`;
        } catch (err) {
            if (status) status.textContent = err.message;
            alert(`${genitiveLabel} poisto epäonnistui: ${err.message}`);
        }
    }

    async function renderTranslationHistory() {
        if (!isViewAllowed('view-kaannokset')) return;
        const history = document.getElementById('translation-history');
        const project = currentTranslationProject();
        if (!history) return;
        if (!project?.id) {
            currentTranslationHistory = [];
            selectedTranslation = null;
            populateTranslationReviewSelect();
            renderSelectedTranslationForReview();
            renderTranslationParts();
            history.innerHTML = '<div style="color:var(--text-secondary); font-size:13px;">Ei valittua käsikirjoitusta.</div>';
            return;
        }
        try {
            const res = await apiFetch(`/api/projects/${project.id}/translations`);
            if (!res.ok) throw new Error(await apiErrorMessage(res, 'Käännöshistorian lataus epäonnistui.'));
            const translations = await res.json();
            currentTranslationHistory = (translations || []).filter(item => item.target_language !== 'fi');
            if (selectedTranslation && !currentTranslationHistory.some(item => String(item.id) === String(selectedTranslation.id))) {
                selectedTranslation = null;
            }
            if (!selectedTranslation && currentTranslationHistory.length) {
                selectedTranslation = currentTranslationHistory[0];
            }
            populateTranslationReviewSelect();
            renderSelectedTranslationForReview();
            renderTranslationParts();
            if (!currentTranslationHistory.length) {
                history.innerHTML = '<div style="color:var(--text-secondary); font-size:13px;">Ei tallennettuja käännöksiä.</div>';
                return;
            }
            history.innerHTML = currentTranslationHistory.map(item => translationHistoryCard(item)).join('');
            history.querySelectorAll('[data-translation-id]').forEach(button => {
                button.addEventListener('click', () => {
                    const selected = currentTranslationHistory.find(item => String(item.id) === String(button.dataset.translationId));
                    if (!selected) return;
                    selectTranslationForReview(selected.id);
                    showTranslationPanel('translation-parts-panel');
                });
            });
            history.querySelectorAll('[data-translation-export-id]').forEach(button => {
                button.addEventListener('click', event => {
                    event.stopPropagation();
                    exportTranslationAsProject(button.dataset.translationExportId);
                });
            });
            history.querySelectorAll('[data-translation-delete-id]').forEach(button => {
                button.addEventListener('click', event => {
                    event.stopPropagation();
                    deleteSavedTranslation(button.dataset.translationDeleteId);
                });
            });
        } catch (err) {
            history.innerHTML = `<div style="color:#ffb4b4; font-size:13px;">${escapeHtml(err.message)}</div>`;
        }
    }

    async function renderFinnishTranslationHistory() {
        if (!isViewAllowed('view-kaannokset') && !isViewAllowed('view-kaannostyotila')) return;
        const history = document.getElementById('finnish-translation-history');
        const project = currentFinnishTranslationProject();
        if (!history) return;
        if (!project?.id) {
            currentFinnishTranslationHistory = [];
            selectedFinnishTranslation = null;
            translationWorkspaceFiles = [];
            loadedTranslationWorkspaceTranslationId = null;
            selectedTranslationWorkspaceFilePath = '';
            resetTranslationWorkspaceFileEditState();
            populateFinnishTranslationReviewSelect();
            populateTranslationWorkspaceTranslationSelect();
            renderSelectedFinnishTranslationForReview();
            renderFinnishTranslationParts();
            renderFinnishTranslationAiCheck();
            history.innerHTML = '<div style="color:var(--text-secondary); font-size:13px;">Ei valittua käsikirjoitusta.</div>';
            return;
        }
        try {
            const res = await apiFetch(`/api/projects/${project.id}/translations`);
            if (!res.ok) throw new Error(await apiErrorMessage(res, 'Käännöshistorian lataus epäonnistui.'));
            const translations = await res.json();
            currentFinnishTranslationHistory = translations || [];
            if (selectedFinnishTranslation && !currentFinnishTranslationHistory.some(item => String(item.id) === String(selectedFinnishTranslation.id))) {
                selectedFinnishTranslation = null;
            }
            if (!selectedFinnishTranslation && currentFinnishTranslationHistory.length) {
                selectedFinnishTranslation = currentFinnishTranslationHistory[0];
            }
            populateFinnishTranslationReviewSelect();
            renderSelectedFinnishTranslationForReview();
            renderFinnishTranslationParts();
            renderFinnishTranslationAiCheck();
            populateTranslationWorkspaceTranslationSelect();
            void resumeTranslationReviewBatchJob('finnish');
            if (!currentFinnishTranslationHistory.length) {
                history.innerHTML = '<div style="color:var(--text-secondary); font-size:13px;">Ei tallennettuja käännöksiä.</div>';
                return;
            }
            history.innerHTML = currentFinnishTranslationHistory.map(item => translationHistoryCard(item, { isFinnish: true })).join('');
            history.querySelectorAll('[data-finnish-translation-id]').forEach(button => {
                button.addEventListener('click', () => {
                    const selected = currentFinnishTranslationHistory.find(item => String(item.id) === String(button.dataset.finnishTranslationId));
                    if (!selected) return;
                    selectFinnishTranslationForReview(selected.id);
                    showFinnishTranslationPanel('suomentaja-ai-check-panel');
                });
            });
            history.querySelectorAll('[data-finnish-translation-export-id]').forEach(button => {
                button.addEventListener('click', event => {
                    event.stopPropagation();
                    exportTranslationAsProject(button.dataset.finnishTranslationExportId, { isFinnish: true });
                });
            });
            history.querySelectorAll('[data-finnish-translation-delete-id]').forEach(button => {
                button.addEventListener('click', event => {
                    event.stopPropagation();
                    deleteSavedTranslation(button.dataset.finnishTranslationDeleteId, { isFinnish: true });
                });
            });
        } catch (err) {
            history.innerHTML = `<div style="color:#ffb4b4; font-size:13px;">${escapeHtml(err.message)}</div>`;
        }
    }

    function translationWorkspaceVersionLabel(item) {
        if (!item) return 'Käännös';
        const date = item.created_at ? new Date(item.created_at).toLocaleString('fi-FI') : '';
        const language = item.target_language_label || item.target_language || 'Käännös';
        return `${language} · ${item.style_label || item.style || 'käännös'}${date ? ` · ${date}` : ''}`;
    }

    function populateTranslationWorkspaceTranslationSelect() {
        const select = document.getElementById('translation-workspace-file-translation-select');
        if (!select) {
            syncTranslationWorkspaceSavedDownloadButtons();
            return;
        }
        const previous = selectedFinnishTranslation?.id || select.value || '';
        select.innerHTML = '';
        if (!currentFinnishTranslationHistory.length) {
            select.innerHTML = '<option value="">Ei tallennettuja käännöksiä</option>';
            syncTranslationWorkspaceSavedDownloadButtons();
            return;
        }
        currentFinnishTranslationHistory.forEach(item => {
            const option = document.createElement('option');
            option.value = String(item.id);
            option.textContent = translationWorkspaceVersionLabel(item);
            select.appendChild(option);
        });
        if (previous && currentFinnishTranslationHistory.some(item => String(item.id) === String(previous))) {
            select.value = String(previous);
        } else {
            select.value = String(currentFinnishTranslationHistory[0].id);
        }
        syncTranslationWorkspaceSavedDownloadButtons();
    }

    function syncTranslationWorkspaceSavedDownloadButtons() {
        const select = document.getElementById('translation-workspace-file-translation-select');
        const selectedId = select?.value || selectedFinnishTranslation?.id || '';
        const hasSavedTranslation = currentFinnishTranslationHistory.some(
            item => String(item.id) === String(selectedId)
        );
        [
            'translation-workspace-files-download-translation-btn',
            'translation-workspace-files-download-metadata-btn'
        ].forEach(id => {
            const button = document.getElementById(id);
            if (button) {
                button.disabled = button.dataset.workspaceDownloadBusy === 'true' || !hasSavedTranslation;
            }
        });
    }

    function translationWorkspaceCategoryLabel(category) {
        return {
            project: 'Projekti',
            source: 'Lähde',
            analysis: 'Analyysi ja ohjeet',
            decisions: 'Päätökset',
            state: 'Tila',
            output: 'Tulostiedostot',
            segments: 'Segmentit'
        }[category] || category || 'Muut tiedostot';
    }

    function selectedTranslationWorkspaceFile() {
        return translationWorkspaceFiles.find(
            file => file.path === selectedTranslationWorkspaceFilePath
        ) || null;
    }

    function translationWorkspaceFileAffects(file) {
        if (!file) return new Set();
        const values = Array.isArray(file.affects)
            ? file.affects
            : (typeof file.affects === 'string' ? file.affects.split(',') : []);
        return new Set(values.map(value => String(value || '').trim().toLowerCase()).filter(Boolean));
    }

    function syncTranslationWorkspaceFileEditor() {
        const file = selectedTranslationWorkspaceFile();
        const content = document.getElementById('translation-workspace-file-content');
        const saveButton = document.getElementById('translation-workspace-file-save-btn');
        const rerunTranslationButton = document.getElementById('translation-workspace-file-rerun-translation-btn');
        const rerunReviewButton = document.getElementById('translation-workspace-file-rerun-review-btn');
        const editStatus = document.getElementById('translation-workspace-file-edit-status');
        const reviewSelect = document.getElementById('translation-workspace-review-select');
        const editable = file?.editable === true;
        const affects = translationWorkspaceFileAffects(file);
        const canRerun = editable
            && translationWorkspaceFileSavedForRerun
            && !translationWorkspaceFileDirty
            && !translationWorkspaceFileActionRunning;

        if (content) {
            content.readOnly = !editable || translationWorkspaceFileActionRunning;
            content.classList.toggle('is-editable', editable);
            content.classList.toggle('is-dirty', editable && translationWorkspaceFileDirty);
            content.setAttribute('aria-readonly', content.readOnly ? 'true' : 'false');
        }
        if (saveButton) {
            saveButton.classList.toggle('hidden', !editable);
            saveButton.disabled = !editable || !translationWorkspaceFileDirty || translationWorkspaceFileActionRunning;
        }
        if (rerunTranslationButton) {
            const visible = editable && affects.has('translation');
            rerunTranslationButton.classList.toggle('hidden', !visible);
            rerunTranslationButton.disabled = !visible || !canRerun;
        }
        if (rerunReviewButton) {
            const visible = editable && affects.has('review');
            rerunReviewButton.classList.toggle('hidden', !visible);
            rerunReviewButton.disabled = !visible || !canRerun;
        }
        if (reviewSelect) {
            reviewSelect.disabled = translationWorkspaceReviewRunning || translationWorkspaceFileActionRunning;
        }
        if (editStatus) {
            let message = translationWorkspaceFileEditMessage;
            if (!message) {
                if (!file) {
                    message = 'Valitse tiedosto vasemmalta.';
                } else if (!editable) {
                    message = 'Tiedosto on vain luettavissa.';
                } else if (translationWorkspaceFileDirty) {
                    message = 'Tiedostossa on tallentamattomia muutoksia.';
                } else {
                    message = 'Tiedostoa voi muokata käsin.';
                }
            }
            editStatus.textContent = message;
            editStatus.classList.toggle('is-error', translationWorkspaceFileEditError);
        }
    }

    function setTranslationWorkspaceFileEditStatus(message = '', isError = false) {
        translationWorkspaceFileEditMessage = message;
        translationWorkspaceFileEditError = isError;
        syncTranslationWorkspaceFileEditor();
    }

    function resetTranslationWorkspaceFileEditState(options = {}) {
        translationWorkspaceFileLoadedContent = options.content ?? '';
        translationWorkspaceFileDirty = false;
        translationWorkspaceFileSavedForRerun = options.savedForRerun === true;
        translationWorkspaceFileActionRunning = false;
        translationWorkspaceFileEditMessage = options.message || '';
        translationWorkspaceFileEditError = false;
        syncTranslationWorkspaceFileEditor();
    }

    function confirmDiscardTranslationWorkspaceFileChanges() {
        if (!translationWorkspaceFileDirty) return true;
        const fileName = selectedTranslationWorkspaceFilePath || 'valittu tiedosto';
        return window.confirm(
            `Tiedostossa ${fileName} on tallentamattomia muutoksia. Hylätäänkö muutokset?`
        );
    }

    function discardTranslationWorkspaceFileChanges() {
        translationWorkspaceFileDirty = false;
        translationWorkspaceFileSavedForRerun = false;
        translationWorkspaceFileEditMessage = '';
        translationWorkspaceFileEditError = false;
        syncTranslationWorkspaceFileEditor();
    }

    function renderTranslationWorkspaceFiles() {
        const list = document.getElementById('translation-workspace-file-list');
        const search = String(document.getElementById('translation-workspace-file-search')?.value || '').trim().toLowerCase();
        if (!list) return;
        const files = translationWorkspaceFiles.filter(file => {
            if (!search) return true;
            return `${file.path} ${file.label} ${file.group}`.toLowerCase().includes(search);
        });
        if (!files.length) {
            list.innerHTML = `<p class="card-meta">${translationWorkspaceFiles.length ? 'Hakua vastaavia tiedostoja ei löytynyt.' : 'Ei tiedostoja.'}</p>`;
            return;
        }

        const groups = new Map();
        files.forEach(file => {
            const key = file.category === 'segments' ? file.group : file.category;
            if (!groups.has(key)) {
                groups.set(key, {
                    key,
                    category: file.category,
                    label: file.category === 'segments'
                        ? file.group
                        : translationWorkspaceCategoryLabel(file.category),
                    files: []
                });
            }
            groups.get(key).files.push(file);
        });
        let groupIndex = 0;
        list.innerHTML = Array.from(groups.values()).map(group => {
            const containsSelected = group.files.some(file => file.path === selectedTranslationWorkspaceFilePath);
            const shouldOpen = containsSelected || groupIndex++ === 0;
            return `
                <details class="translation-workspace-file-group" ${shouldOpen ? 'open' : ''}>
                    <summary>${escapeHtml(group.label)} <span class="card-meta">(${group.files.length})</span></summary>
                    <div class="translation-workspace-file-buttons">
                        ${group.files.map(file => `
                            <button
                                class="translation-workspace-file-button ${file.path === selectedTranslationWorkspaceFilePath ? 'active' : ''}"
                                type="button"
                                data-translation-workspace-file-path="${escapeHtml(file.path)}"
                                title="${escapeHtml(file.path)}"
                            >${escapeHtml(file.label)}</button>
                        `).join('')}
                    </div>
                </details>
            `;
        }).join('');
        list.querySelectorAll('[data-translation-workspace-file-path]').forEach(button => {
            button.addEventListener('click', () => {
                openTranslationWorkspaceFile(button.dataset.translationWorkspaceFilePath);
            });
        });
    }

    async function openTranslationWorkspaceFile(path, options = {}) {
        const translationId = selectedFinnishTranslation?.id;
        const content = document.getElementById('translation-workspace-file-content');
        const pathLabel = document.getElementById('translation-workspace-file-path');
        const status = document.getElementById('translation-workspace-files-status');
        const downloadButton = document.getElementById('translation-workspace-file-download-btn');
        if (!translationId || !path || !content || translationWorkspaceFileActionRunning) return false;
        const loadSequence = ++translationWorkspaceFileLoadSequence;
        if (translationWorkspaceFileDirty && options.discardChanges !== true) {
            if (!confirmDiscardTranslationWorkspaceFileChanges()) {
                renderTranslationWorkspaceFiles();
                return false;
            }
        }
        discardTranslationWorkspaceFileChanges();
        selectedTranslationWorkspaceFilePath = path;
        renderTranslationWorkspaceFiles();
        if (pathLabel) pathLabel.textContent = path;
        if (downloadButton) downloadButton.disabled = true;
        content.value = 'Ladataan tiedostoa...';
        if (status) status.textContent = `Avataan ${path}.`;
        setTranslationWorkspaceFileEditStatus('Ladataan tiedostoa...');
        try {
            const query = new URLSearchParams({ path });
            const res = await apiFetch(`/api/translations/${translationId}/workspace-files/content?${query}`);
            if (!res.ok) throw new Error(await apiErrorMessage(res, 'Työtiedoston lataus epäonnistui.'));
            const loadedContent = await res.text();
            if (
                loadSequence !== translationWorkspaceFileLoadSequence
                || selectedTranslationWorkspaceFilePath !== path
                || String(selectedFinnishTranslation?.id || '') !== String(translationId)
            ) {
                return false;
            }
            content.value = loadedContent;
            const file = selectedTranslationWorkspaceFile();
            resetTranslationWorkspaceFileEditState({
                content: content.value,
                savedForRerun: file?.modified === true,
                message: file?.editable === true
                    ? (file?.modified === true
                        ? 'Tiedosto sisältää tallennettuja muutoksia. Voit muokata sitä tai ajaa työn uudelleen.'
                        : 'Tiedostoa voi muokata käsin. Tallenna muutokset ennen uudelleenajoa.')
                    : 'Tiedosto on vain luettavissa.'
            });
            if (downloadButton) downloadButton.disabled = false;
            if (status) status.textContent = `${path} · ${formatNumber(content.value.length)} merkkiä`;
            return true;
        } catch (err) {
            if (loadSequence !== translationWorkspaceFileLoadSequence) return false;
            content.value = '';
            if (status) status.textContent = err.message;
            resetTranslationWorkspaceFileEditState({ content: '' });
            setTranslationWorkspaceFileEditStatus(err.message, true);
            return false;
        }
    }

    async function loadTranslationWorkspaceFiles(force = false, options = {}) {
        const status = document.getElementById('translation-workspace-files-status');
        const content = document.getElementById('translation-workspace-file-content');
        const downloadAllButton = document.getElementById('translation-workspace-files-download-all-btn');
        if (force && translationWorkspaceFileDirty && options.discardChanges !== true) {
            if (!confirmDiscardTranslationWorkspaceFileChanges()) return false;
            discardTranslationWorkspaceFileChanges();
        }
        populateTranslationWorkspaceTranslationSelect();
        const select = document.getElementById('translation-workspace-file-translation-select');
        const selectedId = select?.value || selectedFinnishTranslation?.id || '';
        const selected = currentFinnishTranslationHistory.find(item => String(item.id) === String(selectedId));
        if (!selected) {
            translationWorkspaceFiles = [];
            loadedTranslationWorkspaceTranslationId = null;
            selectedTranslationWorkspaceFilePath = '';
            if (status) status.textContent = 'Luo tai valitse ensin tallennettu käännös.';
            if (content) content.value = 'Ei valittua käännöstä.';
            if (downloadAllButton) downloadAllButton.disabled = true;
            renderTranslationWorkspaceFiles();
            resetTranslationWorkspaceFileEditState({ message: 'Ei valittua käännöstä.' });
            return false;
        }
        if (!selectedFinnishTranslation || String(selectedFinnishTranslation.id) !== String(selected.id)) {
            if (!selectTranslationWorkspaceTranslation(selected.id, { discardChanges: options.discardChanges === true })) {
                return false;
            }
        }
        if (!force && String(loadedTranslationWorkspaceTranslationId) === String(selected.id) && translationWorkspaceFiles.length) {
            if (downloadAllButton) downloadAllButton.disabled = false;
            renderTranslationWorkspaceFiles();
            syncTranslationWorkspaceFileEditor();
            return true;
        }
        if (downloadAllButton) downloadAllButton.disabled = true;
        if (status) status.textContent = 'Muodostetaan työtilan tiedostoluetteloa...';
        if (content) content.value = 'Valitse tiedosto vasemmalta.';
        setTranslationWorkspaceFileEditStatus('Muodostetaan tiedostoluetteloa...');
        try {
            const res = await apiFetch(`/api/translations/${selected.id}/workspace-files`);
            if (!res.ok) throw new Error(await apiErrorMessage(res, 'Työtiedostojen lataus epäonnistui.'));
            translationWorkspaceFiles = await res.json();
            loadedTranslationWorkspaceTranslationId = selected.id;
            if (downloadAllButton) downloadAllButton.disabled = !translationWorkspaceFiles.length;
            if (!translationWorkspaceFiles.some(file => file.path === selectedTranslationWorkspaceFilePath)) {
                selectedTranslationWorkspaceFilePath = translationWorkspaceFiles.find(file => file.path === 'project.json')?.path
                    || translationWorkspaceFiles[0]?.path
                    || '';
            }
            renderTranslationWorkspaceFiles();
            if (status) {
                status.textContent = `${translationWorkspaceVersionLabel(selected)} · ${translationWorkspaceFiles.length} tiedostoa`;
            }
            if (selectedTranslationWorkspaceFilePath) {
                await openTranslationWorkspaceFile(selectedTranslationWorkspaceFilePath, { discardChanges: true });
            }
            return true;
        } catch (err) {
            translationWorkspaceFiles = [];
            loadedTranslationWorkspaceTranslationId = null;
            if (downloadAllButton) downloadAllButton.disabled = true;
            renderTranslationWorkspaceFiles();
            if (status) status.textContent = err.message;
            resetTranslationWorkspaceFileEditState();
            setTranslationWorkspaceFileEditStatus(err.message, true);
            return false;
        }
    }

    async function saveTranslationWorkspaceFile() {
        const translationId = selectedFinnishTranslation?.id;
        const path = selectedTranslationWorkspaceFilePath;
        const file = selectedTranslationWorkspaceFile();
        const content = document.getElementById('translation-workspace-file-content');
        const status = document.getElementById('translation-workspace-files-status');
        if (!translationId || !path || !content || file?.editable !== true) return false;
        if (!translationWorkspaceFileDirty) return true;

        translationWorkspaceFileActionRunning = true;
        setTranslationWorkspaceFileEditStatus('Tallennetaan tiedostoa...');
        try {
            const query = new URLSearchParams({ path });
            const res = await apiFetch(`/api/translations/${translationId}/workspace-files/content?${query}`, {
                method: 'PUT',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ content: content.value })
            });
            if (!res.ok) throw new Error(await apiErrorMessage(res, 'Työtiedoston tallennus epäonnistui.'));
            const saved = await res.json().catch(() => null);
            if (typeof saved?.content === 'string') content.value = saved.content;
            translationWorkspaceFileLoadedContent = content.value;
            translationWorkspaceFileDirty = false;
            translationWorkspaceFileSavedForRerun = true;
            file.size_chars = content.value.length;
            file.modified = true;
            if (status) status.textContent = `${path} · ${formatNumber(content.value.length)} merkkiä · tallennettu`;
            setTranslationWorkspaceFileEditStatus('Muutokset tallennettiin. Voit nyt ajaa tiedostoon liittyvän työn uudelleen.');
            return true;
        } catch (err) {
            if (status) status.textContent = err.message;
            setTranslationWorkspaceFileEditStatus(err.message, true);
            return false;
        } finally {
            translationWorkspaceFileActionRunning = false;
            syncTranslationWorkspaceFileEditor();
        }
    }

    async function rerunTranslationWorkspaceFromFile() {
        const translationId = selectedFinnishTranslation?.id;
        const file = selectedTranslationWorkspaceFile();
        if (!translationId || file?.editable !== true || !translationWorkspaceFileAffects(file).has('translation')) {
            return;
        }
        if (translationWorkspaceFileDirty && !(await saveTranslationWorkspaceFile())) return;

        translationWorkspaceFileActionRunning = true;
        setTranslationWorkspaceFileEditStatus('Käynnistetään käännös uudelleen...');
        showTranslationWorkspacePanel('translation-workspace-translate-panel');
        setTranslationWorkspaceProgress(0, 'Valmistellaan uutta käännöstä', 'Käynnistetään käännös tallennetuilla aputiedostoilla.');
        try {
            const startRes = await apiFetch(`/api/translations/${translationId}/rerun`, {
                method: 'POST'
            });
            const started = await startRes.json().catch(() => null);
            if (!startRes.ok) throw new Error(demoPriceSafeText(
                started?.detail || 'Käännöksen uudelleenajo ei käynnistynyt.',
                'Käännöksen uudelleenajo ei käynnistynyt.'
            ));
            if (!started?.job_id) throw new Error('Käännöksen uudelleenajo ei palauttanut työn tunnistetta.');

            while (true) {
                const statusRes = await apiFetch(`/api/translations/jobs/${started.job_id}`);
                const job = await statusRes.json().catch(() => null);
                if (!statusRes.ok) throw new Error(demoPriceSafeText(
                    job?.detail || 'Käännöstyön tilaa ei saatu.',
                    'Käännöstyön tilaa ei saatu.'
                ));
                const done = Number(job?.done_chunks || 0);
                const total = Number(job?.total_chunks || 0);
                const percent = total ? done / total * 100 : 0;
                setTranslationWorkspaceProgress(
                    percent,
                    'Käännös käynnissä',
                    total
                        ? `Valmiina ${Math.min(done, total)}/${total} segmenttiä.`
                        : demoPriceSafeText(job?.message || 'Käännös käynnissä.', 'Käännös käynnissä.')
                );
                if (['done', 'completed', 'partial'].includes(job?.status) && job?.translation_id) {
                    const data = await fetchSavedTranslation(job.translation_id);
                    selectedFinnishTranslation = data;
                    setTranslationWorkspaceProgress(
                        100,
                        data.status === 'partial' ? 'Käännös valmistui osittain' : 'Käännös valmis',
                        demoPriceSafeText(data.warnings, 'Käännöstyössä on huomautuksia.')
                            || `${data.chunks_count} segmenttiä tallennettiin projektiin.`
                    );
                    translationWorkspaceFileSavedForRerun = false;
                    await loadTranslationWorkspaceHistory(data.id);
                    loadUsage();
                    return;
                }
                if (['failed', 'error'].includes(job?.status)) {
                    throw new Error(demoPriceSafeText(
                        job?.error || job?.message || 'Käännöstyö epäonnistui.',
                        'Käännöstyö epäonnistui.'
                    ));
                }
                await wait(2500);
            }
        } catch (err) {
            const message = networkFailureMessage(err);
            setTranslationWorkspaceProgress(0, 'Käännös keskeytyi', message);
            setTranslationWorkspaceFileEditStatus(message, true);
            alert('Käännöksen uudelleenajo epäonnistui: ' + message);
            loadUsage();
        } finally {
            translationWorkspaceFileActionRunning = false;
            syncTranslationWorkspaceFileEditor();
        }
    }

    async function rerunTranslationWorkspaceReviewFromFile() {
        const translationId = selectedFinnishTranslation?.id;
        const file = selectedTranslationWorkspaceFile();
        if (!translationId || file?.editable !== true || !translationWorkspaceFileAffects(file).has('review')) {
            return;
        }
        if (translationWorkspaceFileDirty && !(await saveTranslationWorkspaceFile())) return;

        translationWorkspaceFileActionRunning = true;
        setTranslationWorkspaceFileEditStatus('Käynnistetään tarkastus uudelleen...');
        selectTranslationWorkspaceTranslation(translationId);
        showTranslationWorkspacePanel('translation-workspace-review-panel');
        try {
            await checkAllTranslationWorkspaceSegments({ force: true });
            setTranslationWorkspaceFileEditStatus('Tarkastusajo valmistui.');
        } finally {
            translationWorkspaceFileActionRunning = false;
            syncTranslationWorkspaceFileEditor();
        }
    }

    function translationWorkspaceSavedDownloadFileName(translationId, kind) {
        const project = currentTranslationWorkspaceProject();
        const item = currentFinnishTranslationHistory.find(
            entry => String(entry.id) === String(translationId)
        );
        const safeTitle = String(project?.title || 'kaannos')
            .toLowerCase()
            .replace(/[^a-z0-9åäö]+/gi, '-')
            .replace(/^-+|-+$/g, '') || 'kaannos';
        const language = String(item?.target_language || 'translation')
            .toLowerCase()
            .replace(/[^a-z0-9_-]+/g, '') || 'translation';
        const version = String(translationId || '').replace(/[^0-9]+/g, '') || 'saved';
        return kind === 'metadata'
            ? `${safeTitle}-${language}-kaannos-${version}-metadata.json`
            : `${safeTitle}-${language}-kaannos-${version}.txt`;
    }

    async function downloadTranslationWorkspacePath(translationId, path, options = {}) {
        const status = document.getElementById(options.statusId || 'translation-workspace-files-status');
        const button = options.button || null;
        if (!translationId || !path) return false;
        const originalLabel = button?.textContent || '';
        if (button) {
            button.dataset.workspaceDownloadBusy = 'true';
            button.disabled = true;
            button.textContent = options.pendingLabel || 'Ladataan…';
        }
        if (status && options.pendingMessage) status.textContent = options.pendingMessage;
        try {
            const query = new URLSearchParams({ path, download: 'true' });
            const res = await apiFetch(`/api/translations/${translationId}/workspace-files/content?${query}`);
            if (!res.ok) throw new Error(await apiErrorMessage(res, options.errorMessage || 'Työtiedoston lataus epäonnistui.'));
            const blob = await res.blob();
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = options.fileName || path.split('/').pop() || 'translation-file.txt';
            document.body.appendChild(link);
            link.click();
            link.remove();
            URL.revokeObjectURL(url);
            if (status) status.textContent = options.successMessage || `${path} ladattu.`;
            return true;
        } catch (err) {
            if (status) status.textContent = err.message;
            return false;
        } finally {
            if (button) {
                delete button.dataset.workspaceDownloadBusy;
                button.textContent = originalLabel;
                button.disabled = false;
            }
            syncTranslationWorkspaceSavedDownloadButtons();
        }
    }

    async function downloadTranslationWorkspaceSavedFile(translationId, kind, options = {}) {
        const config = translationWorkspaceSavedDownloads[kind];
        if (!config) return false;
        return downloadTranslationWorkspacePath(translationId, config.path, {
            ...options,
            fileName: translationWorkspaceSavedDownloadFileName(translationId, kind),
            pendingLabel: 'Ladataan…',
            pendingMessage: config.pending,
            successMessage: config.success,
            errorMessage: config.error
        });
    }

    async function downloadTranslationWorkspaceFile() {
        return downloadTranslationWorkspacePath(
            selectedFinnishTranslation?.id,
            selectedTranslationWorkspaceFilePath,
            { statusId: 'translation-workspace-files-status' }
        );
    }

    async function downloadTranslationWorkspaceArchive() {
        const translationId = selectedFinnishTranslation?.id;
        const button = document.getElementById('translation-workspace-files-download-all-btn');
        const status = document.getElementById('translation-workspace-files-status');
        if (!translationId || !translationWorkspaceFiles.length) return;
        if (translationWorkspaceFileDirty && !(await saveTranslationWorkspaceFile())) return;

        const originalLabel = button?.textContent || 'Lataa kaikki ZIP';
        if (button) {
            button.disabled = true;
            button.textContent = 'Muodostetaan ZIP…';
        }
        if (status) status.textContent = 'Pakataan kaikki työtilan tiedostot...';
        try {
            const res = await apiFetch(`/api/translations/${translationId}/workspace-files/archive`);
            if (!res.ok) throw new Error(await apiErrorMessage(res, 'ZIP-paketin lataus epäonnistui.'));
            const blob = await res.blob();
            const disposition = res.headers.get('content-disposition') || '';
            const fileNameMatch = disposition.match(/filename="?([^";]+)"?/i);
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = fileNameMatch?.[1] || 'kaannostyotila.zip';
            document.body.appendChild(link);
            link.click();
            link.remove();
            URL.revokeObjectURL(url);
            if (status) status.textContent = `${translationWorkspaceFiles.length} tiedostoa ladattu ZIP-pakettina.`;
        } catch (err) {
            if (status) status.textContent = err.message;
        } finally {
            if (button) {
                button.textContent = originalLabel;
                button.disabled = (
                    !selectedFinnishTranslation?.id
                    || !translationWorkspaceFiles.length
                    || String(selectedFinnishTranslation.id) !== String(translationId)
                );
            }
        }
    }

    async function downloadReviewedTranslationExport(format = 'reviewed', workspace = false) {
        const item = selectedFinnishTranslation;
        const status = document.getElementById(
            workspace ? 'translation-workspace-review-status' : 'finnish-translation-ai-check-status'
        );
        if (!item?.id) {
            alert('Valitse ensin tarkastettu käännös.');
            return;
        }
        if (status) status.textContent = format === 'bilingual'
            ? 'Muodostetaan tarkastettua bilingual-tiedostoa...'
            : 'Muodostetaan tarkastettua kirjaa...';
        try {
            const query = new URLSearchParams({ format });
            const res = await apiFetch(`/api/translations/${item.id}/review-export?${query}`);
            if (!res.ok) throw new Error(await apiErrorMessage(res, 'Tarkastetun käännöksen lataus epäonnistui.'));
            const blob = await res.blob();
            const disposition = res.headers.get('content-disposition') || '';
            const fileNameMatch = disposition.match(/filename="?([^";]+)"?/i);
            const fallbackName = format === 'bilingual'
                ? 'tarkastettu-bilingual.md'
                : 'tarkastettu-kaannos.md';
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = fileNameMatch?.[1] || fallbackName;
            document.body.appendChild(link);
            link.click();
            link.remove();
            URL.revokeObjectURL(url);
            if (status) status.textContent = format === 'bilingual'
                ? 'Tarkastettu bilingual-tiedosto ladattu.'
                : 'Tarkastettu kirja ladattu.';
        } catch (err) {
            if (status) status.textContent = err.message;
        }
    }

    function populateTranslationReviewSelect() {
        const select = document.getElementById('translation-review-select');
        if (!select) return;
        select.innerHTML = '';
        currentTranslationHistory.forEach(item => {
            const option = document.createElement('option');
            option.value = item.id;
            option.textContent = `${item.target_language_label} · ${item.style_label} · ${translationStatusLabel(item.status)}`;
            select.appendChild(option);
        });
        if (selectedTranslation) select.value = String(selectedTranslation.id);
    }

    function populateFinnishTranslationReviewSelect() {
        const select = document.getElementById('finnish-translation-review-select');
        if (!select) return;
        select.innerHTML = '';
        currentFinnishTranslationHistory.forEach(item => {
            const option = document.createElement('option');
            option.value = item.id;
            option.textContent = `${item.target_language_label || item.target_language || 'Käännös'} · ${item.style_label} · ${translationStatusLabel(item.status)}`;
            select.appendChild(option);
        });
        if (selectedFinnishTranslation) select.value = String(selectedFinnishTranslation.id);
    }

    function translationChunkDetails(item) {
        return Array.isArray(item?.chunk_details) ? item.chunk_details : [];
    }

    function updateFinnishTranslationAiCheckChunk(index, data, translation = selectedFinnishTranslation) {
        const chunks = translationChunkDetails(translation);
        if (!chunks[index]) return;
        chunks[index].ai_check = {
            checked_translation: data.checked_translation || '',
            notes: data.notes || '',
            model: data.model || '',
            checked_at: new Date().toISOString()
        };
        translation.chunk_details = chunks;
        if (String(selectedFinnishTranslation?.id) === String(translation.id)) {
            selectedFinnishTranslation = translation;
        }
        loadedTranslationWorkspaceTranslationId = null;
        const itemIndex = currentFinnishTranslationHistory.findIndex(
            historyItem => String(historyItem.id) === String(translation.id)
        );
        if (itemIndex >= 0) currentFinnishTranslationHistory[itemIndex] = translation;
    }

    function finnishTranslationAiCheckedText(chunk) {
        const aiCheck = chunk?.ai_check && typeof chunk.ai_check === 'object' ? chunk.ai_check : {};
        return String(aiCheck.checked_translation || '').trim();
    }

    function normalizeTranslationReviewText(value) {
        return String(value || '').replace(/\r\n?/g, '\n').trim();
    }

    function translationReviewSuggestionState(chunk) {
        const checked = normalizeTranslationReviewText(finnishTranslationAiCheckedText(chunk));
        if (!checked) return 'unchecked';
        const current = normalizeTranslationReviewText(chunk?.translation);
        return checked === current ? 'unchanged' : 'pending';
    }

    function translationReviewSummaryModel(chunks) {
        const safeChunks = Array.isArray(chunks) ? chunks : [];
        const entries = safeChunks.map((chunk, index) => ({
            chunk,
            index,
            state: translationReviewSuggestionState(chunk)
        }));
        const checked = entries.filter(entry => entry.state !== 'unchecked').length;
        const suggestions = entries.filter(entry => entry.state === 'pending');
        return {
            total: entries.length,
            checked,
            unchecked: entries.length - checked,
            unchanged: checked - suggestions.length,
            suggestions
        };
    }

    function renderTranslationReviewSummary(containerId, chunks, selectedIndex, onSelect) {
        const container = document.getElementById(containerId);
        if (!container) return;
        const summary = translationReviewSummaryModel(chunks);
        if (!summary.total) {
            container.hidden = true;
            container.innerHTML = '';
            return;
        }

        container.hidden = false;
        const progressText = summary.checked === 0
            ? 'Yhteenveto täyttyy, kun tarkastat yhden tai useamman segmentin.'
            : summary.suggestions.length
                ? `AI ehdottaa muutosta ${summary.suggestions.length} segmenttiin. Avaa ehdotus siirtyäksesi suoraan kyseiseen kohtaan.`
                : summary.unchecked
                    ? 'Tarkastetuissa segmenteissä ei ole avoimia korjausehdotuksia. Jatka vielä tarkastamattomiin segmentteihin.'
                    : 'Koko käännös on tarkastettu eikä nykyiseen tekstiin ole avoimia korjausehdotuksia.';
        const suggestionMarkup = summary.suggestions.length
            ? `
                <div class="translation-review-summary-list">
                    ${summary.suggestions.map(entry => {
                        const label = translationPartLabel(entry.chunk, entry.index);
                        const aiCheck = workspaceChunkCheck(entry.chunk);
                        const notes = String(aiCheck.notes || '').trim() || 'Tarkastettu teksti poikkeaa nykyisestä käännöksestä.';
                        return `
                            <button
                                type="button"
                                class="translation-review-summary-item ${entry.index === selectedIndex ? 'active' : ''}"
                                data-translation-review-summary-index="${entry.index}"
                                ${entry.index === selectedIndex ? 'aria-current="true"' : ''}
                            >
                                <span class="translation-review-summary-item-head">
                                    <strong>${escapeHtml(label.title)}</strong>
                                    <span>Korjausehdotus</span>
                                </span>
                                <span class="translation-review-summary-item-meta">${escapeHtml(label.meta)}</span>
                                <span class="translation-review-summary-item-notes">${escapeHtml(notes)}</span>
                            </button>
                        `;
                    }).join('')}
                </div>
            `
            : `
                <div class="translation-review-summary-empty">
                    ${summary.checked
                        ? 'Ei avoimia korjausehdotuksia tarkastetuissa segmenteissä.'
                        : 'Ei korjausehdotuksia ennen ensimmäistä tarkastusta.'}
                </div>
            `;

        container.innerHTML = `
            <div class="translation-review-summary-head">
                <div>
                    <span class="translation-review-summary-eyebrow">KOKONAISKUVA</span>
                    <h3>Korjausehdotusten yhteenveto</h3>
                    <p>${escapeHtml(progressText)}</p>
                </div>
                <div class="translation-review-summary-stats" aria-label="Tarkastuksen tilanne">
                    <span><strong>${summary.checked}/${summary.total}</strong>Tarkastettu</span>
                    <span><strong>${summary.suggestions.length}</strong>Muutosta ehdottavia</span>
                    <span><strong>${summary.unchanged}</strong>Ei muutosta</span>
                    <span><strong>${summary.unchecked}</strong>Tarkastamatta</span>
                </div>
            </div>
            ${suggestionMarkup}
        `;
        container.querySelectorAll('[data-translation-review-summary-index]').forEach(button => {
            button.addEventListener('click', () => {
                const index = Number(button.dataset.translationReviewSummaryIndex);
                if (Number.isInteger(index) && typeof onSelect === 'function') onSelect(index);
            });
        });
    }

    function translationPartLabel(chunk, fallbackIndex) {
        const index = Number(chunk?.index || fallbackIndex + 1);
        const total = Number(chunk?.total || 0);
        const words = Number(chunk?.source_word_count || 0);
        const status = chunk?.status && chunk.status !== 'completed' ? ` · ${chunk.status}` : '';
        const location = chunk?.book_location && typeof chunk.book_location === 'object' ? chunk.book_location : {};
        const primary = location.primary_chapter && typeof location.primary_chapter === 'object' ? location.primary_chapter : {};
        const chapterLabel = location.chapter_span || primary.title || primary.id || '';
        const locationLabel = chapterLabel ? ` · ${chapterLabel}` : '';
        return {
            title: total ? `Osa ${index}/${total}` : `Osa ${index}`,
            meta: `${words ? `${formatNumber(words)} sanaa` : 'Ei sanamäärää'}${locationLabel}${status}`
        };
    }

    function translationPartModelValue(chunk, item) {
        return chunk?.model
            || (chunk?.model_provider && chunk?.model_name ? `${chunk.model_provider}:${chunk.model_name}` : '')
            || item?.model
            || '';
    }

    function translationModelLabel(value) {
        if (!value) return 'Ei mallia tiedossa';
        const model = translationModels.find(item => `${item.provider}:${item.model_name}` === value);
        return model ? `${model.display_name || model.model_name}${model.model_tier === 'pro' ? ' · pro' : ''}` : value;
    }

    function populateTranslationPartModelSelect(prefix, chunk, item) {
        const select = document.getElementById(`${prefix}-part-rerun-model`);
        const used = document.getElementById(`${prefix}-part-model-used`);
        const button = document.getElementById(`${prefix}-part-rerun-btn`);
        const modelValue = translationPartModelValue(chunk, item);
        if (used) used.textContent = translationModelLabel(modelValue);
        if (!select) return;
        select.innerHTML = '';
        translationModels.forEach(model => {
            const option = document.createElement('option');
            option.value = `${model.provider}:${model.model_name}`;
            option.textContent = `${model.display_name || model.model_name}${model.model_tier === 'pro' ? ' · pro' : ''}`;
            select.appendChild(option);
        });
        if (modelValue && translationModels.some(model => `${model.provider}:${model.model_name}` === modelValue)) {
            select.value = modelValue;
        } else if (translationModels.length) {
            const defaultModel = translationModels.find(model => model.is_default) || translationModels[0];
            select.value = `${defaultModel.provider}:${defaultModel.model_name}`;
        }
        if (button) button.disabled = !chunk || !translationModels.length;
    }

    function stripPromptSectionLabel(value, labels) {
        const text = String(value || '').trim();
        if (!text) return '';
        const pattern = new RegExp(`^(${labels.map(label => label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|')})\\s*:?\\s*\\n+`, 'i');
        return text.replace(pattern, '').trim();
    }

    function translationPartSections(chunk) {
        const sections = chunk?.prompt_sections && typeof chunk.prompt_sections === 'object'
            ? chunk.prompt_sections
            : {};
        const contextFallback = [
            chunk?.pre_context ? `EDELTÄVÄ KONTEKSTI:\n${chunk.pre_context}` : '',
            chunk?.post_context ? `SEURAAVA KONTEKSTI:\n${chunk.post_context}` : ''
        ].filter(Boolean).join('\n\n');
        return {
            instructions: sections.instructions || '',
            analysis: sections.analysis_context || '',
            context: sections.context || contextFallback,
            source: stripPromptSectionLabel(sections.source_text || chunk?.source_text || '', ['KÄÄNNETTÄVÄ TEKSTI']),
            prompt: chunk?.prompt || '',
            response: chunk?.translation || chunk?.response || ''
        };
    }

    function setTranslationPartText(prefix, key, value) {
        const element = document.getElementById(`${prefix}-part-${key}`);
        if (!element) return;
        if ('value' in element) {
            element.value = value || 'Ei tietoa.';
        } else {
            element.textContent = value || 'Ei tietoa.';
        }
    }

    function syncTranslationPartScrollPosition(from, to) {
        if (!from || !to || from.dataset.scrollSyncing === 'true' || to.dataset.scrollSyncing === 'true') return;
        const fromMax = from.scrollHeight - from.clientHeight;
        const toMax = to.scrollHeight - to.clientHeight;
        if (fromMax <= 0 || toMax <= 0) return;
        const ratio = from.scrollTop / fromMax;
        from.dataset.scrollSyncing = 'true';
        to.dataset.scrollSyncing = 'true';
        to.scrollTop = ratio * toMax;
        requestAnimationFrame(() => {
            from.dataset.scrollSyncing = 'false';
            to.dataset.scrollSyncing = 'false';
        });
    }

    function bindTranslationPartScrollSync(prefix, reset = false) {
        const source = document.getElementById(`${prefix}-part-source`);
        const response = document.getElementById(`${prefix}-part-response`);
        if (!source || !response) return;
        if (reset) {
            source.scrollTop = 0;
            response.scrollTop = 0;
        }
        const syncKey = `${source.id}:${response.id}`;
        if (source.dataset.translationScrollSync === syncKey && response.dataset.translationScrollSync === syncKey) return;
        source.dataset.translationScrollSync = syncKey;
        response.dataset.translationScrollSync = syncKey;
        source.addEventListener('scroll', () => syncTranslationPartScrollPosition(source, response));
        response.addEventListener('scroll', () => syncTranslationPartScrollPosition(response, source));
    }

    function translationReviewElements(prefix) {
        const isFinnish = prefix === 'finnish-translation';
        return {
            original: document.getElementById(isFinnish ? 'finnish-translation-review-original' : 'translation-review-original'),
            chunks: document.getElementById(isFinnish ? 'finnish-translation-review-chunks' : 'translation-review-chunks'),
            hidden: document.getElementById(isFinnish ? 'finnish-translation-review-text' : 'translation-review-text'),
        };
    }

    function translationReviewChunkValues(prefix) {
        const { chunks } = translationReviewElements(prefix);
        if (!chunks) return [];
        const sections = Array.from(chunks.querySelectorAll('[data-translation-review-chunk-section]'));
        if (sections.length) {
            return sections.map(section => {
                const paragraphs = Array.from(section.querySelectorAll('[data-translation-review-paragraph]'));
                if (paragraphs.length) {
                    return paragraphs.map(input => input.value.trim()).join('\n\n').trim();
                }
                const chunkInput = section.querySelector('[data-translation-review-chunk]');
                return chunkInput ? chunkInput.value : '';
            });
        }
        return Array.from(chunks.querySelectorAll('[data-translation-review-chunk]')).map(input => input.value);
    }

    function syncTranslationReviewText(prefix) {
        const { hidden } = translationReviewElements(prefix);
        if (!hidden) return '';
        const values = translationReviewChunkValues(prefix);
        const text = values.length ? values.map(value => value.trim()).filter(Boolean).join('\n\n') : hidden.value;
        hidden.value = text;
        if (prefix === 'finnish-translation') {
            latestFinnishTranslationText = text;
        } else {
            latestTranslationText = text;
        }
        return text;
    }

    function translationReviewTextValue(prefix) {
        const { hidden } = translationReviewElements(prefix);
        return syncTranslationReviewText(prefix) || hidden?.value || '';
    }

    function translationReviewBlockLabel(chunk, fallbackIndex) {
        const label = translationPartLabel(chunk || {}, fallbackIndex);
        return `${label.title}${label.meta ? ` · ${label.meta}` : ''}`;
    }

    function splitTranslationReviewParagraphs(value) {
        return String(value || '').split(/\n\s*\n/).map(part => part.trim()).filter(Boolean);
    }

    function sourceParagraphsForReview(chunk) {
        if (Array.isArray(chunk?.source_paragraphs) && chunk.source_paragraphs.length) {
            return chunk.source_paragraphs
                .map(item => String(item?.text || '').trim())
                .filter(Boolean);
        }
        return splitTranslationReviewParagraphs(chunk?.source_text || '');
    }

    function renderReviewSourceBody(chunk) {
        const paragraphs = sourceParagraphsForReview(chunk);
        if (paragraphs.length <= 1) {
            return `<div class="translation-review-chunk-body">${escapeHtml(paragraphs[0] || chunk?.source_text || '')}</div>`;
        }
        return `
            <div class="translation-review-paragraph-list">
                ${paragraphs.map((paragraph, index) => `
                    <div class="translation-review-chunk-body" style="margin-bottom:10px;">
                        <strong>Kappale ${index + 1}</strong><br>
                        ${escapeHtml(paragraph)}
                    </div>
                `).join('')}
            </div>
        `;
    }

    function renderReviewTranslationBody(chunk, index) {
        const sourceParagraphs = sourceParagraphsForReview(chunk);
        const translatedParagraphs = splitTranslationReviewParagraphs(chunk?.translation || '');
        if (sourceParagraphs.length > 1 && sourceParagraphs.length === translatedParagraphs.length) {
            return `
                <div class="translation-review-paragraph-list">
                    ${translatedParagraphs.map((paragraph, paragraphIndex) => `
                        <label class="card-meta" style="display:block; margin-bottom:4px;">Kappale ${paragraphIndex + 1}</label>
                        <textarea class="translation-review-chunk-text" data-translation-review-paragraph="${paragraphIndex}" style="margin-bottom:10px;">${escapeHtml(paragraph)}</textarea>
                    `).join('')}
                </div>
            `;
        }
        return `<textarea class="translation-review-chunk-text" data-translation-review-chunk="${index}">${escapeHtml(chunk?.translation || '')}</textarea>`;
    }

    function renderAlignedTranslationReview(prefix, project, item, emptyMessage) {
        const { original, chunks, hidden } = translationReviewElements(prefix);
        if (!original || !chunks || !hidden) return;
        const sourceText = project ? projectTextForTranslation(project) : '';
        const translatedText = item?.translated_text || '';
        hidden.value = translatedText;

        if (!project || !item) {
            original.textContent = emptyMessage;
            chunks.textContent = emptyMessage;
            return;
        }

        const details = translationChunkDetails(item);
        if (!details.length) {
            original.innerHTML = `
                <section class="translation-review-chunk">
                    <h5>Alkuperäinen teksti</h5>
                    <div class="translation-review-chunk-body">${escapeHtml(sourceText || 'Alkuperäistä tekstiä ei ole.')}</div>
                </section>
            `;
            chunks.innerHTML = `
                <section class="translation-review-chunk">
                    <h5>Käännös</h5>
                    <textarea class="translation-review-chunk-text" data-translation-review-chunk="0">${escapeHtml(translatedText)}</textarea>
                </section>
            `;
            chunks.querySelector('[data-translation-review-chunk]')?.addEventListener('input', () => syncTranslationReviewText(prefix));
            syncTranslationReviewText(prefix);
            return;
        }

        original.innerHTML = details.map((chunk, index) => `
            <section class="translation-review-chunk">
                <h5>${escapeHtml(translationReviewBlockLabel(chunk, index))}</h5>
                ${renderReviewSourceBody(chunk)}
            </section>
        `).join('');
        chunks.innerHTML = details.map((chunk, index) => `
            <section class="translation-review-chunk" data-translation-review-chunk-section="${index}">
                <h5>${escapeHtml(translationReviewBlockLabel(chunk, index))}</h5>
                ${renderReviewTranslationBody(chunk, index)}
            </section>
        `).join('');
        chunks.querySelectorAll('[data-translation-review-chunk], [data-translation-review-paragraph]').forEach(input => {
            input.addEventListener('input', () => syncTranslationReviewText(prefix));
        });
        syncTranslationReviewText(prefix);
    }

    function renderTranslationPartDetail(prefix, chunk, emptyMessage) {
        const item = prefix === 'finnish-translation' ? selectedFinnishTranslation : selectedTranslation;
        if (!chunk) {
            ['instructions', 'analysis', 'context', 'source', 'prompt', 'response'].forEach(key => {
                setTranslationPartText(prefix, key, emptyMessage);
            });
            populateTranslationPartModelSelect(prefix, null, item);
            bindTranslationPartScrollSync(prefix, true);
            return;
        }
        const sections = translationPartSections(chunk);
        setTranslationPartText(prefix, 'instructions', sections.instructions);
        setTranslationPartText(prefix, 'analysis', sections.analysis);
        setTranslationPartText(prefix, 'context', sections.context);
        setTranslationPartText(prefix, 'source', sections.source);
        setTranslationPartText(prefix, 'prompt', sections.prompt);
        setTranslationPartText(prefix, 'response', sections.response);
        populateTranslationPartModelSelect(prefix, chunk, item);
        bindTranslationPartScrollSync(prefix, true);
    }

    function renderTranslationParts() {
        const list = document.getElementById('translation-part-list');
        const status = document.getElementById('translation-parts-status');
        if (!list || !status) return;

        const chunks = translationChunkDetails(selectedTranslation);
        if (!selectedTranslation) {
            list.innerHTML = '';
            renderTranslationPartDetail('translation', null, 'Valitse käännös.');
            status.textContent = 'Valitse käännös ja tarkastele käännöspalakohtainen kutsu ja vastaus.';
            return;
        }
        if (!chunks.length) {
            list.innerHTML = '<div style="color:var(--text-secondary); font-size:13px;">Tällä käännöksellä ei ole osalokia. Luo käännös uudelleen, niin kutsut ja vastaukset tallentuvat.</div>';
            renderTranslationPartDetail('translation', {
                prompt: 'Osakohtainen prompti ei ole tallessa tälle vanhalle käännökselle.',
                response: selectedTranslation.translated_text || 'Vastausta ei ole.'
            }, '');
            status.textContent = 'Osaloki puuttuu tältä käännökseltä.';
            return;
        }

        selectedTranslationPartIndex = Math.max(0, Math.min(selectedTranslationPartIndex, chunks.length - 1));
        list.innerHTML = chunks.map((chunk, index) => {
            const label = translationPartLabel(chunk, index);
            return `
                <button class="translation-part-item ${index === selectedTranslationPartIndex ? 'active' : ''}" data-translation-part-index="${index}">
                    ${escapeHtml(label.title)}
                    <small>${escapeHtml(label.meta)}</small>
                </button>
            `;
        }).join('');
        list.querySelectorAll('[data-translation-part-index]').forEach(button => {
            button.addEventListener('click', () => {
                selectedTranslationPartIndex = Number(button.dataset.translationPartIndex || 0);
                renderTranslationParts();
            });
        });
        const selected = chunks[selectedTranslationPartIndex] || {};
        renderTranslationPartDetail('translation', selected, 'Valitse käännösosa.');
        const label = translationPartLabel(selected, selectedTranslationPartIndex);
        status.textContent = `${label.title}: ${label.meta}.`;
    }

    function renderFinnishTranslationParts() {
        const list = document.getElementById('finnish-translation-part-list');
        const status = document.getElementById('finnish-translation-parts-status');
        if (!list || !status) return;

        const chunks = translationChunkDetails(selectedFinnishTranslation);
        if (!selectedFinnishTranslation) {
            renderTranslationReviewSummary(
                'finnish-translation-ai-check-summary',
                [],
                selectedFinnishTranslationPartIndex
            );
            list.innerHTML = '';
            renderTranslationPartDetail('finnish-translation', null, 'Valitse käännös.');
            status.textContent = 'Valitse käännös ja tarkastele käännöspalakohtainen kutsu ja vastaus.';
            return;
        }
        if (!chunks.length) {
            list.innerHTML = '<div style="color:var(--text-secondary); font-size:13px;">Tällä käännöksellä ei ole osalokia. Luo käännös uudelleen, niin kutsut ja vastaukset tallentuvat.</div>';
            renderTranslationPartDetail('finnish-translation', {
                prompt: 'Osakohtainen prompti ei ole tallessa tälle vanhalle käännökselle.',
                response: selectedFinnishTranslation.translated_text || 'Vastausta ei ole.'
            }, '');
            status.textContent = 'Osaloki puuttuu tältä käännökseltä.';
            return;
        }

        selectedFinnishTranslationPartIndex = Math.max(0, Math.min(selectedFinnishTranslationPartIndex, chunks.length - 1));
        list.innerHTML = chunks.map((chunk, index) => {
            const label = translationPartLabel(chunk, index);
            return `
                <button class="translation-part-item ${index === selectedFinnishTranslationPartIndex ? 'active' : ''}" data-finnish-translation-part-index="${index}">
                    ${escapeHtml(label.title)}
                    <small>${escapeHtml(label.meta)}</small>
                </button>
            `;
        }).join('');
        list.querySelectorAll('[data-finnish-translation-part-index]').forEach(button => {
            button.addEventListener('click', () => {
                selectedFinnishTranslationPartIndex = Number(button.dataset.finnishTranslationPartIndex || 0);
                renderFinnishTranslationParts();
                renderFinnishTranslationAiCheck();
            });
        });
        const selected = chunks[selectedFinnishTranslationPartIndex] || {};
        renderTranslationPartDetail('finnish-translation', selected, 'Valitse käännösosa.');
        const label = translationPartLabel(selected, selectedFinnishTranslationPartIndex);
        status.textContent = `${label.title}: ${label.meta}.`;
    }

    function setTranslationAiCheckText(key, value) {
        const element = document.getElementById(`finnish-translation-ai-check-${key}`);
        if (!element) return;
        element.value = value || '';
    }

    function selectedFinnishTranslationChunk() {
        const chunks = translationChunkDetails(selectedFinnishTranslation);
        if (!chunks.length) return null;
        selectedFinnishTranslationPartIndex = Math.max(0, Math.min(selectedFinnishTranslationPartIndex, chunks.length - 1));
        return chunks[selectedFinnishTranslationPartIndex] || null;
    }

    function renderFinnishTranslationAiCheck() {
        const list = document.getElementById('finnish-translation-ai-check-list');
        const status = document.getElementById('finnish-translation-ai-check-status');
        const runBtn = document.getElementById('finnish-translation-ai-check-run-btn');
        const runAllBtn = document.getElementById('finnish-translation-ai-check-run-all-btn');
        const batchBtn = document.getElementById('finnish-translation-ai-check-batch-btn');
        const cancelBtn = document.getElementById('finnish-translation-ai-check-cancel-btn');
        const acceptBtn = document.getElementById('finnish-translation-ai-check-accept-btn');
        const acceptSelectedBtn = document.getElementById('finnish-translation-ai-check-accept-selected-btn');
        const acceptAllBtn = document.getElementById('finnish-translation-ai-check-accept-all-btn');
        const downloadBtn = document.getElementById('finnish-translation-ai-check-download-btn');
        const bilingualBtn = document.getElementById('finnish-translation-ai-check-bilingual-btn');
        const modelSelect = document.getElementById('finnish-translation-ai-check-model');
        const checkedEl = document.getElementById('finnish-translation-ai-check-checked');
        if (modelSelect) modelSelect.disabled = finnishTranslationAiCheckAllRunning;
        if (cancelBtn) {
            cancelBtn.classList.toggle('hidden', !finnishTranslationReviewAllRunning);
            cancelBtn.disabled = !finnishTranslationReviewAllRunning;
            cancelBtn.textContent = 'Pysäytä tarkastus';
        }
        if (!list || !status) return;

        const chunks = translationChunkDetails(selectedFinnishTranslation);
        if (!selectedFinnishTranslation) {
            list.innerHTML = '';
            setTranslationAiCheckText('source', 'Valitse käännös.');
            setTranslationAiCheckText('current', 'Valitse käännös.');
            setTranslationAiCheckText('checked', '');
            setTranslationAiCheckText('notes', '');
            status.textContent = 'Valitse käännös ja sen jälkeen tarkistettava pala.';
            if (runBtn) runBtn.disabled = true;
            if (runAllBtn) runAllBtn.disabled = true;
            if (batchBtn) batchBtn.disabled = true;
            if (acceptBtn) acceptBtn.disabled = true;
            if (acceptSelectedBtn) acceptSelectedBtn.disabled = true;
            if (acceptAllBtn) acceptAllBtn.disabled = true;
            if (downloadBtn) downloadBtn.disabled = true;
            if (bilingualBtn) bilingualBtn.disabled = true;
            return;
        }
        if (!chunks.length) {
            renderTranslationReviewSummary(
                'finnish-translation-ai-check-summary',
                [],
                selectedFinnishTranslationPartIndex
            );
            list.innerHTML = '<div style="color:var(--text-secondary); font-size:13px;">Tällä käännöksellä ei ole osalokia. Luo käännös uudelleen, niin AI-tarkastus voidaan tehdä paloittain.</div>';
            setTranslationAiCheckText('source', '');
            setTranslationAiCheckText('current', selectedFinnishTranslation.translated_text || '');
            setTranslationAiCheckText('checked', '');
            setTranslationAiCheckText('notes', 'Osaloki puuttuu.');
            status.textContent = 'Osaloki puuttuu tältä käännökseltä.';
            if (runBtn) runBtn.disabled = true;
            if (runAllBtn) runAllBtn.disabled = true;
            if (batchBtn) batchBtn.disabled = true;
            if (acceptBtn) acceptBtn.disabled = true;
            if (acceptSelectedBtn) acceptSelectedBtn.disabled = true;
            if (acceptAllBtn) acceptAllBtn.disabled = true;
            if (downloadBtn) downloadBtn.disabled = true;
            if (bilingualBtn) bilingualBtn.disabled = true;
            return;
        }

        selectedFinnishTranslationPartIndex = Math.max(0, Math.min(selectedFinnishTranslationPartIndex, chunks.length - 1));
        renderTranslationReviewSummary(
            'finnish-translation-ai-check-summary',
            chunks,
            selectedFinnishTranslationPartIndex,
            index => {
                selectedFinnishTranslationPartIndex = index;
                renderFinnishTranslationParts();
                renderFinnishTranslationAiCheck();
            }
        );
        const checkedIndexes = chunks
            .map((chunk, index) => finnishTranslationAiCheckedText(chunk) ? index : null)
            .filter(index => index !== null);
        selectedFinnishTranslationAiCheckIndexes = new Set(
            Array.from(selectedFinnishTranslationAiCheckIndexes).filter(index => checkedIndexes.includes(index))
        );
        list.innerHTML = chunks.map((chunk, index) => {
            const label = translationPartLabel(chunk, index);
            const hasAiCheck = Boolean(finnishTranslationAiCheckedText(chunk));
            const checked = hasAiCheck ? ' · AI-tarkastettu' : '';
            const selectedForReplace = selectedFinnishTranslationAiCheckIndexes.has(index);
            return `
                <div class="translation-part-choice ${index === selectedFinnishTranslationPartIndex ? 'active' : ''}">
                    <label class="translation-part-checkbox" title="${hasAiCheck ? 'Valitse korvattavaksi' : 'Tarkasta osa ensin'}">
                        <input type="checkbox" data-finnish-ai-check-select-index="${index}" ${selectedForReplace ? 'checked' : ''} ${hasAiCheck ? '' : 'disabled'}>
                    </label>
                    <button class="translation-part-item ${index === selectedFinnishTranslationPartIndex ? 'active' : ''}" data-finnish-ai-check-part-index="${index}">
                        ${escapeHtml(label.title)}
                        <small>${escapeHtml(label.meta + checked)}</small>
                    </button>
                </div>
            `;
        }).join('');
        list.querySelectorAll('[data-finnish-ai-check-select-index]').forEach(input => {
            input.addEventListener('change', event => {
                const index = Number(event.target.dataset.finnishAiCheckSelectIndex || 0);
                if (event.target.checked) {
                    selectedFinnishTranslationAiCheckIndexes.add(index);
                } else {
                    selectedFinnishTranslationAiCheckIndexes.delete(index);
                }
                renderFinnishTranslationAiCheck();
            });
        });
        list.querySelectorAll('[data-finnish-ai-check-part-index]').forEach(button => {
            button.addEventListener('click', () => {
                selectedFinnishTranslationPartIndex = Number(button.dataset.finnishAiCheckPartIndex || 0);
                renderFinnishTranslationParts();
                renderFinnishTranslationAiCheck();
            });
        });

        const selected = chunks[selectedFinnishTranslationPartIndex] || {};
        const sections = translationPartSections(selected);
        const aiCheck = selected.ai_check && typeof selected.ai_check === 'object' ? selected.ai_check : {};
        setTranslationAiCheckText('source', sections.source || selected.source_text || '');
        setTranslationAiCheckText('current', selected.translation || '');
        setTranslationAiCheckText('checked', aiCheck.checked_translation || '');
        setTranslationAiCheckText('notes', aiCheck.notes || '');
        const label = translationPartLabel(selected, selectedFinnishTranslationPartIndex);
        status.textContent = aiCheck.checked_translation
            ? `${label.title}: AI-tarkastus valmiina.`
            : `${label.title}: valitse Tarkasta AI:lla.`;
        if (runBtn) runBtn.disabled = !translationModels.length || finnishTranslationAiCheckAllRunning;
        if (runAllBtn) runAllBtn.disabled = !translationModels.length || finnishTranslationAiCheckAllRunning;
        if (acceptBtn) acceptBtn.disabled = finnishTranslationAiCheckAllRunning || !String(checkedEl?.value || '').trim();
        if (acceptSelectedBtn) acceptSelectedBtn.disabled = finnishTranslationAiCheckAllRunning || !selectedFinnishTranslationAiCheckIndexes.size;
        if (acceptAllBtn) acceptAllBtn.disabled = finnishTranslationAiCheckAllRunning || !checkedIndexes.length;
        if (downloadBtn) downloadBtn.disabled = finnishTranslationAiCheckAllRunning || !checkedIndexes.length;
        if (bilingualBtn) bilingualBtn.disabled = finnishTranslationAiCheckAllRunning || !checkedIndexes.length;
        if (modelSelect && translationModels.length) {
            const currentValue = translationPartModelValue(selected, selectedFinnishTranslation);
            const selectedValueIsAvailable = translationModels.some(
                model => `${model.provider}:${model.model_name}` === modelSelect.value
            );
            if (!selectedValueIsAvailable && currentValue && translationModels.some(model => `${model.provider}:${model.model_name}` === currentValue)) {
                modelSelect.value = currentValue;
            }
        }
        if (batchBtn) {
            const selectedModel = String(modelSelect?.value || '').trim();
            const batchModel = preferredTranslationBatchModelValue(modelSelect);
            const selectedModelSupported = selectedModel && translationBatchModelSupported(selectedModel);
            batchBtn.disabled = finnishTranslationAiCheckAllRunning || !batchModel;
            batchBtn.title = !batchModel
                ? 'Eräajo vaatii käytettävissä olevan Gemini Flash -mallin.'
                : selectedModelSupported
                    ? 'Lähetä koko tarkastus Gemini Batch APIin. Tavoiteaika on enintään 24 tuntia.'
                    : showcaseDemoMode
                        ? 'Eräajo valitsee automaattisesti Gemini Flash -mallin.'
                        : 'Eräajo valitsee automaattisesti edullisen Gemini Flash -mallin.';
        }
    }

    async function runFinnishTranslationAiCheck() {
        const item = selectedFinnishTranslation;
        const chunk = selectedFinnishTranslationChunk();
        const status = document.getElementById('finnish-translation-ai-check-status');
        const runBtn = document.getElementById('finnish-translation-ai-check-run-btn');
        const modelEl = document.getElementById('finnish-translation-ai-check-model');
        const currentEl = document.getElementById('finnish-translation-ai-check-current');
        if (!item || !chunk) {
            alert('Valitse ensin käännös ja käännöspala.');
            return;
        }
        if (runBtn) runBtn.disabled = true;
        if (status) status.textContent = 'Tarkastetaan käännöspalaa AI:lla...';
        try {
            const res = await apiFetch(`/api/translations/${item.id}/chunks/${selectedFinnishTranslationPartIndex}/check`, {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    model: modelEl?.value || null,
                    current_translation: currentEl?.value || chunk.translation || '',
                    save: true
                })
            });
            const data = await res.json();
            if (!res.ok) throw new Error(data.detail || 'AI-tarkastus epäonnistui.');
            updateFinnishTranslationAiCheckChunk(selectedFinnishTranslationPartIndex, data);
            setTranslationAiCheckText('checked', data.checked_translation || '');
            setTranslationAiCheckText('notes', data.notes || '');
            if (status) status.textContent = 'AI-tarkastus valmis. Voit hyväksyä ehdotuksen tai poimia siitä osia käsin.';
            renderFinnishTranslationAiCheck();
        } catch (err) {
            if (status) status.textContent = err.message;
            alert('AI-tarkastus epäonnistui: ' + networkFailureMessage(err));
        } finally {
            if (runBtn) runBtn.disabled = false;
            loadUsage();
        }
    }

    async function runAllFinnishTranslationAiChecks() {
        const item = selectedFinnishTranslation;
        const chunks = translationChunkDetails(item);
        const status = document.getElementById('finnish-translation-ai-check-status');
        const runBtn = document.getElementById('finnish-translation-ai-check-run-btn');
        const runAllBtn = document.getElementById('finnish-translation-ai-check-run-all-btn');
        const acceptBtn = document.getElementById('finnish-translation-ai-check-accept-btn');
        const modelEl = document.getElementById('finnish-translation-ai-check-model');
        const selectedModel = modelEl?.value || null;
        const repeatReviewed = document.getElementById('finnish-translation-ai-check-repeat')?.checked === true;
        if (!item || !chunks.length) {
            alert('Valitse ensin käännös, jolla on palakohtainen loki.');
            return;
        }
        if (!translationModels.length) {
            alert('Tekstimalleja ei ole ladattu.');
            return;
        }
        const indexes = chunks
            .map((chunk, index) => (repeatReviewed || !finnishTranslationAiCheckedText(chunk)) ? index : null)
            .filter(index => index !== null);
        if (!indexes.length) {
            if (status) status.textContent = 'Koko käännös on jo tarkastettu. Valitse Tarkasta aiemmat uudelleen, jos haluat uuden kierroksen.';
            return;
        }

        finnishTranslationAiCheckAllRunning = true;
        finnishTranslationReviewAllRunning = true;
        finnishTranslationReviewCancelRequested = false;
        if (runBtn) runBtn.disabled = true;
        if (runAllBtn) runAllBtn.disabled = true;
        if (acceptBtn) acceptBtn.disabled = true;

        let completed = 0;
        const failures = [];
        let stopped = false;
        try {
            for (const index of indexes) {
                if (finnishTranslationReviewCancelRequested) {
                    stopped = true;
                    break;
                }
                const chunk = chunks[index];
                selectedFinnishTranslationPartIndex = index;
                renderFinnishTranslationAiCheck();
                if (status) {
                    status.textContent = `Tarkastetaan osaa ${index + 1}/${chunks.length}. Valmiina ${completed}/${indexes.length}.`;
                }
                try {
                    const controller = new AbortController();
                    finnishTranslationReviewController = controller;
                    const res = await apiFetch(`/api/translations/${item.id}/chunks/${index}/check`, {
                        method: 'POST',
                        headers: {'Content-Type': 'application/json'},
                        signal: controller.signal,
                        body: JSON.stringify({
                            model: selectedModel,
                            current_translation: chunk.translation || '',
                            save: true
                        })
                    });
                    const data = await res.json();
                    if (!res.ok) throw new Error(data.detail || 'AI-tarkastus epäonnistui.');
                    updateFinnishTranslationAiCheckChunk(index, data);
                    completed += 1;
                    setTranslationAiCheckText('checked', data.checked_translation || '');
                    setTranslationAiCheckText('notes', data.notes || '');
                } catch (err) {
                    if (finnishTranslationReviewCancelRequested && err?.name === 'AbortError') {
                        stopped = true;
                        break;
                    }
                    failures.push(`Osa ${index + 1}: ${networkFailureMessage(err)}`);
                } finally {
                    finnishTranslationReviewController = null;
                }
            }
        } finally {
            finnishTranslationAiCheckAllRunning = false;
            finnishTranslationReviewAllRunning = false;
            finnishTranslationReviewCancelRequested = false;
            finnishTranslationReviewController = null;
            renderFinnishTranslationAiCheck();
            if (runBtn) runBtn.disabled = !translationModels.length;
            if (runAllBtn) runAllBtn.disabled = !translationModels.length;
        }

        if (status) {
            status.textContent = stopped
                ? `AI-tarkastus pysäytettiin. Valmiina ${completed}/${indexes.length} osaa.`
                : failures.length
                ? `AI-tarkastus valmis osittain. Onnistui ${completed}/${indexes.length}. Epäonnistui: ${failures.slice(0, 4).join(' ')}${failures.length > 4 ? ' ...' : ''}`
                : `AI-tarkastus valmis (${completed}/${indexes.length} käsiteltävää osaa).`;
        }
        if (failures.length && !stopped) {
            alert(`AI-tarkastus valmistui osittain. Onnistui ${completed}/${indexes.length}.\n\n${failures.slice(0, 8).join('\n')}${failures.length > 8 ? '\n...' : ''}`);
        }
        loadUsage();
    }

    async function acceptFinnishTranslationAiCheck() {
        const checkedEl = document.getElementById('finnish-translation-ai-check-checked');
        const value = String(checkedEl?.value || '').trim();
        if (!value) {
            alert('Tarkastettua käännöstä ei ole.');
            return;
        }
        const responseEl = document.getElementById('finnish-translation-part-response');
        if (responseEl) responseEl.value = value;
        await saveTranslationPartCorrection('finnish-translation');
        const currentEl = document.getElementById('finnish-translation-ai-check-current');
        if (currentEl) currentEl.value = value;
        renderFinnishTranslationAiCheck();
    }

    async function replaceFinnishTranslationAiCheckChunks(mode) {
        const item = selectedFinnishTranslation;
        const chunks = translationChunkDetails(item);
        const status = document.getElementById('finnish-translation-ai-check-status');
        const runBtn = document.getElementById('finnish-translation-ai-check-run-btn');
        const runAllBtn = document.getElementById('finnish-translation-ai-check-run-all-btn');
        const acceptBtn = document.getElementById('finnish-translation-ai-check-accept-btn');
        const acceptSelectedBtn = document.getElementById('finnish-translation-ai-check-accept-selected-btn');
        const acceptAllBtn = document.getElementById('finnish-translation-ai-check-accept-all-btn');
        if (!item || !chunks.length) {
            alert('Valitse ensin käännös, jolla on palakohtainen loki.');
            return;
        }

        const candidateIndexes = mode === 'all'
            ? chunks.map((chunk, index) => finnishTranslationAiCheckedText(chunk) ? index : null).filter(index => index !== null)
            : Array.from(selectedFinnishTranslationAiCheckIndexes);
        const indexes = Array.from(new Set(candidateIndexes))
            .filter(index => finnishTranslationAiCheckedText(chunks[index]))
            .sort((a, b) => a - b);

        if (!indexes.length) {
            alert(mode === 'all'
                ? 'Yhtään AI-tarkastettua palaa ei ole vielä korvattavaksi.'
                : 'Valitse ensin vähintään yksi AI-tarkastettu pala.');
            return;
        }

        finnishTranslationAiCheckAllRunning = true;
        [runBtn, runAllBtn, acceptBtn, acceptSelectedBtn, acceptAllBtn].forEach(button => {
            if (button) button.disabled = true;
        });

        let completed = 0;
        const failures = [];
        try {
            for (const index of indexes) {
                const currentChunks = translationChunkDetails(selectedFinnishTranslation);
                const checkedText = finnishTranslationAiCheckedText(currentChunks[index]);
                if (!checkedText) {
                    failures.push(`Osa ${index + 1}: tarkastettu teksti puuttuu`);
                    continue;
                }
                selectedFinnishTranslationPartIndex = index;
                if (status) {
                    status.textContent = `Korvataan osaa ${index + 1}/${chunks.length}. Valmiina ${completed}/${indexes.length}.`;
                }
                try {
                    const res = await apiFetch(`/api/translations/${item.id}/chunks/${index}`, {
                        method: 'PATCH',
                        headers: {'Content-Type': 'application/json'},
                        body: JSON.stringify({ translation: checkedText })
                    });
                    const data = await res.json();
                    if (!res.ok) throw new Error(data.detail || 'Käännöspalan korvaus epäonnistui.');
                    selectedFinnishTranslation = data;
                    latestFinnishTranslationText = data.translated_text || '';
                    loadedTranslationWorkspaceTranslationId = null;
                    const itemIndex = currentFinnishTranslationHistory.findIndex(historyItem => String(historyItem.id) === String(data.id));
                    if (itemIndex >= 0) currentFinnishTranslationHistory[itemIndex] = data;
                    completed += 1;
                } catch (err) {
                    failures.push(`Osa ${index + 1}: ${networkFailureMessage(err)}`);
                }
            }

            populateFinnishTranslationReviewSelect();
            renderSelectedFinnishTranslationForReview();
            renderFinnishTranslationParts();
            await renderFinnishTranslationHistory();
        } finally {
            finnishTranslationAiCheckAllRunning = false;
            renderFinnishTranslationAiCheck();
        }

        if (status) {
            status.textContent = failures.length
                ? `Korvaus valmis osittain. Korvattiin ${completed}/${indexes.length}. Epäonnistui: ${failures.slice(0, 4).join(' ')}${failures.length > 4 ? ' ...' : ''}`
                : `Korvaus valmis. Korvattiin ${completed}/${indexes.length} palaa.`;
        }
        if (failures.length) {
            alert(`Korvaus valmistui osittain. Korvattiin ${completed}/${indexes.length}.\n\n${failures.slice(0, 8).join('\n')}${failures.length > 8 ? '\n...' : ''}`);
        }
    }

    async function rerunTranslationPart(prefix) {
        const isFinnish = prefix === 'finnish-translation';
        const item = isFinnish ? selectedFinnishTranslation : selectedTranslation;
        const index = isFinnish ? selectedFinnishTranslationPartIndex : selectedTranslationPartIndex;
        const promptEl = document.getElementById(`${prefix}-part-prompt`);
        const modelEl = document.getElementById(`${prefix}-part-rerun-model`);
        const statusEl = document.getElementById(`${prefix}-part-rerun-status`);
        const button = document.getElementById(`${prefix}-part-rerun-btn`);
        if (!item) {
            alert('Valitse ensin käännös.');
            return;
        }
        const chunks = translationChunkDetails(item);
        if (!chunks.length || !chunks[index]) {
            alert('Valitse ensin käännöspala.');
            return;
        }
        const prompt = promptEl?.value?.trim() || '';
        if (!prompt) {
            alert('Kutsu ei voi olla tyhjä.');
            return;
        }
        if (button) button.disabled = true;
        if (statusEl) statusEl.textContent = 'Ajetaan valittu osa uudelleen...';
        try {
            const res = await apiFetch(`/api/translations/${item.id}/chunks/${index}/rerun`, {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    model: modelEl?.value || null,
                    prompt,
                    preview: true
                })
            });
            const preview = await res.json();
            if (!res.ok) throw new Error(preview.detail || 'Käännöspalan uudelleenajo epäonnistui.');
            const proposedTranslation = String(preview.translation || '').trim();
            if (!proposedTranslation) {
                throw new Error('Uudelleenajo ei palauttanut käännöstekstiä.');
            }
            const warningText = preview.quality_warning
                ? `\n\nHuomautus: ${demoPriceSafeText(
                    preview.quality_warning,
                    'Ehdotuksen laadussa on tarkistettavaa.'
                )}`
                : '';
            const previewText = proposedTranslation.length > 1600
                ? `${proposedTranslation.slice(0, 1600)}\n\n[...]`
                : proposedTranslation;
            const accepted = confirm(`Uusi ehdotus:\n\n${previewText}${warningText}\n\nHyväksytäänkö ehdotus ja korvataan nykyinen pala?`);
            if (!accepted) {
                if (statusEl) statusEl.textContent = 'Uudelleenajo tehty esikatseluna. Nykyistä palaa ei muutettu.';
                return;
            }

            const saveRes = await apiFetch(`/api/translations/${item.id}/chunks/${index}`, {
                method: 'PATCH',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ translation: proposedTranslation })
            });
            const data = await saveRes.json();
            if (!saveRes.ok) throw new Error(data.detail || 'Uuden ehdotuksen tallennus epäonnistui.');

            if (isFinnish) {
                selectedFinnishTranslation = data;
                latestFinnishTranslationText = data.translated_text || '';
                loadedTranslationWorkspaceTranslationId = null;
                const itemIndex = currentFinnishTranslationHistory.findIndex(historyItem => String(historyItem.id) === String(data.id));
                if (itemIndex >= 0) currentFinnishTranslationHistory[itemIndex] = data;
                populateFinnishTranslationReviewSelect();
                renderSelectedFinnishTranslationForReview();
                renderFinnishTranslationParts();
                renderFinnishTranslationAiCheck();
                await renderFinnishTranslationHistory();
            } else {
                selectedTranslation = data;
                latestTranslationText = data.translated_text || '';
                const itemIndex = currentTranslationHistory.findIndex(historyItem => String(historyItem.id) === String(data.id));
                if (itemIndex >= 0) currentTranslationHistory[itemIndex] = data;
                populateTranslationReviewSelect();
                renderSelectedTranslationForReview();
                renderTranslationParts();
                await renderTranslationHistory();
            }
            if (statusEl) statusEl.textContent = 'Uusi ehdotus hyväksytty ja pala päivitetty.';
        } catch (err) {
            if (statusEl) statusEl.textContent = err.message;
            alert('Uudelleenajo epäonnistui: ' + err.message);
        } finally {
            if (button) button.disabled = false;
        }
    }

    async function saveTranslationPartCorrection(prefix) {
        const isFinnish = prefix === 'finnish-translation';
        const item = isFinnish ? selectedFinnishTranslation : selectedTranslation;
        const index = isFinnish ? selectedFinnishTranslationPartIndex : selectedTranslationPartIndex;
        const responseEl = document.getElementById(`${prefix}-part-response`);
        const statusEl = document.getElementById(`${prefix}-part-rerun-status`);
        const button = document.getElementById(`${prefix}-part-save-btn`);
        if (!item) {
            alert('Valitse ensin käännös.');
            return;
        }
        const chunks = translationChunkDetails(item);
        if (!chunks.length || !chunks[index]) {
            alert('Valitse ensin käännöspala.');
            return;
        }
        if (!responseEl) return;
        if (button) button.disabled = true;
        if (statusEl) statusEl.textContent = 'Tallennetaan palan korjausta...';
        try {
            const res = await apiFetch(`/api/translations/${item.id}/chunks/${index}`, {
                method: 'PATCH',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ translation: responseEl.value })
            });
            const data = await res.json();
            if (!res.ok) throw new Error(data.detail || 'Käännöspalan tallennus epäonnistui.');

            if (isFinnish) {
                selectedFinnishTranslation = data;
                latestFinnishTranslationText = data.translated_text || '';
                loadedTranslationWorkspaceTranslationId = null;
                const itemIndex = currentFinnishTranslationHistory.findIndex(historyItem => String(historyItem.id) === String(data.id));
                if (itemIndex >= 0) currentFinnishTranslationHistory[itemIndex] = data;
                populateFinnishTranslationReviewSelect();
                renderSelectedFinnishTranslationForReview();
                renderFinnishTranslationParts();
                renderFinnishTranslationAiCheck();
                await renderFinnishTranslationHistory();
            } else {
                selectedTranslation = data;
                latestTranslationText = data.translated_text || '';
                const itemIndex = currentTranslationHistory.findIndex(historyItem => String(historyItem.id) === String(data.id));
                if (itemIndex >= 0) currentTranslationHistory[itemIndex] = data;
                populateTranslationReviewSelect();
                renderSelectedTranslationForReview();
                renderTranslationParts();
                await renderTranslationHistory();
            }
            if (statusEl) statusEl.textContent = 'Palan korjaus tallennettu.';
        } catch (err) {
            if (statusEl) statusEl.textContent = err.message;
            alert('Tallennus epäonnistui: ' + err.message);
        } finally {
            if (button) button.disabled = false;
        }
    }

    function selectTranslationForReview(translationId) {
        const selected = currentTranslationHistory.find(item => String(item.id) === String(translationId));
        if (!selected) return;
        selectedTranslation = selected;
        selectedTranslationPartIndex = 0;
        latestTranslationText = selected.translated_text || '';
        populateTranslationReviewSelect();
        renderSelectedTranslationForReview();
        renderTranslationParts();
    }

    function selectFinnishTranslationForReview(translationId) {
        const selected = currentFinnishTranslationHistory.find(item => String(item.id) === String(translationId));
        if (!selected) return;
        const changed = !selectedFinnishTranslation || String(selectedFinnishTranslation.id) !== String(selected.id);
        selectedFinnishTranslation = selected;
        selectedFinnishTranslationPartIndex = 0;
        selectedFinnishTranslationAiCheckIndexes = new Set();
        if (changed) {
            translationWorkspaceFiles = [];
            selectedTranslationWorkspaceFilePath = '';
            loadedTranslationWorkspaceTranslationId = null;
            resetTranslationWorkspaceFileEditState();
        }
        latestFinnishTranslationText = selected.translated_text || '';
        populateFinnishTranslationReviewSelect();
        populateTranslationWorkspaceTranslationSelect();
        renderSelectedFinnishTranslationForReview();
        renderFinnishTranslationParts();
        renderFinnishTranslationAiCheck();
        void resumeTranslationReviewBatchJob('finnish');
    }

    function renderSelectedTranslationForReview() {
        const project = currentTranslationProject();
        const original = document.getElementById('translation-review-original');
        const textarea = document.getElementById('translation-review-text');
        const status = document.getElementById('translation-review-status');
        const output = document.getElementById('translation-output');
        const outputStatus = document.getElementById('translation-status');
        if (!original || !textarea || !status) return;

        if (!project || !selectedTranslation) {
            renderAlignedTranslationReview('translation', project, null, project ? 'Valitse käännös.' : 'Valitse käsikirjoitus.');
            status.textContent = 'Valitse käännös tarkastettavaksi.';
            if (output) output.value = '';
            if (outputStatus) outputStatus.textContent = project ? 'Valitse käännös.' : 'Valitse käsikirjoitus.';
            return;
        }

        latestTranslationText = selectedTranslation.translated_text || '';
        renderAlignedTranslationReview('translation', project, selectedTranslation, 'Valitse käännös.');
        status.textContent = `${selectedTranslation.target_language_label}, ${selectedTranslation.style_label}: ${translationStatusLabel(selectedTranslation.status)}.`;
        if (selectedTranslation.warnings) {
            status.textContent += ` Huomautukset: ${demoPriceSafeText(
                formatTranslationWarnings(selectedTranslation.warnings),
                'Käännöstyössä on huomautuksia.'
            )}`;
        }
        if (output) output.value = latestTranslationText;
        if (outputStatus) {
            outputStatus.textContent = `${selectedTranslation.target_language_label}, ${selectedTranslation.style_label}: ${translationStatusLabel(selectedTranslation.status)}`;
            if (selectedTranslation.warnings) outputStatus.textContent += ` Huomautukset: ${demoPriceSafeText(
                formatTranslationWarnings(selectedTranslation.warnings),
                'Käännöstyössä on huomautuksia.'
            )}`;
        }
    }

